    Picture,
    Audio,
    Video,
    Archive,
    Document,
    Other,
}

//! Background search: filters and sorts the index without blocking the window.

use crate::index::{Entry, Index};
use crate::query::{compile, Options};
use rayon::prelude::*;
use std::cmp::Ordering;
use std::collections::HashMap;
use std::sync::mpsc::{Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::Instant;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SortKey {
    Name,
    Path,
    Size,
    Extension,
    Modified,
    Created,
    Attributes,
}

#[derive(Clone, PartialEq, Debug)]
pub struct Request {
    pub text: String,
    pub opts: Options,
    pub sort: SortKey,
    pub ascending: bool,
    pub generation: u64,
    pub epoch: u64,
    pub serial: u64,
}

pub struct Reply {
    pub serial: u64,
    pub epoch: u64,
    pub ids: Vec<u32>,
    pub error: Option<String>,
    pub millis: u128,
}

pub fn spawn(index: Arc<RwLock<Index>>, rx: Receiver<Request>, tx: Sender<Reply>, ctx: eframe::egui::Context) {
    std::thread::spawn(move || {
        let mut name_order: Vec<u32> = Vec::new();
        let mut order_key = (u64::MAX, u64::MAX);
        while let Ok(mut req) = rx.recv() {
            while let Ok(newer) = rx.try_recv() {
                req = newer;
            }
            let start = Instant::now();
            let idx = index.read().unwrap();
            let key = (idx.epoch, idx.generation);
            if key != order_key {
                name_order = (0..idx.entries.len() as u32).collect();
                let entries = &idx.entries;
                name_order.par_sort_unstable_by(|a, b| by_name(&entries[*a as usize], &entries[*b as usize]));
                order_key = key;
            }
            let reply = match compile(&req.text, &req.opts) {
                Err(e) => Reply { serial: req.serial, epoch: idx.epoch, ids: Vec::new(), error: Some(e), millis: 0 },
                Ok(q) => {
                    let entries = &idx.entries;
                    let mut ids: Vec<u32> = name_order
                        .par_iter()
                        .copied()
                        .filter(|&i| {
                            let e = &entries[i as usize];
                            !e.deleted && (q.is_empty || q.matches(&idx, e))
                        })
                        .collect();
                    if q.dupe {
                        let mut counts: HashMap<&str, u32> = HashMap::new();
                        for &i in &ids {
                            *counts.entry(&entries[i as usize].fold).or_default() += 1;
                        }
                        ids.retain(|&i| counts[&*entries[i as usize].fold] > 1);
                    }
                    sort(&idx, &mut ids, req.sort, req.ascending);
                    if let Some(n) = q.count {
                        ids.truncate(n);
                    }
                    Reply { serial: req.serial, epoch: idx.epoch, ids, error: None, millis: start.elapsed().as_millis() }
                }
            };
            drop(idx);
            if tx.send(reply).is_err() {
                break;
            }
            ctx.request_repaint();
        }
    });
}

fn by_name(a: &Entry, b: &Entry) -> Ordering {
    a.fold.cmp(&b.fold).then_with(|| a.name.cmp(&b.name))
}

fn sort(idx: &Index, ids: &mut [u32], key: SortKey, ascending: bool) {
    let e = |i: &u32| &idx.entries[*i as usize];
    match key {
        SortKey::Name => {}
        SortKey::Path => ids.par_sort_by(|a, b| {
            let (x, y) = (e(a), e(b));
            idx.dir_fold(x).cmp(idx.dir_fold(y)).then_with(|| by_name(x, y))
        }),
        SortKey::Size => ids.par_sort_by(|a, b| {
            let size = |x: &Entry| if x.is_dir() { 0 } else { x.size.saturating_add(1) };
            size(e(a)).cmp(&size(e(b)))
        }),
        SortKey::Extension => ids.par_sort_by(|a, b| e(a).extension().to_lowercase().cmp(&e(b).extension().to_lowercase())),
        SortKey::Modified => ids.par_sort_by_key(|a| e(a).mtime),
        SortKey::Created => ids.par_sort_by_key(|a| e(a).ctime),
        SortKey::Attributes => ids.par_sort_by_key(|a| e(a).attrs),
    }
    if !ascending {
        ids.reverse();
    }
}

