                    e.size = if is_dir { NO_SIZE } else { md.len() };
                    e.mtime = mtime;
                    e.ctime = ctime;
                    e.attrs = attrs | if is_dir { ATTR_DIRECTORY } else { 0 };
                    if let Some((_, name)) = split(path) {
                        if *e.name != *name {
                            e.name = name.into();
                        }
                    }
                } else {
                    add_new(idx, lookup, key.0, path, is_dir, md.len(), attrs, mtime, ctime);
