//! The main window: menus, search box, filter, results and status bar.

use crate::filters::FILTERS;
use crate::index::{self, Index};
use crate::platform::{open, open_path, thousands};
use crate::query::Options;
use crate::scan::{self, Progress};
use crate::search::{self, Reply, Request, SortKey};
use crate::table::{Columns, RowAction, TableView};
use eframe::egui::{self, Color32, Key, RichText};
use std::collections::HashSet;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub const APP_NAME: &str = "Quickfind";

pub struct App {
    index: Arc<RwLock<Index>>,
    progress: Arc<Progress>,
    req_tx: Sender<Request>,
    rep_rx: Receiver<Reply>,
    query: String,
    opts: Options,
    filter: usize,
    sort: SortKey,
    ascending: bool,
    ids: Vec<u32>,
    ids_epoch: u64,
    error: Option<String>,
    millis: u128,
    serial: u64,
    shown_serial: u64,
    last_req: Option<Request>,
    last_sent: Instant,
    selected: HashSet<u32>,
    anchor: Option<usize>,
    cursor: Option<usize>,
    results_focus: bool,
    scroll_to: Option<usize>,
    columns: Columns,
    status_bar: bool,
    show_help: bool,
    show_about: bool,
    focus_search: bool,
    title: String,
    screenshot: Option<PathBuf>,
    frame: u32,
    shot_sent: bool,
    saved_generation: u64,
    message: Option<(String, Instant)>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        setup_style(&cc.egui_ctx);
        let index = Arc::new(RwLock::new(Index::default()));
        let progress = Arc::new(Progress::default());
        let (req_tx, req_rx) = channel();
        let (rep_tx, rep_rx) = channel();
        search::spawn(index.clone(), req_rx, rep_tx, cc.egui_ctx.clone());
        start_indexing(index.clone(), progress.clone(), cc.egui_ctx.clone(), screenshot.is_some());
        App {
            index,
            progress,
            req_tx,
            rep_rx,
            query: String::new(),
            opts: Options::default(),
            filter: 0,
            sort: SortKey::Name,
            ascending: true,
            ids: Vec::new(),
            ids_epoch: 0,
            error: None,
            millis: 0,
            serial: 0,
            shown_serial: 0,
            last_req: None,
            last_sent: Instant::now() - Duration::from_secs(10),
            selected: HashSet::new(),
            anchor: None,
            cursor: None,
            results_focus: false,
            scroll_to: None,
            columns: Columns::default(),
            status_bar: true,
            show_help: false,
            show_about: false,
            focus_search: true,
            title: String::new(),
            screenshot,
            frame: 0,
            shot_sent: false,
            saved_generation: 0,
            message: None,
        }
    }

    fn search_text(&self) -> String {
        let f = FILTERS[self.filter].1;
        match (f.is_empty(), self.query.trim().is_empty()) {
            (true, _) => self.query.clone(),
            (false, true) => f.to_string(),
            (false, false) => format!("{f} <{}>", self.query),
        }
    }

    fn pump_search(&mut self) {
        let (generation, epoch, ready) = {
            let idx = self.index.read().unwrap();
            (idx.generation, idx.epoch, idx.ready)
        };
        let req = Request {
            text: self.search_text(),
            opts: self.opts,
            sort: self.sort,
            ascending: self.ascending,
            generation,
            epoch,
            serial: 0,
        };
        let changed_query = match &self.last_req {
            None => true,
            Some(l) => l.text != req.text || l.opts != req.opts || l.sort != req.sort || l.ascending != req.ascending || l.epoch != req.epoch,
        };
        let changed_gen = self.last_req.as_ref().is_some_and(|l| l.generation != req.generation);
        let wait = if ready { Duration::from_millis(300) } else { Duration::from_millis(1000) };
        if changed_query || (changed_gen && self.last_sent.elapsed() >= wait) {
            if changed_query {
                self.selected.clear();
                self.anchor = None;
                self.cursor = None;
                self.scroll_to = Some(0);
            }
            self.serial += 1;
            let mut r = req.clone();
            r.serial = self.serial;
            let _ = self.req_tx.send(r);
            self.last_req = Some(req);
            self.last_sent = Instant::now();
        }
        while let Ok(rep) = self.rep_rx.try_recv() {
            if rep.serial >= self.shown_serial {
                self.shown_serial = rep.serial;
                self.ids = rep.ids;
                self.ids_epoch = rep.epoch;
                self.error = rep.error;
                self.millis = rep.millis;
            }
        }
    }

    fn entry_text(&self, id: u32, what: u8) -> String {
        let idx = self.index.read().unwrap();
        match idx.entries.get(id as usize) {
            Some(e) => match what {
                0 => idx.full_path(e),
                1 => e.name.to_string(),
                _ => idx.dir_path(e).to_string(),
            },
            None => String::new(),
        }
    }

    fn selected_paths(&self) -> Vec<String> {
        let idx = self.index.read().unwrap();
        self.ids
            .iter()
            .filter(|i| self.selected.contains(i))
            .filter_map(|i| idx.entries.get(*i as usize).map(|e| idx.full_path(e)))
            .collect()
    }

    fn apply(&mut self, ctx: &egui::Context, a: RowAction) {
        match a {
            RowAction::Click { row, id, ctrl, shift } => {
                self.results_focus = true;
                if shift {
                    let from = self.anchor.unwrap_or(row);
                    let (lo, hi) = (from.min(row), from.max(row));
                    if !ctrl {
                        self.selected.clear();
                    }
                    self.selected.extend(self.ids[lo..=hi].iter().copied());
                } else if ctrl {
                    if !self.selected.remove(&id) {
                        self.selected.insert(id);
                    }
                    self.anchor = Some(row);
                } else {
                    self.selected.clear();
                    self.selected.insert(id);
                    self.anchor = Some(row);
                }
                self.cursor = Some(row);
            }
            RowAction::Open(id) => open(&self.entry_text(id, 0)),
            RowAction::OpenPath(id) => open_path(&self.entry_text(id, 0)),
            RowAction::CopyFull(id) => {
                let mut paths = self.selected_paths();
                if paths.is_empty() {
                    paths.push(self.entry_text(id, 0));
                }
                ctx.copy_text(paths.join("\r\n"));
            }
            RowAction::CopyName(id) => ctx.copy_text(self.entry_text(id, 1)),
            RowAction::CopyPath(id) => ctx.copy_text(self.entry_text(id, 2)),
            RowAction::Sort(k) => {
                if self.sort == k {
                    self.ascending = !self.ascending;
                } else {
                    self.sort = k;
                    // Sizes and dates start with the largest/newest, names with A.
                    self.ascending = matches!(k, SortKey::Name | SortKey::Path | SortKey::Extension);
                }
            }
        }
    }

    fn move_cursor(&mut self, delta: i64, extend: bool) {
        if self.ids.is_empty() {
            return;
        }
        let last = self.ids.len() as i64 - 1;
        let cur = self.cursor.map(|c| c as i64).unwrap_or(-1);
        let next = (cur + delta).clamp(0, last) as usize;
        if extend {
            let from = self.anchor.unwrap_or(next);
            self.selected.clear();
            let (lo, hi) = (from.min(next), from.max(next));
            self.selected.extend(self.ids[lo..=hi].iter().copied());
        } else {
            self.selected.clear();
            self.selected.insert(self.ids[next]);
            self.anchor = Some(next);
        }
        self.cursor = Some(next);
        self.scroll_to = Some(next);
    }

    fn keyboard(&mut self, ctx: &egui::Context) {
        let typing = ctx.memory(|m| m.focused().is_some()) && !self.results_focus;
        let (down, up, pgdn, pgup, home, end, enter, shift, cmd) = ctx.input(|i| {
            (
                i.key_pressed(Key::ArrowDown),
                i.key_pressed(Key::ArrowUp),
                i.key_pressed(Key::PageDown),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::Enter),
                i.modifiers.shift,
                i.modifiers.command,
            )
        });
        let toggles = ctx.input_mut(|i| {
            [Key::I, Key::B, Key::U, Key::M, Key::R, Key::F, Key::A, Key::C]
                .map(|k| i.consume_key(egui::Modifiers::COMMAND, k))
        });
        if toggles[0] { self.opts.case = !self.opts.case; }
        if toggles[1] { self.opts.whole_word = !self.opts.whole_word; }
        if toggles[2] { self.opts.path = !self.opts.path; }
        if toggles[3] { self.opts.diacritics = !self.opts.diacritics; }
        if toggles[4] { self.opts.regex = !self.opts.regex; }
        if toggles[5] {
            self.focus_search = true;
            self.results_focus = false;
        }
        if self.results_focus && toggles[6] {
            self.selected = self.ids.iter().copied().collect();
        }
        if self.results_focus && toggles[7] {
            ctx.copy_text(self.selected_paths().join("\r\n"));
        }
        if typing && down {
            self.results_focus = true;
            ctx.memory_mut(|m| m.request_focus(egui::Id::new("results-focus")));
            self.move_cursor(if self.cursor.is_none() { 1 } else { 0 }, false);
            return;
        }
        if !self.results_focus {
            if enter && !self.ids.is_empty() {
                open(&self.entry_text(self.ids[self.cursor.unwrap_or(0)], 0));
            }
            return;
        }
        if down { self.move_cursor(1, shift); }
        if up {
            if self.cursor == Some(0) && !shift {
                self.results_focus = false;
                self.focus_search = true;
            } else {
                self.move_cursor(-1, shift);
            }
        }
        if pgdn { self.move_cursor(20, shift); }
        if pgup { self.move_cursor(-20, shift); }
        if home && !cmd { self.move_cursor(-(self.ids.len() as i64), shift); }
        if end && !cmd { self.move_cursor(self.ids.len() as i64, shift); }
        if enter {
            for p in self.selected_paths().into_iter().take(16) {
                open(&p);
            }
        }
    }

    fn menus(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        egui::menu::bar(ui, |ui| {
            ui.menu_button("File", |ui| {
                if ui.button("Export...").clicked() {
                    ui.close_menu();
                    self.export();
                }
                ui.separator();
                if ui.button("Exit").clicked() {
                    ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                }
            });
            ui.menu_button("Edit", |ui| {
                if ui.add(egui::Button::new("Copy Full Name to Clipboard").shortcut_text("Ctrl+C")).clicked() {
                    ctx.copy_text(self.selected_paths().join("\r\n"));
                    ui.close_menu();
                }
                if ui.add(egui::Button::new("Select All").shortcut_text("Ctrl+A")).clicked() {
                    self.selected = self.ids.iter().copied().collect();
                    ui.close_menu();
                }
            });
            ui.menu_button("View", |ui| {
                ui.checkbox(&mut self.columns.path, "Path");
                ui.checkbox(&mut self.columns.size, "Size");
                ui.checkbox(&mut self.columns.extension, "Extension");
                ui.checkbox(&mut self.columns.modified, "Date Modified");
                ui.checkbox(&mut self.columns.created, "Date Created");
                ui.checkbox(&mut self.columns.attributes, "Attributes");
                ui.separator();
                ui.checkbox(&mut self.status_bar, "Status Bar");
            });
            ui.menu_button("Search", |ui| {
                toggle(ui, &mut self.opts.case, "Match Case", "Ctrl+I");
                toggle(ui, &mut self.opts.whole_word, "Match Whole Words", "Ctrl+B");
                toggle(ui, &mut self.opts.path, "Match Path", "Ctrl+U");
                toggle(ui, &mut self.opts.diacritics, "Match Diacritics", "Ctrl+M");
                ui.separator();
                toggle(ui, &mut self.opts.regex, "Enable Regex", "Ctrl+R");
                ui.separator();
                for (i, (name, _)) in FILTERS.iter().enumerate() {
                    if ui.radio(self.filter == i, *name).clicked() {
                        self.filter = i;
                        ui.close_menu();
                    }
                }
            });
            ui.menu_button("Tools", |ui| {
                if ui.button("Rebuild Index").clicked() {
                    ui.close_menu();
                    rebuild(self.index.clone(), self.progress.clone(), ctx.clone());
                }
            });
            ui.menu_button("Help", |ui| {
                if ui.button("Search Syntax").clicked() {
                    self.show_help = true;
                    ui.close_menu();
                }
                if ui.button(format!("About {APP_NAME}")).clicked() {
                    self.show_about = true;
                    ui.close_menu();
                }
            });
        });
    }

    fn export(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .set_file_name("results.efu")
            .add_filter("File List", &["efu", "csv"])
            .save_file()
        else {
            return;
        };
        let idx = self.index.read().unwrap();
        let mut out = String::from("Filename,Size,Date Modified,Date Created,Attributes\r\n");
        for &i in &self.ids {
            let Some(e) = idx.entries.get(i as usize) else { continue };
            let size = if e.is_dir() { String::new() } else { e.size.to_string() };
            out.push_str(&format!("\"{}\",{},{},{},{}\r\n", idx.full_path(e).replace('"', "\"\""), size, e.mtime, e.ctime, e.attrs));
        }
        let msg = match std::fs::write(&path, out) {
            Ok(_) => format!("Exported {} results", thousands(self.ids.len() as u64)),
            Err(e) => format!("Export failed: {e}"),
        };
        self.message = Some((msg, Instant::now()));
    }

    fn status(&self, ui: &mut egui::Ui) {
        ui.horizontal(|ui| {
            let text = if let Some(err) = &self.error {
                err.clone()
            } else if self.selected.len() == 1 && self.ids.len() == 1 {
                "1 of 1 objects selected".to_string()
            } else if !self.selected.is_empty() {
                format!("{} objects selected", thousands(self.selected.len() as u64))
            } else {
                format!("{} objects", thousands(self.ids.len() as u64))
            };
            ui.label(RichText::new(text).color(Color32::from_gray(40)));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                ui.add_space(6.0);
                let mut flags = Vec::new();
                if self.opts.case { flags.push("CASE"); }
                if self.opts.whole_word { flags.push("WHOLE WORD"); }
                if self.opts.path { flags.push("PATH"); }
                if self.opts.diacritics { flags.push("DIACRITICS"); }
                if self.opts.regex { flags.push("REGEX"); }
                for f in flags.iter().rev() {
                    ui.label(RichText::new(*f).small().strong().color(Color32::from_gray(70)));
                }
                if self.progress.running.load(Ordering::Relaxed) {
                    let found = self.progress.found.load(Ordering::Relaxed);
                    let cur = self.progress.current.lock().map(|c| c.clone()).unwrap_or_default();
                    let short: String = cur.chars().take(60).collect();
                    ui.label(RichText::new(format!("Indexing {short}...  {} found", thousands(found))).color(Color32::from_gray(90)));
                } else if let Some((m, at)) = &self.message {
                    if at.elapsed() < Duration::from_secs(5) {
                        ui.label(m);
                    }
                }
            });
        });
    }
}

fn toggle(ui: &mut egui::Ui, v: &mut bool, label: &str, shortcut: &str) {
    let text = if *v { format!("✔  {label}") } else { format!("     {label}") };
    if ui.add(egui::Button::new(text).shortcut_text(shortcut)).clicked() {
        *v = !*v;
        ui.close_menu();
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.pump_search();
        self.keyboard(ctx);
        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }

        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin::symmetric(4, 2))).show(ctx, |ui| {
            self.menus(ui, ctx);
        });
        egui::TopBottomPanel::top("search")
            .frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin { left: 4, right: 4, top: 2, bottom: 4 }))
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        egui::ComboBox::from_id_salt("filter")
                            .width(110.0)
                            .selected_text(FILTERS[self.filter].0)
                            .show_ui(ui, |ui| {
                                for (i, (name, _)) in FILTERS.iter().enumerate() {
                                    ui.selectable_value(&mut self.filter, i, *name);
                                }
                            });
                        let edit = egui::TextEdit::singleline(&mut self.query)
                            .hint_text("Search...")
                            .desired_width(f32::INFINITY)
                            .margin(egui::Margin::symmetric(6, 4))
                            .id(egui::Id::new("search-box"));
                        let resp = ui.add(edit);
                        if self.focus_search {
                            resp.request_focus();
                            self.focus_search = false;
                        }
                        if resp.gained_focus() || resp.changed() {
                            self.results_focus = false;
                        }
                    });
                });
            });
        if self.status_bar {
            egui::TopBottomPanel::bottom("status")
                .frame(egui::Frame::new().fill(Color32::from_rgb(240, 240, 240)).inner_margin(egui::Margin::symmetric(6, 3)))
                .show(ctx, |ui| self.status(ui));
        }
        let mut actions = Vec::new();
        egui::CentralPanel::default().frame(egui::Frame::new().fill(Color32::WHITE)).show(ctx, |ui| {
            let idx = self.index.read().unwrap();
            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
            let view = TableView {
                index: &idx,
                ids,
                selected: &self.selected,
                sort: self.sort,
                ascending: self.ascending,
                columns: self.columns,
                scroll_to: self.scroll_to.take(),
            };
            view.show(ui, &mut actions);
        });
        for a in actions {
            self.apply(ctx, a);
        }
        if self.show_help {
            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.monospace(crate::help::SYNTAX);
                });
            });
        }
        if self.show_about {
            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.heading(APP_NAME);
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.label("Find files and folders by name, instantly.");
            });
        }
        self.autosave();
        self.screenshot_step(ctx);
        if self.progress.running.load(Ordering::Relaxed) {
            ctx.request_repaint_after(Duration::from_millis(250));
        }
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        if self.screenshot.is_some() {
            return;
        }
        let idx = self.index.read().unwrap();
        if idx.ready && idx.generation != self.saved_generation && !self.progress.running.load(Ordering::Relaxed) {
            let _ = index::save(&idx);
        }
    }
}

impl App {
    fn autosave(&mut self) {
        // Saved by the indexing thread after each full scan; here only after live changes.
        if self.screenshot.is_some() || self.frame % 600 != 0 {
            self.frame = self.frame.wrapping_add(if self.screenshot.is_some() { 0 } else { 1 });
            return;
        }
        self.frame = self.frame.wrapping_add(1);
    }

    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frame += 1;
        ctx.request_repaint();
        if self.frame >= 120 && !self.shot_sent {
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
            self.shot_sent = true;
        }
        let shot = ctx.input(|i| {
            i.raw.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                let _ = buf.save(&path);
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

fn setup_style(ctx: &egui::Context) {
    let mut fonts = egui::FontDefinitions::default();
    for (name, file) in [("ui", "segoeui.ttf"), ("sym", "seguisym.ttf")] {
        let p = PathBuf::from(std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into())).join("Fonts").join(file);
        if let Ok(bytes) = std::fs::read(p) {
            fonts.font_data.insert(name.into(), Arc::new(egui::FontData::from_owned(bytes)));
            let fam = fonts.families.entry(egui::FontFamily::Proportional).or_default();
            if name == "ui" { fam.insert(0, name.into()); } else { fam.push(name.into()); }
        }
    }
    ctx.set_fonts(fonts);
    ctx.set_visuals(egui::Visuals::light());
    ctx.style_mut(|s| {
        s.text_styles.insert(egui::TextStyle::Body, egui::FontId::proportional(13.0));
        s.text_styles.insert(egui::TextStyle::Button, egui::FontId::proportional(13.0));
        s.spacing.item_spacing = egui::vec2(6.0, 2.0);
        s.visuals.selection.bg_fill = Color32::from_rgb(204, 232, 255);
        s.visuals.selection.stroke = egui::Stroke::new(1.0, Color32::from_rgb(20, 20, 20));
        s.visuals.panel_fill = Color32::WHITE;
        s.visuals.widgets.hovered.weak_bg_fill = Color32::from_rgb(229, 243, 255);
        s.visuals.extreme_bg_color = Color32::WHITE;
    });
}

/// Load the saved index (instant results), then refresh it from disk and watch for changes.
fn start_indexing(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context, screenshot: bool) {
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        let loaded = index::load();
        let had_cache = loaded.is_some();
        if let Some(mut l) = loaded {
            let mut live = index.write().unwrap();
            l.epoch = live.epoch + 1;
            *live = l;
            drop(live);
            ctx.request_repaint();
            if screenshot {
                return;
            }
            refresh(&index, &progress, &roots, &ctx);
        } else {
            scan::scan_into(&index, &roots, &progress);
            ctx.request_repaint();
            if screenshot {
                return;
            }
        }
        let _ = had_cache;
        let _ = index::save(&index.read().unwrap());
        crate::watch::start(index.clone(), roots, ctx.clone());
        // Save live changes now and then.
        let mut saved = index.read().unwrap().generation;
        loop {
            std::thread::sleep(Duration::from_secs(600));
            let idx = index.read().unwrap();
            if idx.generation != saved && !progress.running.load(Ordering::Relaxed) {
                let _ = index::save(&idx);
                saved = idx.generation;
            }
        }
    });
}

/// Scan into a fresh index, then swap it in whole.
fn refresh(index: &Arc<RwLock<Index>>, progress: &Arc<Progress>, roots: &[String], ctx: &egui::Context) {
    let fresh = Arc::new(RwLock::new(Index::default()));
    scan::scan_into(&fresh, roots, progress);
    let mut new_index = std::mem::take(&mut *fresh.write().unwrap());
    let mut live = index.write().unwrap();
    new_index.epoch = live.epoch + 1;
    new_index.generation = live.generation + 1;
    *live = new_index;
    drop(live);
    ctx.request_repaint();
}

fn rebuild(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context) {
    if progress.running.load(Ordering::Relaxed) {
        return;
    }
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        refresh(&index, &progress, &roots, &ctx);
        let _ = index::save(&index.read().unwrap());
    });
}

toolUseResult.content:
//! The main window: menus, search box, filter, results and status bar.

use crate::filters::FILTERS;
use crate::index::{self, Index};
use crate::platform::{open, open_path, thousands};
use crate::query::Options;
use crate::scan::{self, Progress};
use crate::search::{self, Reply, Request, SortKey};
use crate::table::{Columns, RowAction, TableView};
use eframe::egui::{self, Color32, Key, RichText};
use std::collections::HashSet;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub const APP_NAME: &str = "Quickfind";

pub struct App {
    index: Arc<RwLock<Index>>,
    progress: Arc<Progress>,
    req_tx: Sender<Request>,
    rep_rx: Receiver<Reply>,
    query: String,
    opts: Options,
    filter: usize,
    sort: SortKey,
    ascending: bool,
    ids: Vec<u32>,
    ids_epoch: u64,
    error: Option<String>,
    millis: u128,
    serial: u64,
    shown_serial: u64,
    last_req: Option<Request>,
    last_sent: Instant,
    selected: HashSet<u32>,
    anchor: Option<usize>,
    cursor: Option<usize>,
    results_focus: bool,
    scroll_to: Option<usize>,
    columns: Columns,
    status_bar: bool,
    show_help: bool,
    show_about: bool,
    focus_search: bool,
    title: String,
    screenshot: Option<PathBuf>,
    frame: u32,
    shot_sent: bool,
    saved_generation: u64,
    message: Option<(String, Instant)>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        setup_style(&cc.egui_ctx);
        let index = Arc::new(RwLock::new(Index::default()));
        let progress = Arc::new(Progress::default());
        let (req_tx, req_rx) = channel();
        let (rep_tx, rep_rx) = channel();
        search::spawn(index.clone(), req_rx, rep_tx, cc.egui_ctx.clone());
        start_indexing(index.clone(), progress.clone(), cc.egui_ctx.clone(), screenshot.is_some());
        App {
            index,
            progress,
            req_tx,
            rep_rx,
            query: String::new(),
            opts: Options::default(),
            filter: 0,
            sort: SortKey::Name,
            ascending: true,
            ids: Vec::new(),
            ids_epoch: 0,
            error: None,
            millis: 0,
            serial: 0,
            shown_serial: 0,
            last_req: None,
            last_sent: Instant::now() - Duration::from_secs(10),
            selected: HashSet::new(),
            anchor: None,
            cursor: None,
            results_focus: false,
            scroll_to: None,
            columns: Columns::default(),
            status_bar: true,
            show_help: false,
            show_about: false,
            focus_search: true,
            title: String::new(),
            screenshot,
            frame: 0,
            shot_sent: false,
            saved_generation: 0,
            message: None,
        }
    }

    fn search_text(&self) -> String {
        let f = FILTERS[self.filter].1;
        match (f.is_empty(), self.query.trim().is_empty()) {
            (true, _) => self.query.clone(),
            (false, true) => f.to_string(),
            (false, false) => format!("{f} <{}>", self.query),
        }
    }

    fn pump_search(&mut self) {
        let (generation, epoch, ready) = {
            let idx = self.index.read().unwrap();
            (idx.generation, idx.epoch, idx.ready)
        };
        let req = Request {
            text: self.search_text(),
            opts: self.opts,
            sort: self.sort,
            ascending: self.ascending,
            generation,
            epoch,
            serial: 0,
        };
        let changed_query = match &self.last_req {
            None => true,
            Some(l) => l.text != req.text || l.opts != req.opts || l.sort != req.sort || l.ascending != req.ascending || l.epoch != req.epoch,
        };
        let changed_gen = self.last_req.as_ref().is_some_and(|l| l.generation != req.generation);
        let wait = if ready { Duration::from_millis(300) } else { Duration::from_millis(1000) };
        if changed_query || (changed_gen && self.last_sent.elapsed() >= wait) {
            if changed_query {
                self.selected.clear();
                self.anchor = None;
                self.cursor = None;
                self.scroll_to = Some(0);
            }
            self.serial += 1;
            let mut r = req.clone();
            r.serial = self.serial;
            let _ = self.req_tx.send(r);
            self.last_req = Some(req);
            self.last_sent = Instant::now();
        }
        while let Ok(rep) = self.rep_rx.try_recv() {
            if rep.serial >= self.shown_serial {
                self.shown_serial = rep.serial;
                self.ids = rep.ids;
                self.ids_epoch = rep.epoch;
                self.error = rep.error;
                self.millis = rep.millis;
            }
        }
    }

    fn entry_text(&self, id: u32, what: u8) -> String {
        let idx = self.index.read().unwrap();
        match idx.entries.get(id as usize) {
            Some(e) => match what {
                0 => idx.full_path(e),
                1 => e.name.to_string(),
                _ => idx.dir_path(e).to_string(),
            },
            None => String::new(),
        }
    }

    fn selected_paths(&self) -> Vec<String> {
        let idx = self.index.read().unwrap();
        self.ids
            .iter()
            .filter(|i| self.selected.contains(i))
            .filter_map(|i| idx.entries.get(*i as usize).map(|e| idx.full_path(e)))
            .collect()
    }

    fn apply(&mut self, ctx: &egui::Context, a: RowAction) {
        match a {
            RowAction::Click { row, id, ctrl, shift } => {
                self.results_focus = true;
                if shift {
                    let from = self.anchor.unwrap_or(row);
                    let (lo, hi) = (from.min(row), from.max(row));
                    if !ctrl {
                        self.selected.clear();
                    }
                    self.selected.extend(self.ids[lo..=hi].iter().copied());
                } else if ctrl {
                    if !self.selected.remove(&id) {
                        self.selected.insert(id);
                    }
                    self.anchor = Some(row);
                } else {
                    self.selected.clear();
                    self.selected.insert(id);
                    self.anchor = Some(row);
                }
                self.cursor = Some(row);
            }
            RowAction::Open(id) => open(&self.entry_text(id, 0)),
            RowAction::OpenPath(id) => open_path(&self.entry_text(id, 0)),
            RowAction::CopyFull(id) => {
                let mut paths = self.selected_paths();
                if paths.is_empty() {
                    paths.push(self.entry_text(id, 0));
                }
                ctx.copy_text(paths.join("\r\n"));
            }
            RowAction::CopyName(id) => ctx.copy_text(self.entry_text(id, 1)),
            RowAction::CopyPath(id) => ctx.copy_text(self.entry_text(id, 2)),
            RowAction::Sort(k) => {
                if self.sort == k {
                    self.ascending = !self.ascending;
                } else {
                    self.sort = k;
                    // Sizes and dates start with the largest/newest, names with A.
                    self.ascending = matches!(k, SortKey::Name | SortKey::Path | SortKey::Extension);
                }
            }
        }
    }

    fn move_cursor(&mut self, delta: i64, extend: bool) {
        if self.ids.is_empty() {
            return;
        }
        let last = self.ids.len() as i64 - 1;
        let cur = self.cursor.map(|c| c as i64).unwrap_or(-1);
        let next = (cur + delta).clamp(0, last) as usize;
        if extend {
            let from = self.anchor.unwrap_or(next);
            self.selected.clear();
            let (lo, hi) = (from.min(next), from.max(next));
            self.selected.extend(self.ids[lo..=hi].iter().copied());
        } else {
            self.selected.clear();
            self.selected.insert(self.ids[next]);
            self.anchor = Some(next);
        }
        self.cursor = Some(next);
        self.scroll_to = Some(next);
    }

    fn keyboard(&mut self, ctx: &egui::Context) {
        let typing = ctx.memory(|m| m.focused().is_some()) && !self.results_focus;
        let (down, up, pgdn, pgup, home, end, enter, shift, cmd) = ctx.input(|i| {
            (
                i.key_pressed(Key::ArrowDown),
                i.key_pressed(Key::ArrowUp),
                i.key_pressed(Key::PageDown),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::Enter),
                i.modifiers.shift,
                i.modifiers.command,
            )
        });
        let toggles = ctx.input_mut(|i| {
            [Key::I, Key::B, Key::U, Key::M, Key::R, Key::F, Key::A, Key::C]
                .map(|k| i.consume_key(egui::Modifiers::COMMAND, k))
        });
        if toggles[0] { self.opts.case = !self.opts.case; }
        if toggles[1] { self.opts.whole_word = !self.opts.whole_word; }
        if toggles[2] { self.opts.path = !self.opts.path; }
        if toggles[3] { self.opts.diacritics = !self.opts.diacritics; }
        if toggles[4] { self.opts.regex = !self.opts.regex; }
        if toggles[5] {
            self.focus_search = true;
            self.results_focus = false;
        }
        if self.results_focus && toggles[6] {
            self.selected = self.ids.iter().copied().collect();
        }
        if self.results_focus && toggles[7] {
            ctx.copy_text(self.selected_paths().join("\r\n"));
        }
        if typing && down {
            self.results_focus = true;
            ctx.memory_mut(|m| m.request_focus(egui::Id::new("results-focus")));
            self.move_cursor(if self.cursor.is_none() { 1 } else { 0 }, false);
            return;
        }
        if !self.results_focus {
            if enter && !self.ids.is_empty() {
                open(&self.entry_text(self.ids[self.cursor.unwrap_or(0)], 0));
            }
            return;
        }
        if down { self.move_cursor(1, shift); }
        if up {
            if self.cursor == Some(0) && !shift {
                self.results_focus = false;
                self.focus_search = true;
            } else {
                self.move_cursor(-1, shift);
            }
        }
        if pgdn { self.move_cursor(20, shift); }
        if pgup { self.move_cursor(-20, shift); }
        if home && !cmd { self.move_cursor(-(self.ids.len() as i64), shift); }
        if end && !cmd { self.move_cursor(self.ids.len() as i64, shift); }
        if enter {
            for p in self.selected_paths().into_iter().take(16) {
                open(&p);
            }
        }
    }

    fn menus(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        egui::menu::bar(ui, |ui| {
            ui.menu_button("File", |ui| {
                if ui.button("Export...").clicked() {
                    ui.close_menu();
                    self.export();
                }
                ui.separator();
                if ui.button("Exit").clicked() {
                    ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                }
            });
            ui.menu_button("Edit", |ui| {
                if ui.add(egui::Button::new("Copy Full Name to Clipboard").shortcut_text("Ctrl+C")).clicked() {
                    ctx.copy_text(self.selected_paths().join("\r\n"));
                    ui.close_menu();
                }
                if ui.add(egui::Button::new("Select All").shortcut_text("Ctrl+A")).clicked() {
                    self.selected = self.ids.iter().copied().collect();
                    ui.close_menu();
                }
            });
            ui.menu_button("View", |ui| {
                ui.checkbox(&mut self.columns.path, "Path");
                ui.checkbox(&mut self.columns.size, "Size");
                ui.checkbox(&mut self.columns.extension, "Extension");
                ui.checkbox(&mut self.columns.modified, "Date Modified");
                ui.checkbox(&mut self.columns.created, "Date Created");
                ui.checkbox(&mut self.columns.attributes, "Attributes");
                ui.separator();
                ui.checkbox(&mut self.status_bar, "Status Bar");
            });
            ui.menu_button("Search", |ui| {
                toggle(ui, &mut self.opts.case, "Match Case", "Ctrl+I");
                toggle(ui, &mut self.opts.whole_word, "Match Whole Words", "Ctrl+B");
                toggle(ui, &mut self.opts.path, "Match Path", "Ctrl+U");
                toggle(ui, &mut self.opts.diacritics, "Match Diacritics", "Ctrl+M");
                ui.separator();
                toggle(ui, &mut self.opts.regex, "Enable Regex", "Ctrl+R");
                ui.separator();
                for (i, (name, _)) in FILTERS.iter().enumerate() {
                    if ui.radio(self.filter == i, *name).clicked() {
                        self.filter = i;
                        ui.close_menu();
                    }
                }
            });
            ui.menu_button("Tools", |ui| {
                if ui.button("Rebuild Index").clicked() {
                    ui.close_menu();
                    rebuild(self.index.clone(), self.progress.clone(), ctx.clone());
                }
            });
            ui.menu_button("Help", |ui| {
                if ui.button("Search Syntax").clicked() {
                    self.show_help = true;
                    ui.close_menu();
                }
                if ui.button(format!("About {APP_NAME}")).clicked() {
                    self.show_about = true;
                    ui.close_menu();
                }
            });
        });
    }

    fn export(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .set_file_name("results.efu")
            .add_filter("File List", &["efu", "csv"])
            .save_file()
        else {
            return;
        };
        let idx = self.index.read().unwrap();
        let mut out = String::from("Filename,Size,Date Modified,Date Created,Attributes\r\n");
        for &i in &self.ids {
            let Some(e) = idx.entries.get(i as usize) else { continue };
            let size = if e.is_dir() { String::new() } else { e.size.to_string() };
            out.push_str(&format!("\"{}\",{},{},{},{}\r\n", idx.full_path(e).replace('"', "\"\""), size, e.mtime, e.ctime, e.attrs));
        }
        let msg = match std::fs::write(&path, out) {
            Ok(_) => format!("Exported {} results", thousands(self.ids.len() as u64)),
            Err(e) => format!("Export failed: {e}"),
        };
        self.message = Some((msg, Instant::now()));
    }

    fn status(&self, ui: &mut egui::Ui) {
        ui.horizontal(|ui| {
            let text = if let Some(err) = &self.error {
                err.clone()
            } else if self.selected.len() == 1 && self.ids.len() == 1 {
                "1 of 1 objects selected".to_string()
            } else if !self.selected.is_empty() {
                format!("{} objects selected", thousands(self.selected.len() as u64))
            } else {
                format!("{} objects", thousands(self.ids.len() as u64))
            };
            ui.label(RichText::new(text).color(Color32::from_gray(40)));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                ui.add_space(6.0);
                let mut flags = Vec::new();
                if self.opts.case { flags.push("CASE"); }
                if self.opts.whole_word { flags.push("WHOLE WORD"); }
                if self.opts.path { flags.push("PATH"); }
                if self.opts.diacritics { flags.push("DIACRITICS"); }
                if self.opts.regex { flags.push("REGEX"); }
                for f in flags.iter().rev() {
                    ui.label(RichText::new(*f).small().strong().color(Color32::from_gray(70)));
                }
                if self.progress.running.load(Ordering::Relaxed) {
                    let found = self.progress.found.load(Ordering::Relaxed);
                    let cur = self.progress.current.lock().map(|c| c.clone()).unwrap_or_default();
                    let short: String = cur.chars().take(60).collect();
                    ui.label(RichText::new(format!("Indexing {short}...  {} found", thousands(found))).color(Color32::from_gray(90)));
                } else if let Some((m, at)) = &self.message {
                    if at.elapsed() < Duration::from_secs(5) {
                        ui.label(m);
                    }
                }
            });
        });
    }
}

fn toggle(ui: &mut egui::Ui, v: &mut bool, label: &str, shortcut: &str) {
    let text = if *v { format!("✔  {label}") } else { format!("     {label}") };
    if ui.add(egui::Button::new(text).shortcut_text(shortcut)).clicked() {
        *v = !*v;
        ui.close_menu();
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.pump_search();
        self.keyboard(ctx);
        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }

        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin::symmetric(4, 2))).show(ctx, |ui| {
            self.menus(ui, ctx);
        });
        egui::TopBottomPanel::top("search")
            .frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin { left: 4, right: 4, top: 2, bottom: 4 }))
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        egui::ComboBox::from_id_salt("filter")
                            .width(110.0)
                            .selected_text(FILTERS[self.filter].0)
                            .show_ui(ui, |ui| {
                                for (i, (name, _)) in FILTERS.iter().enumerate() {
                                    ui.selectable_value(&mut self.filter, i, *name);
                                }
                            });
                        let edit = egui::TextEdit::singleline(&mut self.query)
                            .hint_text("Search...")
                            .desired_width(f32::INFINITY)
                            .margin(egui::Margin::symmetric(6, 4))
                            .id(egui::Id::new("search-box"));
                        let resp = ui.add(edit);
                        if self.focus_search {
                            resp.request_focus();
                            self.focus_search = false;
                        }
                        if resp.gained_focus() || resp.changed() {
                            self.results_focus = false;
                        }
                    });
                });
            });
        if self.status_bar {
            egui::TopBottomPanel::bottom("status")
                .frame(egui::Frame::new().fill(Color32::from_rgb(240, 240, 240)).inner_margin(egui::Margin::symmetric(6, 3)))
                .show(ctx, |ui| self.status(ui));
        }
        let mut actions = Vec::new();
        egui::CentralPanel::default().frame(egui::Frame::new().fill(Color32::WHITE)).show(ctx, |ui| {
            let idx = self.index.read().unwrap();
            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
            let view = TableView {
                index: &idx,
                ids,
                selected: &self.selected,
                sort: self.sort,
                ascending: self.ascending,
                columns: self.columns,
                scroll_to: self.scroll_to.take(),
            };
            view.show(ui, &mut actions);
        });
        for a in actions {
            self.apply(ctx, a);
        }
        if self.show_help {
            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.monospace(crate::help::SYNTAX);
                });
            });
        }
        if self.show_about {
            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.heading(APP_NAME);
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.label("Find files and folders by name, instantly.");
            });
        }
        self.autosave();
        self.screenshot_step(ctx);
        if self.progress.running.load(Ordering::Relaxed) {
            ctx.request_repaint_after(Duration::from_millis(250));
        }
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        if self.screenshot.is_some() {
            return;
        }
        let idx = self.index.read().unwrap();
        if idx.ready && idx.generation != self.saved_generation && !self.progress.running.load(Ordering::Relaxed) {
            let _ = index::save(&idx);
        }
    }
}

impl App {
    fn autosave(&mut self) {
        // Saved by the indexing thread after each full scan; here only after live changes.
        if self.screenshot.is_some() || self.frame % 600 != 0 {
            self.frame = self.frame.wrapping_add(if self.screenshot.is_some() { 0 } else { 1 });
            return;
        }
        self.frame = self.frame.wrapping_add(1);
    }

    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frame += 1;
        ctx.request_repaint();
        if self.frame >= 120 && !self.shot_sent {
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
            self.shot_sent = true;
        }
        let shot = ctx.input(|i| {
            i.raw.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                let _ = buf.save(&path);
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

fn setup_style(ctx: &egui::Context) {
    let mut fonts = egui::FontDefinitions::default();
    for (name, file) in [("ui", "segoeui.ttf"), ("sym", "seguisym.ttf")] {
        let p = PathBuf::from(std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into())).join("Fonts").join(file);
        if let Ok(bytes) = std::fs::read(p) {
            fonts.font_data.insert(name.into(), Arc::new(egui::FontData::from_owned(bytes)));
            let fam = fonts.families.entry(egui::FontFamily::Proportional).or_default();
            if name == "ui" { fam.insert(0, name.into()); } else { fam.push(name.into()); }
        }
    }
    ctx.set_fonts(fonts);
    ctx.set_visuals(egui::Visuals::light());
    ctx.style_mut(|s| {
        s.text_styles.insert(egui::TextStyle::Body, egui::FontId::proportional(13.0));
        s.text_styles.insert(egui::TextStyle::Button, egui::FontId::proportional(13.0));
        s.spacing.item_spacing = egui::vec2(6.0, 2.0);
        s.visuals.selection.bg_fill = Color32::from_rgb(204, 232, 255);
        s.visuals.selection.stroke = egui::Stroke::new(1.0, Color32::from_rgb(20, 20, 20));
        s.visuals.panel_fill = Color32::WHITE;
        s.visuals.widgets.hovered.weak_bg_fill = Color32::from_rgb(229, 243, 255);
        s.visuals.extreme_bg_color = Color32::WHITE;
    });
}

/// Load the saved index (instant results), then refresh it from disk and watch for changes.
fn start_indexing(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context, screenshot: bool) {
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        let loaded = index::load();
        let had_cache = loaded.is_some();
        if let Some(mut l) = loaded {
            let mut live = index.write().unwrap();
            l.epoch = live.epoch + 1;
            *live = l;
            drop(live);
            ctx.request_repaint();
            if screenshot {
                return;
            }
            refresh(&index, &progress, &roots, &ctx);
        } else {
            scan::scan_into(&index, &roots, &progress);
            ctx.request_repaint();
            if screenshot {
                return;
            }
        }
        let _ = had_cache;
        let _ = index::save(&index.read().unwrap());
        crate::watch::start(index.clone(), roots, ctx.clone());
        // Save live changes now and then.
        let mut saved = index.read().unwrap().generation;
        loop {
            std::thread::sleep(Duration::from_secs(600));
            let idx = index.read().unwrap();
            if idx.generation != saved && !progress.running.load(Ordering::Relaxed) {
                let _ = index::save(&idx);
                saved = idx.generation;
            }
        }
    });
}

/// Scan into a fresh index, then swap it in whole.
fn refresh(index: &Arc<RwLock<Index>>, progress: &Arc<Progress>, roots: &[String], ctx: &egui::Context) {
    let fresh = Arc::new(RwLock::new(Index::default()));
    scan::scan_into(&fresh, roots, progress);
    let mut new_index = std::mem::take(&mut *fresh.write().unwrap());
    let mut live = index.write().unwrap();
    new_index.epoch = live.epoch + 1;
    new_index.generation = live.generation + 1;
    *live = new_index;
    drop(live);
    ctx.request_repaint();
}

fn rebuild(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context) {
    if progress.running.load(Ordering::Relaxed) {
        return;
    }
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        refresh(&index, &progress, &roots, &ctx);
        let _ = index::save(&index.read().unwrap());
    });
}

