593	/// Load the saved index (instant results), then refresh it from disk and watch for changes.
594	fn start_indexing(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context, screenshot: bool) {
595	    std::thread::spawn(move || {
596	        let roots = scan::fixed_drives();
597	        if let Some(mut l) = index::load() {
598	            let mut live = index.write().unwrap();
599	            l.epoch = live.epoch + 1;
600	            *live = l;
601	            drop(live);
602	            ctx.request_repaint();
603	            if screenshot {
604	                return;
605	            }
606	            refresh(&index, &progress, &roots, &ctx);
607	        } else {
608	            scan::scan_into(&index, &roots, &progress);
609	            ctx.request_repaint();
610	            if screenshot {
611	                return;
612	            }
613	        }
614	        let _ = index::save(&index.read().unwrap());
615	        crate::watch::start(index.clone(), roots, ctx.clone());
616	        // Save live changes now and then.
617	        let mut saved = index.read().unwrap().generation;
618	        loop {
619	            std::thread::sleep(Duration::from_secs(600));
620	            let idx = index.read().unwrap();
621	            if idx.generation != saved && !progress.running.load(Ordering::Relaxed) {
622	                let _ = index::save(&idx);
623	                saved = idx.generation;
624	            }
625	        }
626	    });
627	}
