629	/// Scan into a fresh index, then swap it in whole.
630	fn refresh(index: &Arc<RwLock<Index>>, progress: &Arc<Progress>, roots: &[String], ctx: &egui::Context) {
631	    let fresh = Arc::new(RwLock::new(Index::default()));
632	    scan::scan_into(&fresh, roots, progress);
633	    let mut new_index = std::mem::take(&mut *fresh.write().unwrap());
634	    let mut live = index.write().unwrap();
635	    new_index.epoch = live.epoch + 1;
