impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.pump_search();
        self.keyboard(ctx);
        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }

        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin::symmetric(4, 2))).show(ctx, |ui| {
            self.menus(ui, ctx);
        });
        egui::TopBottomPanel::top("search")
            .frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin { left: 4, right: 4, top: 2, bottom: 4 }))
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        egui::ComboBox::from_id_salt("filter")
                            .width(110.0)
                            .selected_text(FILTERS[self.filter].0)
                            .show_ui(ui, |ui| {
                                for (i, (name, _)) in FILTERS.iter().enumerate() {
                                    ui.selectable_value(&mut self.filter, i, *name);
                                }
                            });
                        let edit = egui::TextEdit::singleline(&mut self.query)
                            .hint_text("Search...")
                            .desired_width(f32::INFINITY)
                            .margin(egui::Margin::symmetric(6, 4))
                            .id(egui::Id::new("search-box"));
                        let resp = ui.add(edit);
                        if self.focus_search {
                            resp.request_focus();
                            self.focus_search = false;
                        }
                        if resp.gained_focus() || resp.changed() {
                            self.results_focus = false;
                        }
                    });
                });
            });
        if self.status_bar {
            egui::TopBottomPanel::bottom("status")
                .frame(egui::Frame::new().fill(Color32::from_rgb(240, 240, 240)).inner_margin(egui::Margin::symmetric(6, 3)))
                .show(ctx, |ui| self.status(ui));
        }
        let mut actions = Vec::new();
        egui::CentralPanel::default().frame(egui::Frame::new().fill(Color32::WHITE)).show(ctx, |ui| {
            let idx = self.index.read().unwrap();
            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
            let view = TableView {
                index: &idx,
                ids,
                selected: &self.selected,
                sort: self.sort,
                ascending: self.ascending,
                columns: self.columns,
                scroll_to: self.scroll_to.take(),
            };
            view.show(ui, &mut actions);
        });
        for a in actions {
            self.apply(ctx, a);
        }
        if self.show_help {
            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.monospace(crate::help::SYNTAX);
                });
            });
        }
        if self.show_about {
            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.heading(APP_NAME);
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.label("Find files and folders by name, instantly.");
            });
        }
        self.screenshot_step(ctx);
        if self.progress.running.load(Ordering::Relaxed) {
            ctx.request_repaint_after(Duration::from_millis(250));
        }
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        if self.screenshot.is_some() {
            return;
        }
        let idx = self.index.read().unwrap();
        if idx.ready && idx.generation != self.saved_generation && !self.progress.running.load(Ordering::Relaxed) {
            let _ = index::save(&idx);
        }
    }
}

impl App {
    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frame += 1;
        ctx.request_repaint();
        if self.frame >= 120 && !self.shot_sent {
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
            self.shot_sent = true;
        }
        let shot = ctx.input(|i| {
            i.raw.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                let _ = buf.save(&path);
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

fn setup_style(ctx: &egui::Context) {
    let mut fonts = egui::FontDefinitions::default();
    for (name, file) in [("ui", "segoeui.ttf"), ("sym", "seguisym.ttf")] {
        let p = PathBuf::from(std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into())).join("Fonts").join(file);
        if let Ok(bytes) = std::fs::read(p) {
            fonts.font_data.insert(name.into(), Arc::new(egui::FontData::from_owned(bytes)));
            let fam = fonts.families.entry(egui::FontFamily::Proportional).or_default();
            if name == "ui" { fam.insert(0, name.into()); } else { fam.push(name.into()); }
        }
    }
    ctx.set_fonts(fonts);
    ctx.set_visuals(egui::Visuals::light());
    ctx.style_mut(|s| {
        s.text_styles.insert(egui::TextStyle::Body, egui::FontId::proportional(13.0));
        s.text_styles.insert(egui::TextStyle::Button, egui::FontId::proportional(13.0));
        s.spacing.item_spacing = egui::vec2(6.0, 2.0);
        s.visuals.selection.bg_fill = Color32::from_rgb(204, 232, 255);
        s.visuals.selection.stroke = egui::Stroke::new(1.0_f32, Color32::from_rgb(20, 20, 20));
        s.visuals.panel_fill = Color32::WHITE;
        s.visuals.widgets.hovered.weak_bg_fill = Color32::from_rgb(229, 243, 255);
        s.visuals.extreme_bg_color = Color32::WHITE;
    });
}

/// Load the saved index (instant results), then refresh it from disk and watch for changes.
fn start_indexing(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context, screenshot: bool) {
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        if let Some(mut l) = index::load() {
            let mut live = index.write().unwrap();
            l.epoch = live.epoch + 1;
            *live = l;
            drop(live);
            ctx.request_repaint();
            if screenshot {
                return;
            }
            refresh(&index, &progress, &roots, &ctx);
        } else {
            scan::scan_into(&index, &roots, &progress);
            ctx.request_repaint();
            if screenshot {
                return;
            }
        }
        let _ = index::save(&index.read().unwrap());
        crate::watch::start(index.clone(), roots, ctx.clone());
        // Save live changes now and then.
        let mut saved = index.read().unwrap().generation;
        loop {
            std::thread::sleep(Duration::from_secs(600));
            let idx = index.read().unwrap();
            if idx.generation != saved && !progress.running.load(Ordering::Relaxed) {
                let _ = index::save(&idx);
                saved = idx.generation;
            }
        }
    });
}

/// Scan into a fresh index, then swap it in whole.
fn refresh(index: &Arc<RwLock<Index>>, progress: &Arc<Progress>, roots: &[String], ctx: &egui::Context) {
    let fresh = Arc::new(RwLock::new(Index::default()));
    scan::scan_into(&fresh, roots, progress);
    let mut new_index = std::mem::take(&mut *fresh.write().unwrap());
    let mut live = index.write().unwrap();
    new_index.epoch = live.epoch + 1;
    new_index.generation = live.generation + 1;
    *live = new_index;
    drop(live);
    ctx.request_repaint();
}

fn rebuild(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context) {
    if progress.running.load(Ordering::Relaxed) {
        return;
    }
    std::thread::spawn(move || {
        let roots = scan::fixed_drives();
        refresh(&index, &progress, &roots, &ctx);
        let _ = index::save(&index.read().unwrap());
    });
}

