/// `*` = any run of characters, `?` = exactly one character (UTF-8 aware).
fn glob(p: &[u8], s: &[u8]) -> bool {
    let char_len = |b: u8| match b {
        b if b < 0x80 => 1,
        b if b >= 0xF0 => 4,
        b if b >= 0xE0 => 3,
        _ => 2,
    };
