1	//! The in-memory file index: every file and folder on the indexed drives.
2	
3	use std::io::{BufReader, BufWriter, Read, Write};
4	use std::path::PathBuf;
5	
6	pub const NONE: u32 = u32::MAX;
7	pub const NO_SIZE: u64 = u64::MAX;
8	pub const ATTR_DIRECTORY: u32 = 0x10;
9	pub const ATTR_REPARSE: u32 = 0x400;
10	
11	#[derive(Clone)]
12	pub struct Entry {
13	    pub name: Box<str>,
14	    /// Lower-case name with accents removed, used for the default search.
15	    pub fold: Box<str>,
16	    /// Folder (path id) this entry lives in, or NONE for drive roots.
17	    pub dir: u32,
18	    /// Path id of this entry when it is a folder.
19	    pub self_dir: u32,
20	    pub size: u64,
21	    pub mtime: u64,
22	    pub ctime: u64,
23	    pub attrs: u32,
24	    pub children: u32,
25	    pub deleted: bool,
26	}
27	
28	impl Entry {
29	    pub fn is_dir(&self) -> bool {
30	        self.self_dir != NONE || self.attrs & ATTR_DIRECTORY != 0
31	    }
32	    pub fn extension(&self) -> &str {
33	        if self.is_dir() {
34	            return "";
35	        }
36	        match self.name.rfind('.') {
37	            Some(p) if p > 0 => &self.name[p + 1..],
38	            _ => "",
39	        }
40	    }
41	}
42	
43	#[derive(Clone, Default)]
44	pub struct Dir {
45	    pub path: Box<str>,
46	    pub fold: Box<str>,
47	    pub entry: u32,
48	}
49	
50	#[derive(Default)]
51	pub struct Index {
52	    pub entries: Vec<Entry>,
53	    pub dirs: Vec<Dir>,
54	    /// Bumped whenever entries change.
55	    pub generation: u64,
56	    /// Bumped whenever the whole index is replaced (ids become invalid).
57	    pub epoch: u64,
58	    pub ready: bool,
59	}
60	
61	impl Index {
62	    pub fn dir_path(&self, e: &Entry) -> &str {
63	        if e.dir == NONE {
64	            return "";
65	        }
