//! The in-memory file index: every file and folder on the indexed drives.

use std::io::{BufReader, BufWriter, Read, Write};
use std::path::PathBuf;

pub const NONE: u32 = u32::MAX;
pub const NO_SIZE: u64 = u64::MAX;
pub const ATTR_DIRECTORY: u32 = 0x10;
pub const ATTR_REPARSE: u32 = 0x400;

#[derive(Clone)]
pub struct Entry {
    pub name: Box<str>,
    /// Lower-case name with accents removed, used for the default search.
    pub fold: Box<str>,
    /// Folder (path id) this entry lives in, or NONE for drive roots.
    pub dir: u32,
    /// Path id of this entry when it is a folder.
    pub self_dir: u32,
    pub size: u64,
    pub mtime: u64,
    pub ctime: u64,
    pub attrs: u32,
    pub children: u32,
    pub deleted: bool,
}

impl Entry {
    pub fn is_dir(&self) -> bool {
        self.self_dir != NONE || self.attrs & ATTR_DIRECTORY != 0
    }
    pub fn extension(&self) -> &str {
        if self.is_dir() {
            return "";
        }
        match self.name.rfind('.') {
            Some(p) if p > 0 => &self.name[p + 1..],
            _ => "",
        }
