        self.self_dir != NONE || self.attrs & ATTR_DIRECTORY != 0
    }
    /// Shift name offsets after moving a local name block into the index's.
    pub fn rebase(&mut self, by: u32) {
        self.name_off += by;
        self.fold_off += by;
    }
}

