    pub fn move_into(&mut self, idx: &mut Index) {
        for (id, path) in self.dirs.drain(..) {
            idx.set_dir(id, path);
        }
        let base = idx.names.len() as u32;
        idx.names.push_str(&self.names);
        self.names.clear();
        for e in self.entries.iter_mut() {
            e.rebase(base);
        }
        idx.entries.append(&mut self.entries);
    }
}

