//! The in-memory file index: every file and folder on the indexed drives.

use std::io::{BufReader, BufWriter, Read, Write};
use std::path::PathBuf;

pub const NONE: u32 = u32::MAX;
pub const NO_SIZE: u64 = u64::MAX;
pub const ATTR_DIRECTORY: u32 = 0x10;
pub const ATTR_REPARSE: u32 = 0x400;

#[derive(Clone)]
pub struct Entry {
    pub name: Box<str>,
    /// Lower-case name with accents removed, used for the default search.
    pub fold: Box<str>,
    /// Folder (path id) this entry lives in, or NONE for drive roots.
    pub dir: u32,
    /// Path id of this entry when it is a folder.
    pub self_dir: u32,
    pub size: u64,
    pub mtime: u64,
    pub ctime: u64,
    pub attrs: u32,
    pub children: u32,
    pub deleted: bool,
}

impl Entry {
    pub fn is_dir(&self) -> bool {
        self.self_dir != NONE || self.attrs & ATTR_DIRECTORY != 0
    }
    pub fn extension(&self) -> &str {
        if self.is_dir() {
            return "";
        }
        match self.name.rfind('.') {
            Some(p) if p > 0 => &self.name[p + 1..],
            _ => "",
        }
    }
}

#[derive(Clone, Default)]
pub struct Dir {
    pub path: Box<str>,
    pub fold: Box<str>,
    pub entry: u32,
}

#[derive(Default)]
pub struct Index {
    pub entries: Vec<Entry>,
    pub dirs: Vec<Dir>,
    /// Bumped whenever entries change.
    pub generation: u64,
    /// Bumped whenever the whole index is replaced (ids become invalid).
    pub epoch: u64,
    pub ready: bool,
}

impl Index {
    pub fn dir_path(&self, e: &Entry) -> &str {
        if e.dir == NONE {
            return "";
        }
        self.dirs.get(e.dir as usize).map(|d| &*d.path).unwrap_or("")
    }
    pub fn dir_fold(&self, e: &Entry) -> &str {
        if e.dir == NONE {
            return "";
        }
        self.dirs.get(e.dir as usize).map(|d| &*d.fold).unwrap_or("")
    }
    pub fn full_path(&self, e: &Entry) -> String {
        join(self.dir_path(e), &e.name)
    }
    pub fn live_count(&self) -> usize {
        self.entries.iter().filter(|e| !e.deleted).count()
    }
    pub fn set_dir(&mut self, id: u32, path: String) {
        let i = id as usize;
        if self.dirs.len() <= i {
            self.dirs.resize(i + 1, Dir { entry: NONE, ..Default::default() });
        }
        let fold = fold(&path).into_boxed_str();
        self.dirs[i].path = path.into_boxed_str();
        self.dirs[i].fold = fold;
    }
    /// Link folder records to their entries and count children.
    pub fn finalize(&mut self) {
        for d in self.dirs.iter_mut() {
            d.entry = NONE;
        }
        for (i, e) in self.entries.iter().enumerate() {
            if e.self_dir != NONE && (e.self_dir as usize) < self.dirs.len() {
                self.dirs[e.self_dir as usize].entry = i as u32;
            }
        }
        let mut counts = vec![0u32; self.dirs.len()];
        for e in self.entries.iter().filter(|e| !e.deleted) {
            if e.dir != NONE && (e.dir as usize) < counts.len() {
                counts[e.dir as usize] += 1;
            }
        }
        for e in self.entries.iter_mut() {
            if e.self_dir != NONE {
                e.children = counts.get(e.self_dir as usize).copied().unwrap_or(0);
            }
        }
        self.generation += 1;
    }
}

pub fn join(dir: &str, name: &str) -> String {
    if dir.is_empty() {
        name.to_string()
    } else if dir.ends_with('\\') {
        format!("{dir}{name}")
    } else {
        format!("{dir}\\{name}")
    }
}

/// Lower-case and strip common accents ("Café" -> "cafe").
pub fn fold(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c.is_ascii() {
            out.push(c.to_ascii_lowercase());
        } else {
            for l in c.to_lowercase() {
                out.push(strip_accent(l));
            }
        }
    }
    out
}

/// Strip accents but keep case.
pub fn strip_accents(s: &str) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii() {
                c
            } else if c.is_uppercase() {
                let l: String = c.to_lowercase().collect();
                let b = l.chars().next().map(strip_accent).unwrap_or(c);
                b.to_uppercase().next().unwrap_or(c)
            } else {
                strip_accent(c)
            }
        })
        .collect()
}

pub fn strip_accent(c: char) -> char {
    match c {
        'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' | 'ă' | 'ą' => 'a',
        'ç' | 'ć' | 'ĉ' | 'ċ' | 'č' => 'c',
        'ď' | 'đ' => 'd',
        'è' | 'é' | 'ê' | 'ë' | 'ē' | 'ĕ' | 'ė' | 'ę' | 'ě' => 'e',
        'ĝ' | 'ğ' | 'ġ' | 'ģ' => 'g',
        'ĥ' | 'ħ' => 'h',
        'ì' | 'í' | 'î' | 'ï' | 'ĩ' | 'ī' | 'ĭ' | 'į' | 'ı' => 'i',
        'ĵ' => 'j',
        'ķ' => 'k',
        'ĺ' | 'ļ' | 'ľ' | 'ŀ' | 'ł' => 'l',
        'ñ' | 'ń' | 'ņ' | 'ň' => 'n',
        'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' | 'ŏ' | 'ő' => 'o',
        'ŕ' | 'ŗ' | 'ř' => 'r',
        'ś' | 'ŝ' | 'ş' | 'š' => 's',
        'ţ' | 'ť' | 'ŧ' => 't',
        'ù' | 'ú' | 'û' | 'ü' | 'ũ' | 'ū' | 'ŭ' | 'ů' | 'ű' | 'ų' => 'u',
        'ŵ' => 'w',
        'ý' | 'ÿ' | 'ŷ' => 'y',
        'ź' | 'ż' | 'ž' => 'z',
        other => other,
    }
}

// ---------------------------------------------------------------- cache file

const MAGIC: &[u8; 8] = b"QFIX0001";

pub fn cache_path() -> PathBuf {
    let base = std::env::var_os("LOCALAPPDATA")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir);
    base.join("Quickfind").join("index.bin")
}

pub fn save(index: &Index) -> std::io::Result<()> {
    let path = cache_path();
    if let Some(p) = path.parent() {
        std::fs::create_dir_all(p)?;
    }
    let tmp = path.with_extension("tmp");
    {
        let mut w = BufWriter::with_capacity(1 << 20, std::fs::File::create(&tmp)?);
        w.write_all(MAGIC)?;
        w.write_all(&(index.dirs.len() as u32).to_le_bytes())?;
        for d in &index.dirs {
            write_str(&mut w, &d.path)?;
        }
        let live: Vec<&Entry> = index.entries.iter().collect();
        w.write_all(&(live.len() as u32).to_le_bytes())?;
        for e in live {
            w.write_all(&e.dir.to_le_bytes())?;
            w.write_all(&e.self_dir.to_le_bytes())?;
            w.write_all(&e.size.to_le_bytes())?;
            w.write_all(&e.mtime.to_le_bytes())?;
            w.write_all(&e.ctime.to_le_bytes())?;
            w.write_all(&e.attrs.to_le_bytes())?;
            w.write_all(&[e.deleted as u8])?;
            write_str(&mut w, &e.name)?;
        }
        w.flush()?;
    }
    std::fs::rename(tmp, path)
}

fn write_str(w: &mut impl Write, s: &str) -> std::io::Result<()> {
    let b = s.as_bytes();
    let n = b.len().min(u16::MAX as usize);
    w.write_all(&(n as u16).to_le_bytes())?;
    w.write_all(&b[..n])
}

pub fn load() -> Option<Index> {
    let f = std::fs::File::open(cache_path()).ok()?;
    let mut r = BufReader::with_capacity(1 << 20, f);
    let mut magic = [0u8; 8];
    r.read_exact(&mut magic).ok()?;
    if &magic != MAGIC {
        return None;
    }
    let mut index = Index::default();
    let nd = read_u32(&mut r)?;
    let mut paths = Vec::with_capacity(nd as usize);
    for _ in 0..nd {
        paths.push(read_str(&mut r)?);
    }
    use rayon::prelude::*;
    index.dirs = paths
        .into_par_iter()
        .map(|p| Dir { fold: fold(&p).into_boxed_str(), path: p.into_boxed_str(), entry: NONE })
        .collect();
    let ne = read_u32(&mut r)?;
    let mut raw = Vec::with_capacity(ne as usize);
    for _ in 0..ne {
        let dir = read_u32(&mut r)?;
        let self_dir = read_u32(&mut r)?;
        let size = read_u64(&mut r)?;
        let mtime = read_u64(&mut r)?;
        let ctime = read_u64(&mut r)?;
        let attrs = read_u32(&mut r)?;
        let mut del = [0u8; 1];
        r.read_exact(&mut del).ok()?;
        let name = read_str(&mut r)?;
        raw.push((dir, self_dir, size, mtime, ctime, attrs, del[0] != 0, name));
    }
    index.entries = raw
        .into_par_iter()
        .map(|(dir, self_dir, size, mtime, ctime, attrs, deleted, name)| Entry {
            fold: fold(&name).into_boxed_str(),
            name: name.into_boxed_str(),
            dir,
            self_dir,
            size,
            mtime,
            ctime,
            attrs,
            children: 0,
            deleted,
        })
        .collect();
    index.finalize();
    index.ready = true;
    Some(index)
}

fn read_u32(r: &mut impl Read) -> Option<u32> {
    let mut b = [0u8; 4];
    r.read_exact(&mut b).ok()?;
    Some(u32::from_le_bytes(b))
}
fn read_u64(r: &mut impl Read) -> Option<u64> {
    let mut b = [0u8; 8];
    r.read_exact(&mut b).ok()?;
    Some(u64::from_le_bytes(b))
}
fn read_str(r: &mut impl Read) -> Option<String> {
    let mut b = [0u8; 2];
    r.read_exact(&mut b).ok()?;
    let n = u16::from_le_bytes(b) as usize;
    let mut v = vec![0u8; n];
    r.read_exact(&mut v).ok()?;
    String::from_utf8(v).ok()
}

//! Walks the drives with several threads and fills an index as it goes.

use crate::index::{fold, Entry, Index, ATTR_DIRECTORY, ATTR_REPARSE, NONE, NO_SIZE};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex, RwLock};
use std::time::Duration;

#[derive(Default)]
pub struct Progress {
    pub running: AtomicBool,
    pub found: AtomicU64,
    pub current: Mutex<String>,
}

struct Shared {
    queue: Mutex<Vec<(String, u32)>>,
    pending: AtomicUsize,
    next_dir: AtomicU32,
}

const FLUSH_AT: usize = 20_000;

/// Fixed drives such as "C:".
pub fn fixed_drives() -> Vec<String> {
    #[cfg(windows)]
    {
        use windows_sys::Win32::Storage::FileSystem::{GetDriveTypeW, GetLogicalDrives};
        let mut out = Vec::new();
        let mask = unsafe { GetLogicalDrives() };
        for i in 0..26u32 {
            if mask & (1 << i) == 0 {
                continue;
            }
            let letter = (b'A' + i as u8) as char;
            let root: Vec<u16> = format!("{letter}:\\").encode_utf16().chain([0]).collect();
            // DRIVE_FIXED = 3
            if unsafe { GetDriveTypeW(root.as_ptr()) } == 3 {
                out.push(format!("{letter}:"));
            }
        }
        out
    }
    #[cfg(not(windows))]
    {
        vec!["/".to_string()]
    }
}

/// Scan `roots` into `target` (which should start empty). Entries appear in the
/// index while the scan runs, so searching works before it finishes.
pub fn scan_into(target: &Arc<RwLock<Index>>, roots: &[String], progress: &Progress) {
    progress.running.store(true, Ordering::SeqCst);
    progress.found.store(0, Ordering::SeqCst);
    let shared = Shared { queue: Mutex::new(Vec::new()), pending: AtomicUsize::new(0), next_dir: AtomicU32::new(0) };
    {
        let mut idx = target.write().unwrap();
        let mut q = shared.queue.lock().unwrap();
        for r in roots {
            let id = shared.next_dir.fetch_add(1, Ordering::SeqCst);
            idx.entries.push(Entry {
                name: r.clone().into_boxed_str(),
                fold: fold(r).into_boxed_str(),
                dir: NONE,
                self_dir: id,
                size: NO_SIZE,
                mtime: 0,
                ctime: 0,
                attrs: ATTR_DIRECTORY,
                children: 0,
                deleted: false,
            });
            q.push((r.clone(), id));
            shared.pending.fetch_add(1, Ordering::SeqCst);
        }
        idx.generation += 1;
    }
    let threads = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4).clamp(2, 8);
    std::thread::scope(|s| {
        for _ in 0..threads {
            s.spawn(|| worker(target, &shared, progress));
        }
    });
    {
        let mut idx = target.write().unwrap();
        idx.finalize();
        idx.ready = true;
    }
    progress.running.store(false, Ordering::SeqCst);
}

#[derive(Default)]
struct Local {
    entries: Vec<Entry>,
    dirs: Vec<(u32, String)>,
}

fn flush(target: &Arc<RwLock<Index>>, local: &mut Local) {
    if local.entries.is_empty() && local.dirs.is_empty() {
        return;
    }
    let mut idx = target.write().unwrap();
    for (id, path) in local.dirs.drain(..) {
        idx.set_dir(id, path);
    }
    idx.entries.append(&mut local.entries);
    idx.generation += 1;
}

fn worker(target: &Arc<RwLock<Index>>, shared: &Shared, progress: &Progress) {
    let mut local = Local::default();
    loop {
        let item = shared.queue.lock().unwrap().pop();
        let Some((path, id)) = item else {
            if shared.pending.load(Ordering::SeqCst) == 0 {
                break;
            }
            // Others are still reading folders; flush so results show up.
            flush(target, &mut local);
            std::thread::sleep(Duration::from_millis(2));
            continue;
        };
        local.dirs.push((id, path.clone()));
        let subdirs = read_one(&path, id, &mut local, shared, progress);
        if !subdirs.is_empty() {
            shared.pending.fetch_add(subdirs.len(), Ordering::SeqCst);
            shared.queue.lock().unwrap().extend(subdirs);
        }
        shared.pending.fetch_sub(1, Ordering::SeqCst);
        if local.entries.len() >= FLUSH_AT {
            if let Ok(mut c) = progress.current.try_lock() {
                *c = path;
            }
            flush(target, &mut local);
        }
    }
    flush(target, &mut local);
}

/// Read one folder; returns the subfolders to visit next.
pub(crate) fn read_one(path: &str, id: u32, local_entries: &mut impl EntrySink, shared: &impl DirIds, progress: &Progress) -> Vec<(String, u32)> {
    let mut subdirs = Vec::new();
    let os_path: PathBuf = if path.ends_with(':') { PathBuf::from(format!("{path}\\")) } else { PathBuf::from(path) };
    let Ok(rd) = std::fs::read_dir(&os_path) else { return subdirs };
    for de in rd.flatten() {
        let name = de.file_name().to_string_lossy().into_owned();
        let Ok(md) = de.metadata() else { continue };
        let (attrs, mtime, ctime) = meta_times(&md);
        let reparse = attrs & ATTR_REPARSE != 0 || md.file_type().is_symlink();
        let is_dir = md.is_dir() || attrs & ATTR_DIRECTORY != 0;
        let mut self_dir = NONE;
        if is_dir {
            self_dir = shared.new_dir_id();
            let child = crate::index::join(path, &name);
            if reparse {
                // Listed, but not followed (avoids loops through junctions).
                local_entries.add_dir(self_dir, child);
            } else {
                subdirs.push((child, self_dir));
            }
        }
        progress.found.fetch_add(1, Ordering::Relaxed);
        local_entries.add_entry(Entry {
            fold: fold(&name).into_boxed_str(),
            name: name.into_boxed_str(),
            dir: id,
            self_dir,
            size: if is_dir { NO_SIZE } else { md.len() },
            mtime,
            ctime,
            attrs: attrs | if is_dir { ATTR_DIRECTORY } else { 0 },
            children: 0,
            deleted: false,
        });
    }
    subdirs
}

pub(crate) trait EntrySink {
    fn add_entry(&mut self, e: Entry);
    fn add_dir(&mut self, id: u32, path: String);
}
impl EntrySink for Local {
    fn add_entry(&mut self, e: Entry) {
        self.entries.push(e);
    }
    fn add_dir(&mut self, id: u32, path: String) {
        self.dirs.push((id, path));
    }
}
pub(crate) trait DirIds {
    fn new_dir_id(&self) -> u32;
}
impl DirIds for Shared {
    fn new_dir_id(&self) -> u32 {
        self.next_dir.fetch_add(1, Ordering::SeqCst)
    }
}

#[cfg(windows)]
pub fn meta_times(md: &std::fs::Metadata) -> (u32, u64, u64) {
    use std::os::windows::fs::MetadataExt;
    (md.file_attributes(), md.last_write_time(), md.creation_time())
}

#[cfg(not(windows))]
pub fn meta_times(md: &std::fs::Metadata) -> (u32, u64, u64) {
    let to_ft = |t: std::io::Result<std::time::SystemTime>| {
        t.ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| (d.as_secs() + 11_644_473_600) * 10_000_000 + d.subsec_nanos() as u64 / 100)
            .unwrap_or(0)
    };
    (0, to_ft(md.modified()), to_ft(md.created()))
}

