//! Search language: space = AND, | = OR, ! = NOT, < > grouping, "phrases",
//! * and ? wildcards, modifiers (case:, path:, ww:, regex:, file:, folder: ...)
//! and functions (ext:, size:, dm:, dc:, infolder:, len:, count:, dupe:, empty:).

use crate::dates;
use crate::index::{fold, strip_accents, Entry, Index, ATTR_DIRECTORY};
use regex::Regex;

#[derive(Clone, Copy, Default, PartialEq, Eq, Debug)]
pub struct Options {
    pub case: bool,
    pub whole_word: bool,
    pub path: bool,
    pub diacritics: bool,
    pub regex: bool,
}

#[derive(Clone, Copy, Default)]
struct Mods {
    case: Option<bool>,
    whole_word: Option<bool>,
    path: Option<bool>,
    diacritics: Option<bool>,
    regex: Option<bool>,
    wildcards: Option<bool>,
    wfn: bool,
    start: bool,
    end: bool,
    files_only: bool,
    folders_only: bool,
}

impl Mods {
    fn merge(&self, inner: &Mods) -> Mods {
        Mods {
            case: inner.case.or(self.case),
            whole_word: inner.whole_word.or(self.whole_word),
            path: inner.path.or(self.path),
            diacritics: inner.diacritics.or(self.diacritics),
            regex: inner.regex.or(self.regex),
            wildcards: inner.wildcards.or(self.wildcards),
            wfn: self.wfn || inner.wfn,
            start: self.start || inner.start,
            end: self.end || inner.end,
            files_only: self.files_only || inner.files_only,
            folders_only: self.folders_only || inner.folders_only,
        }
    }
    fn is_empty_type(&self) -> bool {
        !self.files_only && !self.folders_only
    }
}

enum TextMode {
    Contains(String),
    Equals(String),
    Starts(String),
    Ends(String),
    Word(String),
    Re(Regex),
}

struct TextTerm {
    mode: TextMode,
    case: bool,
    diacritics: bool,
    path: bool,
}

enum Term {
    Text(TextTerm),
    Ext(Vec<String>),
    Size(u64, u64),
    SizeUnknown,
    Date { created: bool, lo: i64, hi: i64 },
    InFolder(String),
    Len(u64, u64),
    Empty,
    Attrib(u32),
    True,
}

enum Node {
    And(Vec<Node>),
    Or(Vec<Node>),
    Not(Box<Node>),
    Leaf { term: Term, files_only: bool, folders_only: bool },
}

pub struct Query {
    root: Node,
    pub count: Option<usize>,
    pub dupe: bool,
    pub is_empty: bool,
}

// ------------------------------------------------------------------ tokens

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Open,
    Close,
    Or,
    Not,
    Word(String),
}

const MODIFIERS: &[&str] = &[
    "nocase:", "case:", "nopath:", "path:", "nowholeword:", "wholeword:", "noww:", "ww:", "noregex:", "regex:",
    "nodiacritics:", "diacritics:", "nowildcards:", "wildcards:", "wholefilename:", "wfn:", "startwith:", "endwith:",
    "files:", "file:", "folders:", "folder:", "ascii:", "utf8:", "nofile:", "nofolder:",
];

fn is_modifier_only(w: &str) -> bool {
    let mut rest = w;
    if rest.is_empty() {
        return false;
    }
    while !rest.is_empty() {
        let lower = rest.to_ascii_lowercase();
        match MODIFIERS.iter().find(|m| lower.starts_with(**m)) {
            Some(m) => rest = &rest[m.len()..],
            None => return false,
        }
    }
    true
}

fn tokenize(s: &str) -> Vec<Tok> {
    let mut out = Vec::new();
    let mut word = String::new();
    let mut quoted = false;
    let push = |w: &mut String, out: &mut Vec<Tok>| {
        if !w.is_empty() {
            out.push(Tok::Word(std::mem::take(w)));
        }
    };
    for c in s.chars() {
        if quoted {
            if c == '"' {
                quoted = false;
            } else {
                word.push(c);
            }
            continue;
        }
        match c {
            '"' => quoted = true,
            c if c.is_whitespace() => push(&mut word, &mut out),
            '|' => {
                push(&mut word, &mut out);
                out.push(Tok::Or);
            }
            '!' if word.is_empty() => out.push(Tok::Not),
            '<' | '>' => {
                let last = word.chars().last();
                let comparison = matches!(last, Some(':') | Some('<') | Some('>') | Some('='));
                if comparison && !(c == '<' && is_modifier_only(&word)) {
                    word.push(c);
                } else {
                    push(&mut word, &mut out);
                    out.push(if c == '<' { Tok::Open } else { Tok::Close });
                }
            }
            c => word.push(c),
        }
    }
    push(&mut word, &mut out);
    out
}

// ------------------------------------------------------------------ parser

struct Parser<'a> {
    toks: Vec<Tok>,
    pos: usize,
    opts: &'a Options,
    count: Option<usize>,
    dupe: bool,
    error: Option<String>,
}

pub fn compile(text: &str, opts: &Options) -> Result<Query, String> {
    let toks = tokenize(text);
    let is_empty = toks.is_empty();
    let mut p = Parser { toks, pos: 0, opts, count: None, dupe: false, error: None };
    let root = p.parse_or(&Mods::default());
    if let Some(e) = p.error {
        return Err(e);
    }
    Ok(Query { root, count: p.count, dupe: p.dupe, is_empty })
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<&Tok> {
        self.toks.get(self.pos)
    }

    fn parse_or(&mut self, mods: &Mods) -> Node {
        let mut alts = vec![self.parse_and(mods)];
        while self.peek() == Some(&Tok::Or) {
            self.pos += 1;
            alts.push(self.parse_and(mods));
        }
        if alts.len() == 1 { alts.pop().unwrap() } else { Node::Or(alts) }
    }

    fn parse_and(&mut self, mods: &Mods) -> Node {
        let mut items = Vec::new();
        let mut cur = *mods;
        loop {
            match self.peek() {
                None | Some(Tok::Or) | Some(Tok::Close) => break,
                Some(Tok::Word(w)) if is_modifier_only(w) => {
                    let w = w.clone();
                    self.pos += 1;
                    let (m, _) = strip_modifiers(&w);
                    let next_is_term = !matches!(self.peek(), None | Some(Tok::Or) | Some(Tok::Close));
                    if next_is_term {
                        // Applies to the next item (and, for a bare switch, the rest of this group).
                        cur = cur.merge(&m);
                    } else if !m.is_empty_type() {
                        items.push(leaf(Term::True, &cur.merge(&m)));
                    }
                }
                _ => {
                    if let Some(n) = self.parse_unary(&cur) {
                        items.push(n);
                    }
                }
            }
        }
        if items.len() == 1 { items.pop().unwrap() } else { Node::And(items) }
    }

    fn parse_unary(&mut self, mods: &Mods) -> Option<Node> {
        match self.peek()?.clone() {
            Tok::Not => {
                self.pos += 1;
                let inner = self.parse_unary(mods)?;
                Some(Node::Not(Box::new(inner)))
            }
            Tok::Open => {
                self.pos += 1;
                let n = self.parse_or(mods);
                if self.peek() == Some(&Tok::Close) {
                    self.pos += 1;
                }
                Some(n)
            }
            Tok::Close | Tok::Or => {
                self.pos += 1;
                None
            }
            Tok::Word(w) => {
                self.pos += 1;
                self.word(&w, mods)
            }
        }
    }

    fn word(&mut self, w: &str, outer: &Mods) -> Option<Node> {
        let (m, rest) = strip_modifiers(w);
        let mods = outer.merge(&m);
        let lower = rest.to_ascii_lowercase();
        let func = |name: &str| -> Option<&str> {
            if lower.starts_with(name) { Some(&rest[name.len()..]) } else { None }
        };
        for (macro_name, exts) in crate::filters::MACROS {
            if let Some(arg) = func(macro_name) {
                let mut n = vec![leaf(Term::Ext(split_exts(exts)), &mods)];
                if !arg.is_empty() {
                    n.push(self.text_leaf(arg, &mods)?);
                }
                return Some(if n.len() == 1 { n.pop().unwrap() } else { Node::And(n) });
            }
        }
        if let Some(arg) = func("ext:") {
            return Some(leaf(Term::Ext(split_exts(arg)), &mods));
        }
        if let Some(arg) = func("size:") {
            return Some(leaf(parse_size(arg).unwrap_or(Term::True), &mods));
        }
        for (name, created) in [("dm:", false), ("datemodified:", false), ("dc:", true), ("datecreated:", true)] {
            if let Some(arg) = func(name) {
                return Some(match dates::parse_range(arg) {
                    Some((lo, hi)) => leaf(Term::Date { created, lo, hi }, &mods),
                    None => leaf(Term::True, &mods),
                });
            }
        }
        for name in ["infolder:", "parent:"] {
            if let Some(arg) = func(name) {
                let p = fold(arg.trim_end_matches('\\'));
                return Some(leaf(Term::InFolder(p), &mods));
            }
        }
        if let Some(arg) = func("len:") {
            let (lo, hi) = parse_numeric(arg, 1).unwrap_or((0, u64::MAX));
            return Some(leaf(Term::Len(lo, hi), &mods));
        }
        if let Some(arg) = func("count:") {
            self.count = arg.trim().parse().ok();
            return Some(leaf(Term::True, &mods));
        }
        if func("dupe:").is_some() {
            self.dupe = true;
            return Some(leaf(Term::True, &mods));
        }
        if func("empty:").is_some() {
            return Some(leaf(Term::Empty, &mods));
        }
        for name in ["attrib:", "attributes:"] {
            if let Some(arg) = func(name) {
                return Some(leaf(Term::Attrib(parse_attrib(arg)), &mods));
            }
        }
        self.text_leaf(rest, &mods)
    }

    fn text_leaf(&mut self, text: &str, mods: &Mods) -> Option<Node> {
        if text.is_empty() {
            return Some(leaf(Term::True, mods));
        }
        let o = self.opts;
        let case = mods.case.unwrap_or(o.case);
        let diacritics = mods.diacritics.unwrap_or(o.diacritics);
        let regex = mods.regex.unwrap_or(o.regex);
        let whole_word = mods.whole_word.unwrap_or(o.whole_word);
        let wildcards = mods.wildcards.unwrap_or(true);
        let path = mods.path.unwrap_or(o.path) || text.contains('\\') || text.contains('/');
        let text_norm = text.replace('/', "\\");
        let norm = |s: &str| normalize(s, case, diacritics);
        let mode = if regex {
            let pat = if case { text.to_string() } else { format!("(?i){text}") };
            match Regex::new(&pat) {
                Ok(r) => TextMode::Re(r),
                Err(_) => {
                    self.error = Some(format!("Invalid regex: {text}"));
                    return None;
                }
            }
        } else if wildcards && (text.contains('*') || text.contains('?')) {
            let mut pat = String::from("^");
            for ch in norm(&text_norm).chars() {
                match ch {
                    '*' => pat.push_str(".*"),
                    '?' => pat.push('.'),
                    c => pat.push_str(&regex::escape(&c.to_string())),
                }
            }
            pat.push('$');
            let pat = if path { pat } else { pat.replacen('^', "^", 1) };
            match Regex::new(&format!("(?s){pat}")) {
                Ok(r) => TextMode::Re(r),
                Err(_) => TextMode::Contains(norm(&text_norm)),
            }
        } else if mods.wfn {
            TextMode::Equals(norm(&text_norm))
        } else if mods.start {
            TextMode::Starts(norm(&text_norm))
        } else if mods.end {
            TextMode::Ends(norm(&text_norm))
        } else if whole_word {
            TextMode::Word(norm(&text_norm))
        } else {
            TextMode::Contains(norm(&text_norm))
        };
        // A wildcard pattern that never used a path separator still matches the whole path
        // only when path matching is on.
        let t = TextTerm { mode, case, diacritics, path };
        Some(leaf(Term::Text(t), mods))
    }
}

fn leaf(term: Term, m: &Mods) -> Node {
    Node::Leaf { term, files_only: m.files_only, folders_only: m.folders_only }
}

fn strip_modifiers(w: &str) -> (Mods, &str) {
    let mut m = Mods::default();
    let mut rest = w;
    loop {
        let lower = rest.to_ascii_lowercase();
        let Some(found) = MODIFIERS.iter().find(|p| lower.starts_with(**p)) else { break };
        match *found {
            "case:" => m.case = Some(true),
            "nocase:" => m.case = Some(false),
            "path:" => m.path = Some(true),
            "nopath:" => m.path = Some(false),
            "wholeword:" | "ww:" => m.whole_word = Some(true),
            "nowholeword:" | "noww:" => m.whole_word = Some(false),
            "regex:" => m.regex = Some(true),
            "noregex:" => m.regex = Some(false),
            "diacritics:" => m.diacritics = Some(true),
            "nodiacritics:" => m.diacritics = Some(false),
            "wildcards:" => m.wildcards = Some(true),
            "nowildcards:" => m.wildcards = Some(false),
            "wholefilename:" | "wfn:" => m.wfn = true,
            "startwith:" => m.start = true,
            "endwith:" => m.end = true,
            "file:" | "files:" | "nofolder:" => m.files_only = true,
            "folder:" | "folders:" | "nofile:" => m.folders_only = true,
            _ => {}
        }
        rest = &rest[found.len()..];
        if m.regex == Some(true) {
            break; // the rest is the pattern itself
        }
    }
    (m, rest)
}

fn split_exts(s: &str) -> Vec<String> {
    s.split(';').map(|e| e.trim().trim_start_matches('.').to_lowercase()).filter(|e| !e.is_empty()).collect()
}

/// "<", ">", "<=", ">=", "=", "a..b" or "a-b" over numbers converted by `unit`.
fn parse_compare(arg: &str, value: impl Fn(&str) -> Option<(u64, u64)>) -> Option<(u64, u64)> {
    let a = arg.trim();
    for (op, f) in [
        ("<=", 0u8), (">=", 1), ("<", 2), (">", 3), ("=", 4),
    ] {
        if let Some(v) = a.strip_prefix(op) {
            let (lo, hi) = value(v)?;
            return Some(match f {
                0 => (0, hi),
                1 => (lo, u64::MAX),
                2 => (0, lo.saturating_sub(1)),
                3 => (hi.saturating_add(1), u64::MAX),
                _ => (lo, hi),
            });
        }
    }
    if let Some((l, r)) = a.split_once("..").or_else(|| a.split_once('-')) {
        let (lo, _) = value(l)?;
        let (_, hi) = value(r)?;
        return Some((lo, hi));
    }
    value(a)
}

fn parse_numeric(arg: &str, _unit: u64) -> Option<(u64, u64)> {
    parse_compare(arg, |v| v.trim().parse::<u64>().ok().map(|n| (n, n)))
}

/// size: keywords and values (see MECHANICS.md, sub_140055200).
fn parse_size(arg: &str) -> Option<Term> {
    let a = arg.trim().to_ascii_lowercase();
    if a == "unknown" {
        return Some(Term::SizeUnknown);
    }
    let r = parse_compare(&a, size_value)?;
    Some(Term::Size(r.0, r.1))
}

const KB: u64 = 1024;
pub const SIZE_BANDS: [(&str, u64, u64); 7] = [
    ("empty", 0, 0),
    ("tiny", 1, 10 * KB),
    ("small", 10 * KB + 1, 100 * KB),
    ("medium", 100 * KB + 1, KB * KB),
    ("large", KB * KB + 1, 16 * KB * KB),
    ("huge", 16 * KB * KB + 1, 128 * KB * KB),
    ("gigantic", 128 * KB * KB + 1, u64::MAX - 1),
];

fn size_value(v: &str) -> Option<(u64, u64)> {
    let v = v.trim();
    if let Some(b) = SIZE_BANDS.iter().find(|b| b.0 == v) {
        return Some((b.1, b.2));
    }
    let split = v.find(|c: char| !(c.is_ascii_digit() || c == '.')).unwrap_or(v.len());
    let (num, unit) = v.split_at(split);
    let num: f64 = num.parse().ok()?;
    let mult: u64 = match unit.trim() {
        "" | "b" | "bytes" => return Some((num as u64, num as u64)),
        "k" | "kb" => KB,
        "m" | "mb" => KB * KB,
        "g" | "gb" => KB * KB * KB,
        "t" | "tb" => KB.pow(4),
        "p" | "pb" => KB.pow(5),
        "e" | "eb" => KB.pow(6),
        _ => return None,
    };
    // A value with a unit matches the 1 KB band that ends at the value rounded up.
    let hi = ((num * mult as f64) as u64).saturating_add(0x3ff) & !0x3ff;
    Some((hi.saturating_sub(0x3ff), hi))
}

fn parse_attrib(s: &str) -> u32 {
    let mut a = 0;
    for c in s.to_ascii_uppercase().chars() {
        a |= match c {
            'R' => 0x1, 'H' => 0x2, 'S' => 0x4, 'D' => 0x10, 'A' => 0x20, 'N' => 0x80, 'T' => 0x100,
            'P' => 0x200, 'L' => 0x400, 'C' => 0x800, 'O' => 0x1000, 'I' => 0x2000, 'E' => 0x4000, _ => 0,
        };
    }
    a
}

pub fn normalize(s: &str, case: bool, diacritics: bool) -> String {
    match (case, diacritics) {
        (false, false) => fold(s),
        (true, false) => strip_accents(s),
        (false, true) => s.to_lowercase(),
        (true, true) => s.to_string(),
    }
}

// ------------------------------------------------------------------ matching

impl Query {
    pub fn matches(&self, idx: &Index, e: &Entry) -> bool {
        eval(&self.root, idx, e)
    }
}

fn eval(n: &Node, idx: &Index, e: &Entry) -> bool {
    match n {
        Node::And(v) => v.iter().all(|c| eval(c, idx, e)),
        Node::Or(v) => v.iter().any(|c| eval(c, idx, e)),
        Node::Not(c) => !eval(c, idx, e),
        Node::Leaf { term, files_only, folders_only } => {
            let dir = e.is_dir();
            if (*files_only && dir) || (*folders_only && !dir) {
                return false;
            }
            term_match(term, idx, e)
        }
    }
}

fn term_match(t: &Term, idx: &Index, e: &Entry) -> bool {
    match t {
        Term::True => true,
        Term::Text(tt) => text_match(tt, idx, e),
        Term::Ext(list) => {
            let ext = e.extension();
            !ext.is_empty() && list.iter().any(|x| x.eq_ignore_ascii_case(ext))
        }
        Term::Size(lo, hi) => !e.is_dir() && e.size >= *lo && e.size <= *hi,
        Term::SizeUnknown => e.is_dir(),
        Term::Date { created, lo, hi } => {
            let ft = if *created { e.ctime } else { e.mtime };
            if ft == 0 {
                return false;
            }
            let t = dates::filetime_to_unix(ft);
            t >= *lo && t < *hi
        }
        Term::InFolder(p) => idx.dir_fold(e) == p,
        Term::Len(lo, hi) => {
            let n = e.name.chars().count() as u64;
            n >= *lo && n <= *hi
        }
        Term::Empty => e.is_dir() && e.children == 0 && e.attrs & ATTR_DIRECTORY != 0,
        Term::Attrib(a) => *a != 0 && e.attrs & a == *a,
    }
}

fn text_match(t: &TextTerm, idx: &Index, e: &Entry) -> bool {
    let default_norm = !t.case && !t.diacritics;
    let owned;
    let hay: &str = if t.path {
        owned = if default_norm {
            crate::index::join(idx.dir_fold(e), &e.fold)
        } else {
            normalize(&idx.full_path(e), t.case, t.diacritics)
        };
        &owned
    } else if default_norm {
        &e.fold
    } else {
        owned = normalize(&e.name, t.case, t.diacritics);
        &owned
    };
    match &t.mode {
        TextMode::Contains(n) => hay.contains(n.as_str()),
        TextMode::Equals(n) => hay == n,
        TextMode::Starts(n) => hay.starts_with(n.as_str()),
        TextMode::Ends(n) => hay.ends_with(n.as_str()),
        TextMode::Word(n) => whole_word(hay, n),
        TextMode::Re(r) => r.is_match(hay),
    }
}

fn whole_word(hay: &str, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    let is_word = |c: char| c.is_alphanumeric() || c == '_';
    let mut start = 0;
    while let Some(p) = hay[start..].find(needle) {
        let s = start + p;
        let e = s + needle.len();
        let before = hay[..s].chars().next_back().map_or(true, |c| !is_word(c));
        let after = hay[e..].chars().next().map_or(true, |c| !is_word(c));
        if before && after {
            return true;
        }
        start = s + hay[s..].chars().next().map_or(1, |c| c.len_utf8());
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn tokens() {
        assert_eq!(tokenize("a b|c"), vec![Tok::Word("a".into()), Tok::Word("b".into()), Tok::Or, Tok::Word("c".into())]);
        assert_eq!(tokenize("size:>1mb"), vec![Tok::Word("size:>1mb".into())]);
        assert_eq!(tokenize("!<a|b>"), vec![Tok::Not, Tok::Open, Tok::Word("a".into()), Tok::Or, Tok::Word("b".into()), Tok::Close]);
        assert_eq!(tokenize("\"my file\""), vec![Tok::Word("my file".into())]);
    }
    #[test]
    fn sizes() {
        assert_eq!(size_value("1mb"), Some((1048576 - 1023, 1048576)));
        assert_eq!(size_value("tiny"), Some((1, 10240)));
        assert_eq!(size_value("100"), Some((100, 100)));
    }
}

//! Date keywords for dm:/dc: (today, yesterday, thisweek, last2weeks, 2024-05 ...).

use chrono::{Datelike, Duration, Local, NaiveDate, NaiveDateTime, TimeZone};

pub fn filetime_to_unix(ft: u64) -> i64 {
    (ft / 10_000_000) as i64 - 11_644_473_600
}

fn ts(d: NaiveDateTime) -> i64 {
    Local.from_local_datetime(&d).earliest().map(|t| t.timestamp()).unwrap_or_else(|| d.and_utc().timestamp())
}

fn day(d: NaiveDate) -> i64 {
    ts(d.and_hms_opt(0, 0, 0).unwrap())
}

fn add_months(d: NaiveDate, m: i32) -> NaiveDate {
    let total = d.year() * 12 + d.month0() as i32 + m;
    NaiveDate::from_ymd_opt(total.div_euclid(12), total.rem_euclid(12) as u32 + 1, 1).unwrap()
}

/// One value -> [start, end) in unix seconds.
fn value(v: &str) -> Option<(i64, i64)> {
    let v = v.trim().to_ascii_lowercase();
    let now = Local::now().naive_local();
    let today = now.date();
    let week_start = today - Duration::days(today.weekday().num_days_from_monday() as i64);
    let month_start = NaiveDate::from_ymd_opt(today.year(), today.month(), 1)?;
    let year_start = NaiveDate::from_ymd_opt(today.year(), 1, 1)?;
    let period = |unit: &str, offset: i32| -> Option<(i64, i64)> {
        Some(match unit {
            "day" => {
                let d = today + Duration::days(offset as i64);
                (day(d), day(d + Duration::days(1)))
            }
            "week" => {
                let d = week_start + Duration::weeks(offset as i64);
                (day(d), day(d + Duration::weeks(1)))
            }
            "month" => (day(add_months(month_start, offset)), day(add_months(month_start, offset + 1))),
            "year" => (day(add_months(year_start, offset * 12)), day(add_months(year_start, offset * 12 + 12))),
            _ => return None,
        })
    };
    match v.as_str() {
        "today" => return period("day", 0),
        "yesterday" => return period("day", -1),
        "tomorrow" => return period("day", 1),
        _ => {}
    }
    for (prefix, kind) in [("this", 0), ("last", -1), ("past", 2), ("next", 1)] {
        if let Some(rest) = v.strip_prefix(prefix) {
            let digits: String = rest.chars().take_while(|c| c.is_ascii_digit()).collect();
            let unit = rest[digits.len()..].trim_end_matches('s');
            let n: i64 = digits.parse().unwrap_or(1);
            if digits.is_empty() && kind != 2 {
                if let Some(r) = period(unit, kind) {
                    return Some(r);
                }
            }
            // last<n><unit> / past<n><unit>: from n units ago until now.
            let back = match unit {
                "minute" => Duration::minutes(n),
                "hour" => Duration::hours(n),
                "day" => Duration::days(n),
                "week" => Duration::weeks(n),
                "month" => Duration::days(30 * n),
                "year" => Duration::days(365 * n),
                _ => return None,
            };
            let end = ts(now);
            return Some(if kind == 1 { (end, ts(now + back)) } else { (ts(now - back), end + 1) });
        }
    }
    // Explicit dates: yyyy, yyyy-mm, yyyy-mm-dd, d/m/yyyy.
    let parts: Vec<&str> = v.split(|c| c == '-' || c == '/' || c == '.').collect();
    let nums: Vec<i32> = parts.iter().map(|p| p.parse().ok()).collect::<Option<_>>()?;
    match nums.as_slice() {
        [y] if *y > 1600 => {
            let s = NaiveDate::from_ymd_opt(*y, 1, 1)?;
            Some((day(s), day(add_months(s, 12))))
        }
        [y, m] if *y > 1600 => {
            let s = NaiveDate::from_ymd_opt(*y, *m as u32, 1)?;
            Some((day(s), day(add_months(s, 1))))
        }
        [y, m, d] if *y > 1600 => {
            let s = NaiveDate::from_ymd_opt(*y, *m as u32, *d as u32)?;
            Some((day(s), day(s + Duration::days(1))))
        }
        [d, m, y] if *y > 1600 => {
            let s = NaiveDate::from_ymd_opt(*y, *m as u32, *d as u32)?;
            Some((day(s), day(s + Duration::days(1))))
        }
        _ => None,
    }
}

/// A dm:/dc: argument, with optional comparison or `a..b` range.
pub fn parse_range(arg: &str) -> Option<(i64, i64)> {
    let a = arg.trim();
    if let Some(v) = a.strip_prefix("<=") {
        return value(v).map(|(_, e)| (i64::MIN, e));
    }
    if let Some(v) = a.strip_prefix(">=") {
        return value(v).map(|(s, _)| (s, i64::MAX));
    }
    if let Some(v) = a.strip_prefix('<') {
        return value(v).map(|(s, _)| (i64::MIN, s));
    }
    if let Some(v) = a.strip_prefix('>') {
        return value(v).map(|(_, e)| (e, i64::MAX));
    }
    if let Some(v) = a.strip_prefix('=') {
        return value(v);
    }
    if let Some((l, r)) = a.split_once("..") {
        let (s, _) = value(l)?;
        let (_, e) = value(r)?;
        return Some((s, e));
    }
    value(a)
}

/// FILETIME -> "dd/mm/yyyy hh:mm" in local time (estimated format).
pub fn format_filetime(ft: u64) -> String {
    if ft == 0 {
        return String::new();
    }
    match Local.timestamp_opt(filetime_to_unix(ft), 0).single() {
        Some(t) => t.format("%d/%m/%Y %H:%M").to_string(),
        None => String::new(),
    }
}

//! Built-in filters and macros (sub_1400c15c0 and the help text in the original).

pub const AUDIO: &str = "aac;ac3;aif;aifc;aiff;au;cda;dts;fla;flac;it;m1a;m2a;m3u;m4a;m4b;m4p;mid;midi;mka;mod;mp2;mp3;mpa;ogg;ra;rmi;snd;spc;umx;voc;wav;wma;xm";
pub const COMPRESSED: &str = "7z;ace;arj;bz2;cab;gz;gzip;jar;r00;r01;r02;r03;r04;r05;r06;r07;r08;r09;r10;r11;r12;r13;r14;r15;r16;r17;r18;r19;r20;r21;r22;r23;r24;r25;r26;r27;r28;r29;rar;tar;tgz;z;zip";
pub const DOCUMENT: &str = "c;chm;cpp;csv;cxx;doc;docm;docx;dot;dotm;dotx;h;hpp;htm;html;hxx;ini;java;lua;mht;mhtml;odt;pdf;potx;potm;ppam;ppsm;ppsx;pps;ppt;pptm;pptx;rtf;sldm;sldx;thmx;txt;vsd;wpd;wps;wri;xlam;xls;xlsb;xlsm;xlsx;xltm;xltx;xml";
