/// Which colour family a file name belongs to, for its little icon.
pub fn kind_of(ext: &str) -> Kind {
    let has = |list: &str| list.split(';').any(|e| e.eq_ignore_ascii_case(ext));
    if ext.is_empty() {
        Kind::Other
    } else if has(EXECUTABLE) || ext.eq_ignore_ascii_case("dll") {
        Kind::Exe
    } else if has(PICTURE) {
        Kind::Picture
    } else if has(AUDIO) {
        Kind::Audio
    } else if has(VIDEO) {
        Kind::Video
    } else if has(COMPRESSED) {
        Kind::Archive
    } else if has(DOCUMENT) {
        Kind::Document
    } else {
        Kind::Other
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Exe,
    Picture,
    Audio,
    Video,
    Archive,
    Document,
    Other,
}

//! Background search: filters and sorts the index without blocking the window.

use crate::index::{Entry, Index};
use crate::query::{compile, Options};
use rayon::prelude::*;
use std::cmp::Ordering;
use std::collections::HashMap;
use std::sync::mpsc::{Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::Instant;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SortKey {
    Name,
    Path,
    Size,
    Extension,
    Modified,
    Created,
    Attributes,
}

#[derive(Clone, PartialEq, Debug)]
pub struct Request {
    pub text: String,
    pub opts: Options,
    pub sort: SortKey,
    pub ascending: bool,
    pub generation: u64,
    pub epoch: u64,
    pub serial: u64,
}

pub struct Reply {
    pub serial: u64,
    pub epoch: u64,
    pub ids: Vec<u32>,
    pub error: Option<String>,
    pub millis: u128,
}

pub fn spawn(index: Arc<RwLock<Index>>, rx: Receiver<Request>, tx: Sender<Reply>, ctx: eframe::egui::Context) {
    std::thread::spawn(move || {
        let mut name_order: Vec<u32> = Vec::new();
        let mut order_key = (u64::MAX, u64::MAX);
        while let Ok(mut req) = rx.recv() {
            while let Ok(newer) = rx.try_recv() {
                req = newer;
            }
            let start = Instant::now();
            let idx = index.read().unwrap();
            let key = (idx.epoch, idx.generation);
            if key != order_key {
                name_order = (0..idx.entries.len() as u32).collect();
                let entries = &idx.entries;
                name_order.par_sort_unstable_by(|a, b| by_name(&entries[*a as usize], &entries[*b as usize]));
                order_key = key;
            }
            let reply = match compile(&req.text, &req.opts) {
                Err(e) => Reply { serial: req.serial, epoch: idx.epoch, ids: Vec::new(), error: Some(e), millis: 0 },
                Ok(q) => {
                    let entries = &idx.entries;
                    let mut ids: Vec<u32> = name_order
                        .par_iter()
                        .copied()
                        .filter(|&i| {
                            let e = &entries[i as usize];
                            !e.deleted && (q.is_empty || q.matches(&idx, e))
                        })
                        .collect();
                    if q.dupe {
                        let mut counts: HashMap<&str, u32> = HashMap::new();
                        for &i in &ids {
                            *counts.entry(&entries[i as usize].fold).or_default() += 1;
                        }
                        ids.retain(|&i| counts[&*entries[i as usize].fold] > 1);
                    }
                    sort(&idx, &mut ids, req.sort, req.ascending);
                    if let Some(n) = q.count {
                        ids.truncate(n);
                    }
                    Reply { serial: req.serial, epoch: idx.epoch, ids, error: None, millis: start.elapsed().as_millis() }
                }
            };
            drop(idx);
            if tx.send(reply).is_err() {
                break;
            }
            ctx.request_repaint();
        }
    });
}

fn by_name(a: &Entry, b: &Entry) -> Ordering {
    a.fold.cmp(&b.fold).then_with(|| a.name.cmp(&b.name))
}

fn sort(idx: &Index, ids: &mut [u32], key: SortKey, ascending: bool) {
    let e = |i: &u32| &idx.entries[*i as usize];
    match key {
        SortKey::Name => {}
        SortKey::Path => ids.par_sort_by(|a, b| {
            let (x, y) = (e(a), e(b));
            idx.dir_fold(x).cmp(idx.dir_fold(y)).then_with(|| by_name(x, y))
        }),
        SortKey::Size => ids.par_sort_by(|a, b| {
            let size = |x: &Entry| if x.is_dir() { 0 } else { x.size.saturating_add(1) };
            size(e(a)).cmp(&size(e(b)))
        }),
        SortKey::Extension => ids.par_sort_by(|a, b| e(a).extension().to_lowercase().cmp(&e(b).extension().to_lowercase())),
        SortKey::Modified => ids.par_sort_by_key(|a| e(a).mtime),
        SortKey::Created => ids.par_sort_by_key(|a| e(a).ctime),
        SortKey::Attributes => ids.par_sort_by_key(|a| e(a).attrs),
    }
    if !ascending {
        ids.reverse();
    }
}

//! Keeps the index current: watches the drives and applies changes in batches.

use crate::index::{fold, join, Entry, Index, ATTR_DIRECTORY, NO_SIZE};
use crate::scan::{meta_times, read_one, Counter, Local, Progress};
use notify::{RecursiveMode, Watcher};
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::sync::atomic::AtomicU32;
use std::sync::mpsc::{channel, RecvTimeoutError};
use std::sync::{Arc, RwLock};
use std::time::Duration;

/// Start watching `roots`. Runs for the life of the program.
pub fn start(index: Arc<RwLock<Index>>, roots: Vec<String>, ctx: eframe::egui::Context) {
    std::thread::spawn(move || {
        let (tx, rx) = channel::<PathBuf>();
        let mut watcher = match notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
            if let Ok(ev) = res {
                for p in ev.paths {
                    let _ = tx.send(p);
                }
            }
        }) {
            Ok(w) => w,
            Err(_) => return,
        };
        for r in &roots {
            let _ = watcher.watch(&PathBuf::from(format!("{r}\\")), RecursiveMode::Recursive);
        }
        let cache_dir = crate::index::cache_path().parent().map(|p| fold(&p.to_string_lossy())).unwrap_or_default();
        let mut lookup: Option<HashMap<Box<str>, u32>> = None;
        loop {
            let first = match rx.recv() {
                Ok(p) => p,
                Err(_) => return,
            };
            let mut batch: HashSet<String> = HashSet::new();
            batch.insert(first.to_string_lossy().into_owned());
            // Gather changes for a moment so bursts are applied together.
            loop {
                match rx.recv_timeout(Duration::from_millis(400)) {
                    Ok(p) => {
                        batch.insert(p.to_string_lossy().into_owned());
                        if batch.len() > 50_000 {
                            break;
                        }
                    }
                    Err(RecvTimeoutError::Timeout) => break,
                    Err(RecvTimeoutError::Disconnected) => return,
                }
            }
            batch.retain(|p| !fold(p).starts_with(&cache_dir) || cache_dir.is_empty());
            if batch.is_empty() {
                continue;
            }
            let mut idx = index.write().unwrap();
            if !idx.ready {
                continue;
            }
            let lk = lookup.get_or_insert_with(|| build_lookup(&idx));
            if lk.len() > idx.dirs.len() {
                *lk = build_lookup(&idx);
            }
            apply(&mut idx, lk, batch);
            idx.generation += 1;
            drop(idx);
            ctx.request_repaint();
        }
    });
}

fn build_lookup(idx: &Index) -> HashMap<Box<str>, u32> {
    idx.dirs
        .iter()
        .enumerate()
        .filter(|(_, d)| !d.fold.is_empty())
        .map(|(i, d)| (d.fold.clone(), i as u32))
        .collect()
}

fn split(path: &str) -> Option<(&str, &str)> {
    let p = path.trim_end_matches('\\');
    let i = p.rfind('\\')?;
    let parent = &p[..i];
    Some((if parent.ends_with(':') { parent } else { parent }, &p[i + 1..]))
}

fn apply(idx: &mut Index, lookup: &mut HashMap<Box<str>, u32>, batch: HashSet<String>) {
    // Parents first, so new folders exist before their contents.
    let mut paths: Vec<String> = batch.into_iter().collect();
    paths.sort_by_key(|p| p.len());
    let mut targets: HashMap<(u32, String), String> = HashMap::new();
    for p in &paths {
        let Some((parent, name)) = split(p) else { continue };
        if let Some(&pid) = lookup.get(fold(parent).as_str()) {
            targets.insert((pid, fold(name)), p.clone());
        }
    }
    if targets.is_empty() {
        return;
    }
    let parents: HashSet<u32> = targets.keys().map(|k| k.0).collect();
    let mut found: HashMap<(u32, String), usize> = HashMap::new();
    for (i, e) in idx.entries.iter().enumerate() {
        if !e.deleted && parents.contains(&e.dir) {
            let key = (e.dir, e.fold.to_string());
            if targets.contains_key(&key) {
                found.insert(key, i);
            }
        }
    }
    let mut keys: Vec<(u32, String)> = targets.keys().cloned().collect();
    keys.sort_by_key(|k| targets[k].len());
    for key in keys {
        let path = &targets[&key];
        let existing = found.get(&key).copied();
        match std::fs::symlink_metadata(path) {
            Ok(md) => {
                let (attrs, mtime, ctime) = meta_times(&md);
                let is_dir = md.is_dir();
                if let Some(i) = existing {
                    let e = &mut idx.entries[i];
                    e.size = if is_dir { NO_SIZE } else { md.len() };
                    e.mtime = mtime;
                    e.ctime = ctime;
                    e.attrs = attrs | if is_dir { ATTR_DIRECTORY } else { 0 };
                    if let Some((_, name)) = split(path) {
                        if *e.name != *name {
                            e.name = name.into();
                        }
                    }
                } else {
                    add_new(idx, lookup, key.0, path, is_dir, md.len(), attrs, mtime, ctime);
                }
            }
            Err(_) => {
                if let Some(i) = existing {
                    remove(idx, lookup, i);
                }
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn add_new(idx: &mut Index, lookup: &mut HashMap<Box<str>, u32>, pid: u32, path: &str, is_dir: bool, size: u64, attrs: u32, mtime: u64, ctime: u64) {
    let Some((_, name)) = split(path) else { return };
    let mut self_dir = crate::index::NONE;
    if is_dir {
        self_dir = idx.dirs.len() as u32;
        idx.set_dir(self_dir, path.to_string());
        lookup.insert(fold(path).into_boxed_str(), self_dir);
    }
    idx.entries.push(Entry {
        name: name.into(),
        fold: fold(name).into_boxed_str(),
        dir: pid,
        self_dir,
        size: if is_dir { NO_SIZE } else { size },
        mtime,
        ctime,
        attrs: attrs | if is_dir { ATTR_DIRECTORY } else { 0 },
        children: 0,
        deleted: false,
    });
    bump_children(idx, pid, 1);
    if is_dir {
        let entry = idx.entries.len() as u32 - 1;
        idx.dirs[self_dir as usize].entry = entry;
        // A folder moved in from elsewhere arrives with its contents.
        let counter = Counter(AtomicU32::new(idx.dirs.len() as u32));
        let progress = Progress::default();
        let mut stack = vec![(path.to_string(), self_dir)];
        let mut local = Local::default();
        while let Some((p, id)) = stack.pop() {
            stack.extend(read_one(&p, id, &mut local, &counter, &progress));
            local.dirs.push((id, p));
            if local.entries.len() > 200_000 {
                break;
            }
        }
        for (id, p) in local.dirs.drain(..) {
            if id != self_dir {
                lookup.insert(fold(&p).into_boxed_str(), id);
                idx.set_dir(id, p);
            }
        }
        idx.entries.append(&mut local.entries);
        idx.finalize();
    }
}

fn remove(idx: &mut Index, lookup: &mut HashMap<Box<str>, u32>, i: usize) {
    idx.entries[i].deleted = true;
    let pid = idx.entries[i].dir;
    bump_children(idx, pid, -1);
    let sd = idx.entries[i].self_dir;
    if sd == crate::index::NONE {
        return;
    }
    // Everything below a removed folder goes too.
    let prefix = format!("{}\\", idx.dirs[sd as usize].fold);
    let mut dead: HashSet<u32> = HashSet::new();
    dead.insert(sd);
    for (d, info) in idx.dirs.iter().enumerate() {
        if info.fold.starts_with(&prefix) {
            dead.insert(d as u32);
        }
    }
    for d in &dead {
        let key = idx.dirs[*d as usize].fold.clone();
        lookup.remove(&key);
    }
    for e in idx.entries.iter_mut() {
        if dead.contains(&e.dir) {
            e.deleted = true;
        }
    }
    let _ = join; // keep helper import used across platforms
}

fn bump_children(idx: &mut Index, dir: u32, delta: i32) {
    if dir == crate::index::NONE {
        return;
    }
    let ent = idx.dirs.get(dir as usize).map(|d| d.entry).unwrap_or(crate::index::NONE);
    if let Some(e) = idx.entries.get_mut(ent as usize) {
        e.children = (e.children as i64 + delta as i64).max(0) as u32;
    }
}

input.old_string:
    idx.entries.append(&mut local.entries);
    idx.finalize();
}

input.new_string:
    let start = idx.entries.len();
    idx.entries.append(&mut local.entries);
    for i in start..idx.entries.len() {
        let sd = idx.entries[i].self_dir;
        if sd != crate::index::NONE && (sd as usize) < idx.dirs.len() {
            idx.dirs[sd as usize].entry = i as u32;
        }
    }
    for i in start..idx.entries.len() {
        let d = idx.entries[i].dir;
        bump_children(idx, d, 1);
    }
}

