29	pub struct App {
30	    index: Arc<RwLock<Index>>,
31	    progress: Arc<Progress>,
32	    req_tx: Sender<Request>,
33	    rep_rx: Receiver<Reply>,
34	    query: String,
35	    opts: Options,
36	    filter: usize,
37	    sort: SortKey,
38	    ascending: bool,
39	    ids: Vec<u32>,
40	    ids_epoch: u64,
41	    error: Option<String>,
42	    millis: u128,
43	    serial: u64,
44	    shown_serial: u64,
45	    last_req: Option<Request>,
46	    last_sent: Instant,
47	    selected: HashSet<u32>,
48	    anchor: Option<usize>,
49	    cursor: Option<usize>,
50	    results_focus: bool,
51	    scroll_to: Option<usize>,
52	    columns: Columns,
