66	impl App {
67	    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>, start: StartOptions) -> Self {
68	        let mut app = Self::create(cc, screenshot);
69	        start.apply(&mut app);
70	        app
71	    }
72	
73	    fn create(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
74	        setup_style(&cc.egui_ctx);
75	        let index = Arc::new(RwLock::new(Index::default()));
76	        let progress = Arc::new(Progress::default());
77	        let (req_tx, req_rx) = channel();
78	        let (rep_tx, rep_rx) = channel();
79	        search::spawn(index.clone(), req_rx, rep_tx, cc.egui_ctx.clone());
80	        start_indexing(index.clone(), progress.clone(), cc.egui_ctx.clone(), screenshot.is_some());
81	        App {
82	            index,
83	            progress,
84	            req_tx,
85	            rep_rx,
86	            query: String::new(),
87	            opts: Options::default(),
88	            filter: 0,
89	            sort: SortKey::Name,
90	            ascending: true,
91	            ids: Vec::new(),
92	            ids_epoch: 0,
93	            error: None,
94	            millis: 0,
95	            serial: 0,
96	            shown_serial: 0,
97	            last_req: None,
98	            last_sent: Instant::now() - Duration::from_secs(10),
99	            selected: HashSet::new(),
100	            anchor: None,
101	            cursor: None,
102	            results_focus: false,
103	            scroll_to: None,
104	            columns: Columns::default(),
105	            status_bar: true,
106	            show_help: false,
107	            show_about: false,
108	            focus_search: true,
109	            title: String::new(),
110	            screenshot,
111	            frame: 0,
112	            shot_sent: false,
113	            show_filters: false,
114	            bookmarks: bookmarks::load(),
115	            message: None,
116	        }
117	    }
118	
119	    fn search_text(&self) -> String {
120	        let f = FILTERS[self.filter].1;
121	        match (f.is_empty(), self.query.trim().is_empty()) {
122	            (true, _) => self.query.clone(),
123	            (false, true) => f.to_string(),
124	            (false, false) => format!("{f} <{}>", self.query),
125	        }
126	    }
127	
128	    fn pump_search(&mut self) {
129	        let (generation, epoch, ready) = {
130	            let idx = self.index.read().unwrap();
131	            (idx.generation, idx.epoch, idx.ready)
132	        };
133	        let req = Request {
134	            text: self.search_text(),
135	            opts: self.opts,
136	            sort: self.sort,
137	            ascending: self.ascending,
138	            generation,
139	            epoch,
140	            serial: 0,
141	        };
142	        let changed_query = match &self.last_req {
143	            None => true,
144	            Some(l) => l.text != req.text || l.opts != req.opts || l.sort != req.sort || l.ascending != req.ascending || l.epoch != req.epoch,
145	        };
146	        let changed_gen = self.last_req.as_ref().is_some_and(|l| l.generation != req.generation);
147	        let wait = if ready { Duration::from_millis(300) } else { Duration::from_millis(1000) };
148	        if changed_query || (changed_gen && self.last_sent.elapsed() >= wait) {
149	            if changed_query {
150	                self.selected.clear();
151	                self.anchor = None;
152	                self.cursor = None;
153	                self.scroll_to = Some(0);
154	            }
155	            self.serial += 1;
156	            let mut r = req.clone();
157	            r.serial = self.serial;
158	            let _ = self.req_tx.send(r);
159	            self.last_req = Some(req);
160	            self.last_sent = Instant::now();
161	        }
162	        while let Ok(rep) = self.rep_rx.try_recv() {
163	            if rep.serial >= self.shown_serial {
164	                self.shown_serial = rep.serial;
165	                self.ids = rep.ids;
166	                self.ids_epoch = rep.epoch;
167	                self.error = rep.error;
168	                self.millis = rep.millis;
169	            }
170	        }
171	    }
172	
173	    fn entry_text(&self, id: u32, what: u8) -> String {
174	        let idx = self.index.read().unwrap();
175	        match idx.entries.get(id as usize) {
176	            Some(e) => match what {
177	                0 => idx.full_path(e),
178	                1 => idx.name(e).to_string(),
179	                _ => idx.dir_path(e).to_string(),
180	            },
181	            None => String::new(),
182	        }
183	    }
184	
185	    fn selected_paths(&self) -> Vec<String> {
186	        let idx = self.index.read().unwrap();
187	        self.ids
188	            .iter()
189	            .filter(|i| self.selected.contains(i))
190	            .filter_map(|i| idx.entries.get(*i as usize).map(|e| idx.full_path(e)))
191	            .collect()
192	    }
193	
194	    fn apply(&mut self, ctx: &egui::Context, a: RowAction) {
195	        match a {
196	            RowAction::Click { row, id, ctrl, shift } => {
197	                self.results_focus = true;
198	                if shift {
199	                    let from = self.anchor.unwrap_or(row);
200	                    let (lo, hi) = (from.min(row), from.max(row));
201	                    if !ctrl {
202	                        self.selected.clear();
203	                    }
204	                    self.selected.extend(self.ids[lo..=hi].iter().copied());
205	                } else if ctrl {
206	                    if !self.selected.remove(&id) {
207	                        self.selected.insert(id);
208	                    }
209	                    self.anchor = Some(row);
210	                } else {
211	                    self.selected.clear();
212	                    self.selected.insert(id);
213	                    self.anchor = Some(row);
214	                }
215	                self.cursor = Some(row);
216	            }
217	            RowAction::Open(id) => open(&self.entry_text(id, 0)),
218	            RowAction::OpenPath(id) => open_path(&self.entry_text(id, 0)),
219	            RowAction::CopyFull(id) => {
220	                let mut paths = self.selected_paths();
221	                if paths.is_empty() {
222	                    paths.push(self.entry_text(id, 0));
223	                }
224	                ctx.copy_text(paths.join("\r\n"));
225	            }
226	            RowAction::CopyName(id) => ctx.copy_text(self.entry_text(id, 1)),
227	            RowAction::CopyPath(id) => ctx.copy_text(self.entry_text(id, 2)),
228	            RowAction::Sort(k) => {
229	                if self.sort == k {
230	                    self.ascending = !self.ascending;
231	                } else {
232	                    self.sort = k;
233	                    // Sizes and dates start with the largest/newest, names with A.
234	                    self.ascending = matches!(k, SortKey::Name | SortKey::Path | SortKey::Extension);
235	                }
236	            }
237	        }
238	    }
239	
240	    fn move_cursor(&mut self, delta: i64, extend: bool) {
241	        if self.ids.is_empty() {
242	            return;
243	        }
244	        let last = self.ids.len() as i64 - 1;
245	        let cur = self.cursor.map(|c| c as i64).unwrap_or(-1);
246	        let next = (cur + delta).clamp(0, last) as usize;
247	        if extend {
248	            let from = self.anchor.unwrap_or(next);
249	            self.selected.clear();
250	            let (lo, hi) = (from.min(next), from.max(next));
251	            self.selected.extend(self.ids[lo..=hi].iter().copied());
252	        } else {
253	            self.selected.clear();
254	            self.selected.insert(self.ids[next]);
255	            self.anchor = Some(next);
256	        }
257	        self.cursor = Some(next);
258	        self.scroll_to = Some(next);
259	    }
260	
261	    fn keyboard(&mut self, ctx: &egui::Context) {
262	        let typing = ctx.memory(|m| m.focused().is_some()) && !self.results_focus;
263	        let (down, up, pgdn, pgup, home, end, enter, shift, cmd) = ctx.input(|i| {
264	            (
265	                i.key_pressed(Key::ArrowDown),
266	                i.key_pressed(Key::ArrowUp),
267	                i.key_pressed(Key::PageDown),
268	                i.key_pressed(Key::PageUp),
269	                i.key_pressed(Key::Home),
270	                i.key_pressed(Key::End),
271	                i.key_pressed(Key::Enter),
272	                i.modifiers.shift,
273	                i.modifiers.command,
274	            )
275	        });
276	        let toggles = ctx.input_mut(|i| {
277	            [Key::I, Key::B, Key::U, Key::M, Key::R, Key::F, Key::A, Key::C, Key::D]
278	                .map(|k| i.consume_key(egui::Modifiers::COMMAND, k))
279	        });
280	        if toggles[8] {
281	            bookmarks::add(&mut self.bookmarks, &self.query, self.filter, FILTERS[self.filter].0);
282	            self.message = Some(("Bookmark added".into(), Instant::now()));
283	        }
284	        if toggles[0] { self.opts.case = !self.opts.case; }
285	        if toggles[1] { self.opts.whole_word = !self.opts.whole_word; }
286	        if toggles[2] { self.opts.path = !self.opts.path; }
287	        if toggles[3] { self.opts.diacritics = !self.opts.diacritics; }
288	        if toggles[4] { self.opts.regex = !self.opts.regex; }
289	        if toggles[5] {
290	            self.focus_search = true;
291	            self.results_focus = false;
292	        }
293	        if self.results_focus && toggles[6] {
294	            self.selected = self.ids.iter().copied().collect();
295	        }
296	        if self.results_focus && toggles[7] {
297	            ctx.copy_text(self.selected_paths().join("\r\n"));
298	        }
299	        if typing && down {
300	            self.results_focus = true;
301	            ctx.memory_mut(|m| m.request_focus(egui::Id::new("results-focus")));
302	            self.move_cursor(if self.cursor.is_none() { 1 } else { 0 }, false);
303	            return;
304	        }
305	        if !self.results_focus {
306	            if enter && !self.ids.is_empty() {
307	                open(&self.entry_text(self.ids[self.cursor.unwrap_or(0)], 0));
308	            }
309	            return;
310	        }
311	        if down { self.move_cursor(1, shift); }
312	        if up {
313	            if self.cursor == Some(0) && !shift {
314	                self.results_focus = false;
315	                self.focus_search = true;
316	            } else {
317	                self.move_cursor(-1, shift);
318	            }
319	        }
320	        if pgdn { self.move_cursor(20, shift); }
321	        if pgup { self.move_cursor(-20, shift); }
322	        if home && !cmd { self.move_cursor(-(self.ids.len() as i64), shift); }
323	        if end && !cmd { self.move_cursor(self.ids.len() as i64, shift); }
324	        if enter {
325	            for p in self.selected_paths().into_iter().take(16) {
326	                open(&p);
327	            }
328	        }
329	    }
330	
331	}
332	
333	
334	impl eframe::App for App {
335	    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
336	        self.pump_search();
337	        self.keyboard(ctx);
338	        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
339	        if title != self.title {
340	            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
341	            self.title = title;
342	        }
343	
344	        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin::symmetric(4, 2))).show(ctx, |ui| {
345	            self.menus(ui, ctx);
346	        });
347	        egui::TopBottomPanel::top("search")
348	            .frame(egui::Frame::new().fill(Color32::WHITE).inner_margin(egui::Margin { left: 4, right: 4, top: 2, bottom: 4 }))
349	            .show(ctx, |ui| {
350	                ui.horizontal(|ui| {
351	                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
352	                        if self.show_filters {
353	                            egui::ComboBox::from_id_salt("filter")
354	                                .width(110.0)
355	                                .selected_text(FILTERS[self.filter].0)
356	                                .show_ui(ui, |ui| {
357	                                    for (i, (name, _)) in FILTERS.iter().enumerate() {
358	                                        ui.selectable_value(&mut self.filter, i, *name);
359	                                    }
360	                                });
361	                        }
362	                        let edit = egui::TextEdit::singleline(&mut self.query)
363	                            .hint_text("Search...")
364	                            .desired_width(f32::INFINITY)
365	                            .margin(egui::Margin::symmetric(6, 4))
366	                            .id(egui::Id::new("search-box"));
367	                        let resp = ui.add(edit);
368	                        if self.focus_search {
369	                            resp.request_focus();
370	                            self.focus_search = false;
371	                        }
372	                        if resp.gained_focus() || resp.changed() {
373	                            self.results_focus = false;
374	                        }
375	                    });
376	                });
377	            });
378	        if self.status_bar {
379	            egui::TopBottomPanel::bottom("status")
380	                .frame(egui::Frame::new().fill(Color32::from_rgb(240, 240, 240)).inner_margin(egui::Margin::symmetric(6, 3)))
381	                .show(ctx, |ui| self.status(ui));
382	        }
383	        let mut actions = Vec::new();
384	        egui::CentralPanel::default().frame(egui::Frame::new().fill(Color32::WHITE)).show(ctx, |ui| {
385	            let idx = self.index.read().unwrap();
386	            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
387	            let view = TableView {
388	                index: &idx,
389	                ids,
390	                selected: &self.selected,
391	                sort: self.sort,
392	                ascending: self.ascending,
393	                columns: self.columns,
394	                scroll_to: self.scroll_to.take(),
395	            };
396	            view.show(ui, &mut actions);
397	        });
398	        for a in actions {
399	            self.apply(ctx, a);
400	        }
401	        if self.show_help {
402	            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
403	                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
404	                    ui.monospace(crate::help::SYNTAX);
405	                });
406	            });
407	        }
408	        if self.show_about {
409	            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
410	                ui.heading(APP_NAME);
411	                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
412	                ui.label("Find files and folders by name, instantly.");
413	            });
414	        }
415	        self.screenshot_step(ctx);
416	        if self.progress.running.load(Ordering::Relaxed) {
417	            ctx.request_repaint_after(Duration::from_millis(250));
418	        }
419	    }
420	}
421	
422	impl App {
423	    fn screenshot_step(&mut self, ctx: &egui::Context) {
424	        let Some(path) = self.screenshot.clone() else { return };
425	        self.frame += 1;
426	        ctx.request_repaint();
427	        // About 120 frames, but wait (up to ~15 s) for the loaded index's first results.
428	        let settled = {
429	            let idx = self.index.read().unwrap();
430	            idx.entries.is_empty() || (idx.ready && self.ids_epoch == idx.epoch && self.shown_serial == self.serial)
431	        };
432	        if self.frame >= 120 && (settled || self.frame >= 900) && !self.shot_sent {
433	            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
434	            self.shot_sent = true;
435	        }
436	        let shot = ctx.input(|i| {
437	            i.raw.events.iter().find_map(|e| match e {
438	                egui::Event::Screenshot { image, .. } => Some(image.clone()),
439	                _ => None,
440	            })
441	        });
442	        if let Some(img) = shot {
443	            let [w, h] = img.size;
444	            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
445	            if let Some(parent) = path.parent() {
446	                let _ = std::fs::create_dir_all(parent);
447	            }
448	            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
449	                let _ = buf.save(&path);
450	            }
451	            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
452	        }
453	    }
454	}
