218	        Kind::Exe => Some(Color32::from_rgb(70, 120, 200)),
219	        Kind::Picture => Some(Color32::from_rgb(70, 160, 90)),
220	        Kind::Audio => Some(Color32::from_rgb(200, 90, 160)),
