//! The results list: columns, icons, sorting headers and row actions.

use crate::dates::format_filetime;
use crate::filters::{kind_of, Kind};
use crate::index::{Entry, Index};
use crate::platform::{attrib_text, size_text};
use crate::search::SortKey;
use eframe::egui::{self, Align, Color32, Layout, Rect, RichText, Sense, Stroke, Vec2};
use egui_extras::{Column, TableBuilder};

#[derive(Clone, Copy)]
pub struct Columns {
    pub path: bool,
    pub size: bool,
    pub extension: bool,
    pub modified: bool,
    pub created: bool,
    pub attributes: bool,
}

impl Default for Columns {
    fn default() -> Self {
        Columns { path: true, size: true, extension: false, modified: true, created: false, attributes: false }
    }
}

pub enum RowAction {
    Click { row: usize, id: u32, ctrl: bool, shift: bool },
    Open(u32),
    OpenPath(u32),
    CopyFull(u32),
    CopyName(u32),
    CopyPath(u32),
    Sort(SortKey),
}

pub struct TableView<'a> {
    pub index: &'a Index,
    pub ids: &'a [u32],
    pub selected: &'a std::collections::HashSet<u32>,
    pub sort: SortKey,
    pub ascending: bool,
    pub columns: Columns,
    pub scroll_to: Option<usize>,
}

pub const SORTED_COLUMN_TINT: Color32 = Color32::from_rgb(247, 247, 247);

impl<'a> TableView<'a> {
    pub fn show(&self, ui: &mut egui::Ui, actions: &mut Vec<RowAction>) {
        let mut cols: Vec<(SortKey, &str, f32, bool)> = vec![(SortKey::Name, "Name", 340.0, false)];
        let c = self.columns;
        if c.path {
            cols.push((SortKey::Path, "Path", 380.0, false));
        }
        if c.size {
            cols.push((SortKey::Size, "Size", 90.0, true));
        }
        if c.extension {
            cols.push((SortKey::Extension, "Extension", 70.0, false));
        }
        if c.modified {
            cols.push((SortKey::Modified, "Date Modified", 130.0, false));
        }
        if c.created {
            cols.push((SortKey::Created, "Date Created", 130.0, false));
        }
        if c.attributes {
            cols.push((SortKey::Attributes, "Attributes", 70.0, false));
        }
        let n_cols = cols.len();
        let mut table = TableBuilder::new(ui)
            .striped(false)
            .resizable(true)
            .sense(Sense::click())
            .cell_layout(Layout::left_to_right(Align::Center))
            .min_scrolled_height(0.0)
            .auto_shrink([false, false]);
        for (i, (_, _, w, _)) in cols.iter().enumerate() {
            let col = if i + 1 == n_cols { Column::remainder().at_least(60.0) } else { Column::initial(*w).at_least(40.0) };
            table = table.column(col.clip(true));
        }
        if let Some(r) = self.scroll_to {
            table = table.scroll_to_row(r, None);
        }
        table
            .header(22.0, |mut header| {
                for (key, title, _, right) in &cols {
                    header.col(|ui| {
                        let rect = ui.max_rect();
                        let resp = ui.interact(rect, ui.id().with(title), Sense::click());
                        if resp.hovered() {
                            ui.painter().rect_filled(rect, 0.0, Color32::from_rgb(229, 243, 255));
                        }
                        let text = title.to_string();
                        if *key == self.sort {
                            // A small caret above the header, like the original.
                            let (cx, cy) = (rect.center().x, rect.top() + 3.5);
                            let s = if self.ascending { 1.5 } else { -1.5 };
                            let pts = [egui::pos2(cx - 4.0, cy + s), egui::pos2(cx, cy - s), egui::pos2(cx + 4.0, cy + s)];
                            ui.painter().line_segment([pts[0], pts[1]], Stroke::new(1.0_f32, Color32::from_gray(110)));
                            ui.painter().line_segment([pts[1], pts[2]], Stroke::new(1.0_f32, Color32::from_gray(110)));
                        }
                        let layout = if *right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
                        ui.with_layout(layout, |ui| {
                            ui.add_space(4.0);
                            ui.label(RichText::new(text).color(Color32::from_gray(30)));
                        });
                        if resp.clicked() {
                            actions.push(RowAction::Sort(*key));
                        }
                    });
                }
            })
            .body(|body| {
                body.rows(20.0, self.ids.len(), |mut row| {
                    let r = row.index();
                    let id = self.ids[r];
                    let Some(e) = self.index.entries.get(id as usize) else { return };
                    row.set_selected(self.selected.contains(&id));
                    for (key, _, _, right) in &cols {
                        row.col(|ui| {
                            if *key == self.sort && !self.selected.contains(&id) {
                                ui.painter().rect_filled(ui.max_rect(), 0.0, SORTED_COLUMN_TINT);
                            }
                            self.cell(ui, *key, e, *right);
                        });
                    }
                    let resp = row.response();
                    if resp.double_clicked() {
                        actions.push(RowAction::Open(id));
                    } else if resp.clicked() || resp.secondary_clicked() {
                        let m = ui_modifiers(&resp);
                        if !(resp.secondary_clicked() && self.selected.contains(&id)) {
                            actions.push(RowAction::Click { row: r, id, ctrl: m.command, shift: m.shift });
                        }
                    }
                    resp.context_menu(|ui| {
                        if ui.button(RichText::new("Open").strong()).clicked() {
                            actions.push(RowAction::Open(id));
                            ui.close_menu();
                        }
                        if ui.button("Open Path").clicked() {
                            actions.push(RowAction::OpenPath(id));
                            ui.close_menu();
                        }
                        ui.separator();
                        if ui.button("Copy Full Name to Clipboard").clicked() {
                            actions.push(RowAction::CopyFull(id));
                            ui.close_menu();
                        }
                        if ui.button("Copy Name").clicked() {
                            actions.push(RowAction::CopyName(id));
                            ui.close_menu();
                        }
                        if ui.button("Copy Path").clicked() {
                            actions.push(RowAction::CopyPath(id));
                            ui.close_menu();
                        }
                    });
                });
            });
    }

    fn cell(&self, ui: &mut egui::Ui, key: SortKey, e: &Entry, right: bool) {
        let text_color = Color32::from_gray(20);
        let dim = Color32::from_gray(90);
        match key {
            SortKey::Name => {
                ui.add_space(2.0);
                draw_icon(ui, e, self.index.extension(e));
                ui.add_space(3.0);
                ui.add(egui::Label::new(RichText::new(self.index.name(e)).color(text_color)).truncate().selectable(false));
            }
            SortKey::Path => {
                ui.add_space(3.0);
                ui.add(egui::Label::new(RichText::new(self.index.dir_path(e)).color(text_color)).truncate().selectable(false));
            }
            _ => {
                let text = match key {
                    SortKey::Size => size_text(e.size, e.is_dir()),
                    SortKey::Extension => self.index.extension(e).to_lowercase(),
                    SortKey::Modified => format_filetime(e.mtime),
                    SortKey::Created => format_filetime(e.ctime),
                    SortKey::Attributes => attrib_text(e.attrs),
                    _ => String::new(),
                };
                let layout = if right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
                ui.with_layout(layout, |ui| {
                    ui.add_space(4.0);
                    ui.add(egui::Label::new(RichText::new(text).color(if right { text_color } else { dim })).selectable(false));
                });
            }
        }
    }
}

fn ui_modifiers(resp: &egui::Response) -> egui::Modifiers {
    resp.ctx.input(|i| i.modifiers)
}

/// A small drawn icon: a folder, or a page tinted by file kind.
pub fn draw_icon(ui: &mut egui::Ui, e: &Entry, ext: &str) {
    let (rect, _) = ui.allocate_exact_size(Vec2::new(16.0, 16.0), Sense::hover());
    let p = ui.painter();
    if e.is_dir() {
        let body = Rect::from_min_max(rect.min + Vec2::new(1.0, 4.0), rect.max - Vec2::new(1.0, 2.0));
        let tab = Rect::from_min_max(rect.min + Vec2::new(1.0, 2.0), rect.min + Vec2::new(7.0, 5.0));
        p.rect_filled(tab, 1.0, Color32::from_rgb(222, 170, 60));
        p.rect_filled(body, 1.5, Color32::from_rgb(246, 205, 98));
        p.line_segment([body.left_top() + Vec2::new(0.0, 2.5), body.right_top() + Vec2::new(0.0, 2.5)], Stroke::new(1.0_f32, Color32::from_rgb(255, 228, 150)));
        return;
    }
    let page = Rect::from_min_max(rect.min + Vec2::new(3.0, 1.0), rect.max - Vec2::new(2.0, 1.0));
    p.rect_filled(page, 1.0, Color32::WHITE);
    p.rect_stroke(page, 1.0, Stroke::new(1.0_f32, Color32::from_gray(150)), egui::StrokeKind::Inside);
    let band = match kind_of(ext) {
        Kind::Exe => Some(Color32::from_rgb(70, 120, 200)),
        Kind::Picture => Some(Color32::from_rgb(70, 160, 90)),
        Kind::Audio => Some(Color32::from_rgb(200, 90, 160)),
        Kind::Video => Some(Color32::from_rgb(140, 80, 200)),
        Kind::Archive => Some(Color32::from_rgb(190, 140, 60)),
        Kind::Document => Some(Color32::from_rgb(90, 140, 210)),
        Kind::Other => None,
    };
    match band {
        Some(c) => {
            let b = Rect::from_min_max(page.left_bottom() + Vec2::new(1.0, -6.0), page.right_bottom() - Vec2::new(1.0, 1.0));
            p.rect_filled(b, 0.0, c);
        }
        None => {
            for k in 0..3 {
                let y = page.top() + 4.0 + k as f32 * 3.0;
                p.line_segment([egui::pos2(page.left() + 2.0, y), egui::pos2(page.right() - 2.0, y)], Stroke::new(1.0_f32, Color32::from_gray(200)));
            }
        }
    }
}

