86	    pub(super) fn export(&mut self) {
87	        let Some(path) = rfd::FileDialog::new()
88	            .set_file_name("results.efu")
89	            .add_filter("File List", &["efu", "csv"])
90	            .save_file()
91	        else {
92	            return;
93	        };
94	        let idx = self.index.read().unwrap();
95	        let mut out = String::from("Filename,Size,Date Modified,Date Created,Attributes\r\n");
96	        for &i in &self.ids {
97	            let Some(e) = idx.entries.get(i as usize) else { continue };
98	            let size = if e.is_dir() { String::new() } else { e.size.to_string() };
99	            out.push_str(&format!("\"{}\",{},{},{},{}\r\n", idx.full_path(e).replace('"', "\"\""), size, e.mtime, e.ctime, e.attrs));
100	        }
101	        let msg = match std::fs::write(&path, out) {
102	            Ok(_) => format!("Exported {} results", thousands(self.ids.len() as u64)),
103	            Err(e) => format!("Export failed: {e}"),
104	        };
105	        self.message = Some((msg, Instant::now()));
106	    }
107	
108	    pub(super) fn status(&self, ui: &mut egui::Ui) {
109	        ui.horizontal(|ui| {
110	            let text = if let Some(err) = &self.error {
111	                err.clone()
112	            } else if self.selected.len() == 1 && self.ids.len() == 1 {
113	                "1 of 1 objects selected".to_string()
114	            } else if !self.selected.is_empty() {
115	                format!("{} objects selected", thousands(self.selected.len() as u64))
116	            } else {
117	                format!("{} objects", thousands(self.ids.len() as u64))
118	            };
119	            ui.label(RichText::new(text).color(Color32::from_gray(40)));
120	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
121	                ui.add_space(6.0);
122	                let mut flags = Vec::new();
123	                if self.opts.case { flags.push("CASE"); }
124	                if self.opts.whole_word { flags.push("WHOLE WORD"); }
125	                if self.opts.path { flags.push("PATH"); }
126	                if self.opts.diacritics { flags.push("DIACRITICS"); }
127	                if self.opts.regex { flags.push("REGEX"); }
128	                for f in flags.iter().rev() {
129	                    ui.label(RichText::new(*f).small().strong().color(Color32::from_gray(70)));
130	                }
131	                if self.progress.running.load(Ordering::Relaxed) {
132	                    let found = self.progress.found.load(Ordering::Relaxed);
133	                    let cur = self.progress.current.lock().map(|c| c.clone()).unwrap_or_default();
134	                    let short: String = cur.chars().take(60).collect();
135	                    ui.label(RichText::new(format!("Indexing {short}...  {} found", thousands(found))).color(Color32::from_gray(90)));
136	                } else if let Some((m, at)) = &self.message {
137	                    if at.elapsed() < Duration::from_secs(5) {
138	                        ui.label(m);
139	                    }
140	                }
141	            });
142	        });
143	    }
144	}
145	
146	fn toggle(ui: &mut egui::Ui, v: &mut bool, label: &str, shortcut: &str) {
147	    let text = if *v { format!("\u{2714}  {label}") } else { format!("     {label}") };
148	    if ui.add(egui::Button::new(text).shortcut_text(shortcut)).clicked() {
149	        *v = !*v;
150	        ui.close_menu();
151	    }
152	}
