1	//! The results list: columns, icons, sorting headers and row actions.
2	
3	use crate::dates::format_filetime;
4	use crate::filters::{kind_of, Kind};
5	use crate::index::{Entry, Index};
6	use crate::platform::{attrib_text, size_text};
7	use crate::search::SortKey;
8	use eframe::egui::{self, Align, Color32, Layout, Rect, RichText, Sense, Stroke, Vec2};
9	use egui_extras::{Column, TableBuilder};
10	
11	#[derive(Clone, Copy)]
12	pub struct Columns {
13	    pub path: bool,
14	    pub size: bool,
15	    pub extension: bool,
16	    pub modified: bool,
17	    pub created: bool,
18	    pub attributes: bool,
19	}
20	
21	impl Default for Columns {
22	    fn default() -> Self {
23	        Columns { path: true, size: true, extension: false, modified: true, created: false, attributes: false }
24	    }
25	}
26	
27	pub enum RowAction {
28	    Click { row: usize, id: u32, ctrl: bool, shift: bool },
29	    Open(u32),
30	    OpenPath(u32),
31	    CopyFull(u32),
32	    CopyName(u32),
33	    CopyPath(u32),
34	    Sort(SortKey),
35	}
36	
37	pub struct TableView<'a> {
38	    pub index: &'a Index,
39	    pub ids: &'a [u32],
40	    pub selected: &'a std::collections::HashSet<u32>,
41	    pub sort: SortKey,
42	    pub ascending: bool,
43	    pub columns: Columns,
44	    pub scroll_to: Option<usize>,
45	}
46	
47	pub const SORTED_COLUMN_TINT: Color32 = Color32::from_rgb(247, 247, 247);
48	
49	impl<'a> TableView<'a> {
50	    pub fn show(&self, ui: &mut egui::Ui, actions: &mut Vec<RowAction>) {
51	        let mut cols: Vec<(SortKey, &str, f32, bool)> = vec![(SortKey::Name, "Name", 340.0, false)];
52	        let c = self.columns;
53	        if c.path {
54	            cols.push((SortKey::Path, "Path", 380.0, false));
55	        }
56	        if c.size {
57	            cols.push((SortKey::Size, "Size", 90.0, true));
58	        }
59	        if c.extension {
60	            cols.push((SortKey::Extension, "Extension", 70.0, false));
61	        }
62	        if c.modified {
63	            cols.push((SortKey::Modified, "Date Modified", 130.0, false));
64	        }
65	        if c.created {
66	            cols.push((SortKey::Created, "Date Created", 130.0, false));
67	        }
68	        if c.attributes {
69	            cols.push((SortKey::Attributes, "Attributes", 70.0, false));
70	        }
71	        let n_cols = cols.len();
72	        let mut table = TableBuilder::new(ui)
73	            .striped(false)
74	            .resizable(true)
75	            .sense(Sense::click())
76	            .cell_layout(Layout::left_to_right(Align::Center))
77	            .min_scrolled_height(0.0)
78	            .auto_shrink([false, false]);
79	        for (i, (_, _, w, _)) in cols.iter().enumerate() {
80	            let col = if i + 1 == n_cols { Column::remainder().at_least(60.0) } else { Column::initial(*w).at_least(40.0) };
81	            table = table.column(col.clip(true));
82	        }
83	        if let Some(r) = self.scroll_to {
84	            table = table.scroll_to_row(r, None);
85	        }
86	        table
87	            .header(22.0, |mut header| {
88	                for (key, title, _, right) in &cols {
89	                    header.col(|ui| {
90	                        let rect = ui.max_rect();
91	                        let resp = ui.interact(rect, ui.id().with(title), Sense::click());
92	                        if resp.hovered() {
93	                            ui.painter().rect_filled(rect, 0.0, Color32::from_rgb(229, 243, 255));
94	                        }
95	                        let text = title.to_string();
96	                        if *key == self.sort {
97	                            // A small caret above the header, like the original.
98	                            let (cx, cy) = (rect.center().x, rect.top() + 3.5);
99	                            let s = if self.ascending { 1.5 } else { -1.5 };
100	                            let pts = [egui::pos2(cx - 4.0, cy + s), egui::pos2(cx, cy - s), egui::pos2(cx + 4.0, cy + s)];
101	                            ui.painter().line_segment([pts[0], pts[1]], Stroke::new(1.0_f32, Color32::from_gray(110)));
102	                            ui.painter().line_segment([pts[1], pts[2]], Stroke::new(1.0_f32, Color32::from_gray(110)));
103	                        }
104	                        let layout = if *right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
105	                        ui.with_layout(layout, |ui| {
106	                            ui.add_space(4.0);
107	                            ui.label(RichText::new(text).color(Color32::from_gray(30)));
108	                        });
109	                        if resp.clicked() {
110	                            actions.push(RowAction::Sort(*key));
111	                        }
112	                    });
113	                }
114	            })
115	            .body(|body| {
116	                body.rows(20.0, self.ids.len(), |mut row| {
117	                    let r = row.index();
118	                    let id = self.ids[r];
119	                    let Some(e) = self.index.entries.get(id as usize) else { return };
120	                    row.set_selected(self.selected.contains(&id));
121	                    for (key, _, _, right) in &cols {
122	                        row.col(|ui| {
123	                            if *key == self.sort && !self.selected.contains(&id) {
124	                                ui.painter().rect_filled(ui.max_rect(), 0.0, SORTED_COLUMN_TINT);
125	                            }
126	                            self.cell(ui, *key, e, *right);
127	                        });
128	                    }
129	                    let resp = row.response();
130	                    if resp.double_clicked() {
131	                        actions.push(RowAction::Open(id));
132	                    } else if resp.clicked() || resp.secondary_clicked() {
133	                        let m = ui_modifiers(&resp);
134	                        if !(resp.secondary_clicked() && self.selected.contains(&id)) {
135	                            actions.push(RowAction::Click { row: r, id, ctrl: m.command, shift: m.shift });
136	                        }
137	                    }
138	                    resp.context_menu(|ui| {
139	                        if ui.button(RichText::new("Open").strong()).clicked() {
140	                            actions.push(RowAction::Open(id));
141	                            ui.close_menu();
142	                        }
143	                        if ui.button("Open Path").clicked() {
144	                            actions.push(RowAction::OpenPath(id));
145	                            ui.close_menu();
146	                        }
147	                        ui.separator();
148	                        if ui.button("Copy Full Name to Clipboard").clicked() {
149	                            actions.push(RowAction::CopyFull(id));
150	                            ui.close_menu();
151	                        }
152	                        if ui.button("Copy Name").clicked() {
153	                            actions.push(RowAction::CopyName(id));
154	                            ui.close_menu();
155	                        }
156	                        if ui.button("Copy Path").clicked() {
157	                            actions.push(RowAction::CopyPath(id));
158	                            ui.close_menu();
159	                        }
160	                    });
161	                });
162	            });
163	    }
164	
165	    fn cell(&self, ui: &mut egui::Ui, key: SortKey, e: &Entry, right: bool) {
166	        let text_color = Color32::from_gray(20);
167	        let dim = Color32::from_gray(90);
168	        match key {
169	            SortKey::Name => {
170	                ui.add_space(2.0);
171	                draw_icon(ui, e, self.index.extension(e));
172	                ui.add_space(3.0);
173	                ui.add(egui::Label::new(RichText::new(self.index.name(e)).color(text_color)).truncate().selectable(false));
174	            }
175	            SortKey::Path => {
176	                ui.add_space(3.0);
177	                ui.add(egui::Label::new(RichText::new(self.index.dir_path(e)).color(text_color)).truncate().selectable(false));
178	            }
179	            _ => {
180	                let text = match key {
181	                    SortKey::Size => size_text(e.size, e.is_dir()),
182	                    SortKey::Extension => self.index.extension(e).to_lowercase(),
183	                    SortKey::Modified => format_filetime(e.mtime),
184	                    SortKey::Created => format_filetime(e.ctime),
185	                    SortKey::Attributes => attrib_text(e.attrs),
186	                    _ => String::new(),
187	                };
188	                let layout = if right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
189	                ui.with_layout(layout, |ui| {
190	                    ui.add_space(4.0);
191	                    ui.add(egui::Label::new(RichText::new(text).color(if right { text_color } else { dim })).selectable(false));
192	                });
193	            }
194	        }
195	    }
196	}
197	
198	fn ui_modifiers(resp: &egui::Response) -> egui::Modifiers {
199	    resp.ctx.input(|i| i.modifiers)
200	}
201	
202	/// A small drawn icon: a folder, or a page tinted by file kind.
203	pub fn draw_icon(ui: &mut egui::Ui, e: &Entry, ext: &str) {
204	    let (rect, _) = ui.allocate_exact_size(Vec2::new(16.0, 16.0), Sense::hover());
205	    let p = ui.painter();
206	    if e.is_dir() {
207	        let body = Rect::from_min_max(rect.min + Vec2::new(1.0, 4.0), rect.max - Vec2::new(1.0, 2.0));
208	        let tab = Rect::from_min_max(rect.min + Vec2::new(1.0, 2.0), rect.min + Vec2::new(7.0, 5.0));
209	        p.rect_filled(tab, 1.0, Color32::from_rgb(222, 170, 60));
