1	//! Start-up: fonts and colours, loading the saved index, scanning and rebuilding.
2	
3	use crate::index::{self, Index};
4	use crate::scan::{self, Progress};
5	use eframe::egui::{self, Color32};
6	use std::path::PathBuf;
7	use std::sync::atomic::Ordering;
8	use std::sync::{Arc, RwLock};
9	use std::time::Duration;
10	
11	pub fn setup_style(ctx: &egui::Context) {
12	    let mut fonts = egui::FontDefinitions::default();
13	    for (name, file) in [("ui", "segoeui.ttf"), ("sym", "seguisym.ttf")] {
14	        let p = PathBuf::from(std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into())).join("Fonts").join(file);
15	        if let Ok(bytes) = std::fs::read(p) {
16	            fonts.font_data.insert(name.into(), Arc::new(egui::FontData::from_owned(bytes)));
17	            let fam = fonts.families.entry(egui::FontFamily::Proportional).or_default();
18	            if name == "ui" { fam.insert(0, name.into()); } else { fam.push(name.into()); }
19	        }
20	    }
21	    ctx.set_fonts(fonts);
22	    ctx.set_visuals(egui::Visuals::light());
23	    ctx.style_mut(|s| {
24	        s.text_styles.insert(egui::TextStyle::Body, egui::FontId::proportional(13.0));
25	        s.text_styles.insert(egui::TextStyle::Button, egui::FontId::proportional(13.0));
26	        s.spacing.item_spacing = egui::vec2(6.0, 2.0);
27	        s.visuals.selection.bg_fill = Color32::from_rgb(204, 232, 255);
28	        s.visuals.selection.stroke = egui::Stroke::new(1.0_f32, Color32::from_rgb(20, 20, 20));
29	        s.visuals.panel_fill = Color32::WHITE;
30	        s.visuals.widgets.hovered.weak_bg_fill = Color32::from_rgb(229, 243, 255);
31	        s.visuals.extreme_bg_color = Color32::WHITE;
32	    });
33	}
34	
35	/// Load the saved index (instant results), then refresh it from disk and watch for changes.
36	pub fn start_indexing(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context, screenshot: bool) {
37	    std::thread::spawn(move || {
38	        let roots = scan::fixed_drives();
39	        if let Some(mut l) = index::load() {
40	            let mut live = index.write().unwrap();
41	            l.epoch = live.epoch + 1;
42	            *live = l;
43	            drop(live);
44	            ctx.request_repaint();
45	            if screenshot {
46	                return;
47	            }
48	            refresh(&index, &progress, &roots, &ctx);
49	        } else {
50	            scan::scan_into(&index, &roots, &progress);
51	            ctx.request_repaint();
52	            if screenshot {
53	                return;
54	            }
55	        }
56	        let _ = index::save(&index.read().unwrap());
57	        crate::watch::start(index.clone(), roots, ctx.clone());
58	        // Save live changes now and then.
59	        let mut saved = index.read().unwrap().generation;
60	        loop {
61	            std::thread::sleep(Duration::from_secs(600));
62	            let idx = index.read().unwrap();
63	            if idx.generation != saved && !progress.running.load(Ordering::Relaxed) {
64	                let _ = index::save(&idx);
65	                saved = idx.generation;
66	            }
67	        }
68	    });
69	}
70	
71	/// Scan into a fresh index, then swap it in whole.
72	fn refresh(index: &Arc<RwLock<Index>>, progress: &Arc<Progress>, roots: &[String], ctx: &egui::Context) {
73	    let fresh = Arc::new(RwLock::new(Index::default()));
74	    scan::scan_into(&fresh, roots, progress);
75	    let mut new_index = std::mem::take(&mut *fresh.write().unwrap());
76	    let mut live = index.write().unwrap();
77	    new_index.epoch = live.epoch + 1;
78	    new_index.generation = live.generation + 1;
79	    *live = new_index;
80	    drop(live);
81	    ctx.request_repaint();
82	}
83	
84	pub fn rebuild(index: Arc<RwLock<Index>>, progress: Arc<Progress>, ctx: egui::Context) {
85	    if progress.running.load(Ordering::Relaxed) {
86	        return;
87	    }
88	    std::thread::spawn(move || {
89	        let roots = scan::fixed_drives();
90	        refresh(&index, &progress, &roots, &ctx);
91	        let _ = index::save(&index.read().unwrap());
92	    });
93	}
