        font_id: font,
        color: pal.accent,
        background: pal.sel,
        ..Default::default()
    };
    let mut job = LayoutJob::default();
    let mut at = 0;
    for (s, e) in merged {
        if !name.is_char_boundary(s) || !name.is_char_boundary(e) {
            continue;
        }
        if s > at {
            job.append(&name[at..s], 0.0, plain.clone());
        }
        job.append(&name[s..e], 0.0, marked.clone());
        at = e;
    }
    if at < name.len() {
        job.append(&name[at..], 0.0, plain);
    }
    job
}

/// A small drawn icon: a two-tone folder, or a page with a folded corner tinted by file kind.
pub fn draw_icon(ui: &mut egui::Ui, e: &Entry, ext: &str, pal: &Pal) {
    let (rect, _) = ui.allocate_exact_size(Vec2::new(18.0, 18.0), Sense::hover());
    let p = ui.painter();
    if e.is_dir() {
        let tab = Rect::from_min_max(rect.min + Vec2::new(1.0, 2.0), rect.min + Vec2::new(8.0, 6.0));
        let body = Rect::from_min_max(rect.min + Vec2::new(1.0, 4.5), rect.max - Vec2::new(1.0, 2.0));
        p.rect_filled(tab, 2.0, Color32::from_rgb(226, 160, 52));
        p.rect_filled(body, 2.5, Color32::from_rgb(251, 191, 74));
        p.rect_filled(
            Rect::from_min_max(body.left_top() + Vec2::new(0.0, 3.0), body.right_bottom()),
            2.5,
            Color32::from_rgb(253, 211, 108),
        );
        return;
    }
    let page = Rect::from_min_max(rect.min + Vec2::new(3.5, 1.0), rect.max - Vec2::new(2.5, 1.0));
    let (fill, edge) = if pal.dark {
        (Color32::from_rgb(52, 56, 70), Color32::from_rgb(86, 92, 112))
    } else {
        (Color32::WHITE, Color32::from_gray(170))
    };
    p.rect_filled(page, 2.0, fill);
    p.rect_stroke(page, 2.0, Stroke::new(1.0_f32, edge), egui::StrokeKind::Inside);
    let fold = 4.0;
    p.add(Shape::convex_polygon(
        vec![
            egui::pos2(page.right() - fold, page.top()),
            egui::pos2(page.right(), page.top() + fold),
            egui::pos2(page.right() - fold, page.top() + fold),
        ],
        edge,
        Stroke::NONE,
    ));
    let band = match kind_of(ext) {
        Kind::Exe => Some(Color32::from_rgb(79, 129, 230)),
        Kind::Picture => Some(Color32::from_rgb(52, 180, 110)),
        Kind::Audio => Some(Color32::from_rgb(220, 90, 170)),
        Kind::Video => Some(Color32::from_rgb(150, 90, 230)),
        Kind::Archive => Some(Color32::from_rgb(214, 150, 50)),
        Kind::Document => Some(Color32::from_rgb(99, 130, 240)),
        Kind::Other => None,
    };
    match band {
        Some(c) => {
            let b = Rect::from_min_max(page.left_bottom() + Vec2::new(1.5, -6.5), page.right_bottom() - Vec2::new(1.5, 1.5));
            p.rect_filled(b, 1.5, c);
        }
        None => {
            for k in 0..3 {
                let y = page.top() + 7.0 + k as f32 * 3.0;
                p.line_segment([egui::pos2(page.left() + 2.5, y), egui::pos2(page.right() - 2.5, y)], Stroke::new(1.0_f32, edge));
            }
        }
    }
}

