//! The results list: columns, icons, match highlighting, sorting headers and row actions.

use crate::dates::format_filetime;
use crate::filters::{kind_of, Kind};
use crate::index::{Entry, Index};
use crate::platform::{attrib_text, size_text};
use crate::search::SortKey;
use crate::theme::Pal;
use eframe::egui::{
    self, text::LayoutJob, Align, Color32, CornerRadius, Layout, Rect, RichText, Sense, Shape, Stroke, TextFormat, Vec2,
};
use egui_extras::{Column, TableBuilder};

#[derive(Clone, Copy)]
pub struct Columns {
    pub path: bool,
    pub size: bool,
    pub extension: bool,
    pub modified: bool,
    pub created: bool,
    pub attributes: bool,
}

impl Default for Columns {
    fn default() -> Self {
        Columns { path: true, size: true, extension: false, modified: true, created: false, attributes: false }
    }
}

pub enum RowAction {
    Click { row: usize, id: u32, ctrl: bool, shift: bool },
    Open(u32),
    OpenWith(u32),
    OpenPath(u32),
    CopyFull(u32),
    CopyName(u32),
    CopyPath(u32),
    Rename(u32),
    Delete(u32),
    Properties(u32),
    Sort(SortKey),
}

pub struct TableView<'a> {
    pub index: &'a Index,
    pub ids: &'a [u32],
    pub selected: &'a std::collections::HashSet<u32>,
    pub sort: SortKey,
    pub ascending: bool,
    pub columns: Columns,
    pub scroll_to: Option<usize>,
    pub pal: Pal,
    pub row_h: f32,
    /// Lower-case text pieces of the search, highlighted inside names.
    pub terms: &'a [String],
}

impl<'a> TableView<'a> {
    pub fn show(&self, ui: &mut egui::Ui, actions: &mut Vec<RowAction>) {
        let mut cols: Vec<(SortKey, &str, f32, bool)> = vec![(SortKey::Name, "Name", 340.0, false)];
        let c = self.columns;
        if c.path {
            cols.push((SortKey::Path, "Path", 380.0, false));
        }
        if c.size {
            cols.push((SortKey::Size, "Size", 96.0, true));
        }
        if c.extension {
            cols.push((SortKey::Extension, "Extension", 80.0, false));
        }
        if c.modified {
            cols.push((SortKey::Modified, "Date Modified", 140.0, false));
        }
        if c.created {
            cols.push((SortKey::Created, "Date Created", 140.0, false));
        }
        if c.attributes {
            cols.push((SortKey::Attributes, "Attributes", 80.0, false));
        }
        let n_cols = cols.len();
        ui.spacing_mut().item_spacing = Vec2::ZERO;
        let table_x = ui.max_rect().x_range();
        let mut table = TableBuilder::new(ui)
            .striped(false)
            .resizable(true)
            .sense(Sense::click())
            .cell_layout(Layout::left_to_right(Align::Center))
            .min_scrolled_height(0.0)
            .auto_shrink([false, false]);
        for (i, (_, _, w, _)) in cols.iter().enumerate() {
            let col = if i + 1 == n_cols { Column::remainder().at_least(60.0) } else { Column::initial(*w).at_least(40.0) };
            table = table.column(col.clip(true));
        }
        if let Some(r) = self.scroll_to {
            table = table.scroll_to_row(r, None);
        }
        let pal = self.pal;
        table
            .header(30.0, |mut header| {
                for (key, title, _, right) in &cols {
                    header.col(|ui| {
                        let rect = ui.max_rect();
                        let resp = ui.interact(rect, ui.id().with(*title), Sense::click());
                        if resp.hovered() {
                            ui.painter().rect_filled(rect, 0.0, pal.hover);
                        }
                        ui.painter().hline(rect.x_range(), rect.bottom() - 0.5, Stroke::new(1.0_f32, pal.line));
                        let sorted = *key == self.sort;
                        let layout = if *right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
                        ui.with_layout(layout, |ui| {
                            ui.add_space(10.0);
                            let color = if sorted { pal.text } else { pal.dim };
                            ui.label(RichText::new(*title).size(12.0).strong().color(color));
                            if sorted {
                                ui.add_space(5.0);
                                let (r, _) = ui.allocate_exact_size(Vec2::new(9.0, 6.0), Sense::hover());
                                let pts = if self.ascending {
                                    vec![r.left_bottom(), r.right_bottom(), egui::pos2(r.center().x, r.top())]
                                } else {
                                    vec![r.left_top(), r.right_top(), egui::pos2(r.center().x, r.bottom())]
                                };
                                ui.painter().add(Shape::convex_polygon(pts, pal.accent, Stroke::NONE));
                            }
                        });
                        if resp.clicked() {
                            actions.push(RowAction::Sort(*key));
                        }
                    });
                }
            })
            .body(|body| {
                body.rows(self.row_h, self.ids.len(), |mut row| {
                    let r = row.index();
                    let id = self.ids[r];
                    let Some(e) = self.index.entries.get(id as usize) else { return };
                    let selected = self.selected.contains(&id);
                    for (i, (key, _, _, right)) in cols.iter().enumerate() {
                        row.col(|ui| {
                            self.paint_row_bg(ui, i, n_cols, selected, table_x);
                            self.cell(ui, *key, e, *right);
                        });
                    }
                    let resp = row.response();
                    if resp.double_clicked() {
                        actions.push(RowAction::Open(id));
                    } else if resp.clicked() || resp.secondary_clicked() {
                        let m = resp.ctx.input(|i| i.modifiers);
                        if !(resp.secondary_clicked() && selected) {
                            actions.push(RowAction::Click { row: r, id, ctrl: m.command, shift: m.shift });
                        }
                    }
                    resp.context_menu(|ui| context_menu(ui, id, actions));
                });
            });
    }

    /// Rounded selection / hover band across the row, with a faint divider otherwise.
    fn paint_row_bg(&self, ui: &mut egui::Ui, i: usize, n: usize, selected: bool, table_x: egui::Rangef) {
        let r = ui.max_rect();
        let hovered = ui.input(|inp| {
            inp.pointer.hover_pos().is_some_and(|p| r.y_range().contains(p.y) && table_x.contains(p.x))
        });
        if selected || hovered {
            let radius = CornerRadius {
                nw: if i == 0 { 8 } else { 0 },
                sw: if i == 0 { 8 } else { 0 },
                ne: if i + 1 == n { 8 } else { 0 },
                se: if i + 1 == n { 8 } else { 0 },
            };
            let fill = if selected { self.pal.sel } else { self.pal.hover };
            ui.painter().rect_filled(r.shrink2(Vec2::new(0.0, 1.0)), radius, fill);
        } else {
            ui.painter().hline(r.x_range(), r.bottom() - 0.5, Stroke::new(1.0_f32, self.pal.line));
        }
    }

    fn cell(&self, ui: &mut egui::Ui, key: SortKey, e: &Entry, right: bool) {
        let pal = self.pal;
        match key {
            SortKey::Name => {
                ui.add_space(10.0);
                draw_icon(ui, e, self.index.extension(e), &pal);
                ui.add_space(8.0);
                let font = egui::TextStyle::Body.resolve(ui.style());
                let job = name_job(self.index.name(e), self.terms, font, &pal);
                ui.add(egui::Label::new(job).truncate().selectable(false));
            }
            SortKey::Path => {
                ui.add_space(10.0);
                ui.add(egui::Label::new(RichText::new(self.index.dir_path(e)).color(pal.dim)).truncate().selectable(false));
            }
            _ => {
                let text = match key {
                    SortKey::Size => size_text(e.size, e.is_dir()),
                    SortKey::Extension => self.index.extension(e).to_lowercase(),
                    SortKey::Modified => format_filetime(e.mtime),
                    SortKey::Created => format_filetime(e.ctime),
                    SortKey::Attributes => attrib_text(e.attrs),
                    _ => String::new(),
                };
                let layout = if right { Layout::right_to_left(Align::Center) } else { Layout::left_to_right(Align::Center) };
                ui.with_layout(layout, |ui| {
                    ui.add_space(10.0);
                    ui.add(egui::Label::new(RichText::new(text).color(if right { pal.text } else { pal.dim })).selectable(false));
                });
            }
        }
    }
}

fn context_menu(ui: &mut egui::Ui, id: u32, actions: &mut Vec<RowAction>) {
    let mut item = |ui: &mut egui::Ui, label: &str, shortcut: &str, strong: bool, act: RowAction| {
        let text = if strong { RichText::new(label).strong() } else { RichText::new(label) };
        if ui.add(egui::Button::new(text).shortcut_text(shortcut).frame(false).min_size(Vec2::new(210.0, 22.0))).clicked() {
            actions.push(act);
            ui.close_menu();
        }
    };
    item(ui, "Open", "Enter", true, RowAction::Open(id));
    item(ui, "Open With...", "", false, RowAction::OpenWith(id));
    item(ui, "Open Folder", "", false, RowAction::OpenPath(id));
    ui.separator();
    item(ui, "Copy Full Path", "Ctrl+C", false, RowAction::CopyFull(id));
    item(ui, "Copy Name", "", false, RowAction::CopyName(id));
    item(ui, "Copy Folder Path", "", false, RowAction::CopyPath(id));
    ui.separator();
    item(ui, "Rename...", "F2", false, RowAction::Rename(id));
    item(ui, "Delete (Recycle Bin)", "Del", false, RowAction::Delete(id));
    ui.separator();
    item(ui, "Properties", "Alt+Enter", false, RowAction::Properties(id));
}

/// The name with every search term shown in the accent colour.
fn name_job(name: &str, terms: &[String], font: egui::FontId, pal: &Pal) -> LayoutJob {
    let lower = name.to_ascii_lowercase();
    let mut ranges: Vec<(usize, usize)> = Vec::new();
    for t in terms {
        if t.is_empty() {
            continue;
        }
        for (s, m) in lower.match_indices(t.as_str()) {
            ranges.push((s, s + m.len()));
        }
    }
    ranges.sort_unstable();
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for (s, e) in ranges {
        match merged.last_mut() {
            Some(l) if s <= l.1 => l.1 = l.1.max(e),
            _ => merged.push((s, e)),
        }
    }
    let plain = TextFormat { font_id: font.clone(), color: pal.text, ..Default::default() };
    let marked = TextFormat {
        font_id: font,
        color: pal.accent,
        background: pal.sel,
        ..Default::default()
    };
    let mut job = LayoutJob::default();
    let mut at = 0;
    for (s, e) in merged {
        if !name.is_char_boundary(s) || !name.is_char_boundary(e) {
            continue;
        }
        if s > at {
            job.append(&name[at..s], 0.0, plain.clone());
        }
        job.append(&name[s..e], 0.0, marked.clone());
        at = e;
    }
    if at < name.len() {
        job.append(&name[at..], 0.0, plain);
    }
    job
}

/// A small drawn icon: a two-tone folder, or a page with a folded corner tinted by file kind.
