//! The main window: state, search, selection, keyboard and the frame layout.

use crate::bookmarks::{self, Bookmark};
use crate::filters::FILTERS;
use crate::index::Index;
use crate::platform::{open, open_path};
use crate::preview::{self, Body, Preview};
use crate::query::Options;
use crate::scan::Progress;
use crate::search::{self, Reply, Request, SortKey};
use crate::settings::Settings;
use crate::startup::{setup_style, start_indexing};
use crate::table::{Columns, RowAction, TableView};
use crate::theme;
use eframe::egui::{self, Key};
use std::collections::HashSet;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub const APP_NAME: &str = "Quickfind";

#[path = "ui_start.rs"]
mod start;
pub use start::StartOptions;
#[path = "ui_menus.rs"]
mod menus;
#[path = "ui_bar.rs"]
mod bar;
#[path = "ui_panels.rs"]
mod panels;

pub struct App {
    index: Arc<RwLock<Index>>,
    progress: Arc<Progress>,
    req_tx: Sender<Request>,
    rep_rx: Receiver<Reply>,
    query: String,
    opts: Options,
    filter: usize,
    sort: SortKey,
    ascending: bool,
    ids: Vec<u32>,
    ids_epoch: u64,
    error: Option<String>,
    millis: u128,
    serial: u64,
    shown_serial: u64,
    last_req: Option<Request>,
    last_sent: Instant,
    selected: HashSet<u32>,
    anchor: Option<usize>,
    cursor: Option<usize>,
    results_focus: bool,
    scroll_to: Option<usize>,
    columns: Columns,
    status_bar: bool,
    show_help: bool,
    show_about: bool,
    show_options: bool,
    opt_tab: u8,
    focus_search: bool,
    title: String,
    screenshot: Option<PathBuf>,
    frame: u32,
    shot_sent: bool,
    bookmarks: Vec<Bookmark>,
    message: Option<(String, Instant)>,
    settings: Settings,
    preview: Option<Preview>,
    preview_for: Option<u32>,
    rename: Option<(u32, String)>,
    confirm_delete: Option<Vec<String>>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>, start: StartOptions) -> Self {
        let mut app = Self::create(cc, screenshot);
        start.apply(&mut app);
        app
    }

    fn create(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        let settings = Settings::load();
        settings.apply_rules();
        setup_style(&cc.egui_ctx, settings.dark);
        egui_extras::install_image_loaders(&cc.egui_ctx);
        let index = Arc::new(RwLock::new(Index::default()));
        let progress = Arc::new(Progress::default());
        let (req_tx, req_rx) = channel();
        let (rep_tx, rep_rx) = channel();
        search::spawn(index.clone(), req_rx, rep_tx, cc.egui_ctx.clone());
        start_indexing(index.clone(), progress.clone(), cc.egui_ctx.clone(), screenshot.is_some());
        App {
            index,
            progress,
            req_tx,
            rep_rx,
            query: String::new(),
            opts: settings.opts,
            filter: 0,
            sort: SortKey::Name,
            ascending: true,
            ids: Vec::new(),
            ids_epoch: 0,
            error: None,
            millis: 0,
            serial: 0,
            shown_serial: 0,
            last_req: None,
            last_sent: Instant::now() - Duration::from_secs(10),
            selected: HashSet::new(),
            anchor: None,
            cursor: None,
            results_focus: false,
            scroll_to: None,
            columns: settings.columns,
            status_bar: settings.status_bar,
            show_help: false,
            show_about: false,
            show_options: false,
            opt_tab: 0,
            focus_search: true,
            title: String::new(),
            screenshot,
            frame: 0,
            shot_sent: false,
            bookmarks: bookmarks::load(),
            message: None,
            settings,
            preview: None,
            preview_for: None,
            rename: None,
            confirm_delete: None,
        }
    }

    /// Write the current choices to disk.
    fn save_settings(&mut self) {
        self.settings.columns = self.columns;
        self.settings.status_bar = self.status_bar;
        self.settings.opts = self.opts;
        self.settings.save();
    }

    fn search_text(&self) -> String {
        let f = FILTERS[self.filter].1;
        match (f.is_empty(), self.query.trim().is_empty()) {
            (true, _) => self.query.clone(),
            (false, true) => f.to_string(),
            (false, false) => format!("{f} <{}>", self.query),
        }
    }

    /// Plain words of the search, shown highlighted in the names.
    fn highlight_terms(&self) -> Vec<String> {
        if self.opts.regex {
            return Vec::new();
        }
        let mut out = Vec::new();
        for tok in self.query.split_whitespace() {
            if tok.starts_with('!') || tok.contains(':') || tok.contains('\\') {
                continue;
            }
            for part in tok.split(['|', '*', '?', '<', '>', '"']) {
                if !part.is_empty() {
                    out.push(part.to_ascii_lowercase());
                }
            }
        }
        out
    }

    fn pump_search(&mut self) {
        let (generation, epoch, ready) = {
            let idx = self.index.read().unwrap();
            (idx.generation, idx.epoch, idx.ready)
        };
        let req = Request {
            text: self.search_text(),
            opts: self.opts,
            sort: self.sort,
            ascending: self.ascending,
            generation,
            epoch,
            serial: 0,
        };
        let changed_query = match &self.last_req {
            None => true,
            Some(l) => l.text != req.text || l.opts != req.opts || l.sort != req.sort || l.ascending != req.ascending || l.epoch != req.epoch,
        };
        let changed_gen = self.last_req.as_ref().is_some_and(|l| l.generation != req.generation);
        let wait = if ready { Duration::from_millis(300) } else { Duration::from_millis(1000) };
        if changed_query || (changed_gen && self.last_sent.elapsed() >= wait) {
            if changed_query {
                self.selected.clear();
                self.anchor = None;
                self.cursor = None;
                self.scroll_to = Some(0);
            }
            self.serial += 1;
            let mut r = req.clone();
            r.serial = self.serial;
            let _ = self.req_tx.send(r);
            self.last_req = Some(req);
            self.last_sent = Instant::now();
        }
        while let Ok(rep) = self.rep_rx.try_recv() {
            if rep.serial >= self.shown_serial {
                self.shown_serial = rep.serial;
                self.ids = rep.ids;
                self.ids_epoch = rep.epoch;
                self.error = rep.error;
                self.millis = rep.millis;
            }
        }
    }

    /// Keep the preview pane in step with the selection.
    fn refresh_preview(&mut self, ctx: &egui::Context) {
        let want = if self.settings.preview && self.selected.len() == 1 { self.selected.iter().next().copied() } else { None };
        if want == self.preview_for {
            return;
        }
        if let Some(Preview { body: Body::Image(uri), .. }) = &self.preview {
            ctx.forget_image(uri);
        }
        self.preview = want.and_then(|id| preview::build(&self.index.read().unwrap(), id));
        self.preview_for = want;
    }

    fn entry_text(&self, id: u32, what: u8) -> String {
        let idx = self.index.read().unwrap();
        match idx.entries.get(id as usize) {
            Some(e) => match what {
                0 => idx.full_path(e),
                1 => idx.name(e).to_string(),
                _ => idx.dir_path(e).to_string(),
            },
            None => String::new(),
        }
    }

    fn selected_paths(&self) -> Vec<String> {
        let idx = self.index.read().unwrap();
        self.ids
            .iter()
            .filter(|i| self.selected.contains(i))
            .filter_map(|i| idx.entries.get(*i as usize).map(|e| idx.full_path(e)))
            .collect()
    }

    fn first_selected(&self) -> Option<u32> {
        self.ids.iter().copied().find(|i| self.selected.contains(i))
    }

    fn start_rename(&mut self, id: u32) {
        self.rename = Some((id, self.entry_text(id, 1)));
    }

    fn start_delete(&mut self, id: u32) {
        let paths = if self.selected.contains(&id) { self.selected_paths() } else { vec![self.entry_text(id, 0)] };
        self.confirm_delete = Some(paths);
    }

    fn apply(&mut self, ctx: &egui::Context, a: RowAction) {
        match a {
            RowAction::Click { row, id, ctrl, shift } => {
                self.results_focus = true;
                if shift {
                    let from = self.anchor.unwrap_or(row);
                    let (lo, hi) = (from.min(row), from.max(row));
                    if !ctrl {
                        self.selected.clear();
                    }
                    self.selected.extend(self.ids[lo..=hi].iter().copied());
                } else if ctrl {
                    if !self.selected.remove(&id) {
                        self.selected.insert(id);
                    }
                    self.anchor = Some(row);
                } else {
                    self.selected.clear();
                    self.selected.insert(id);
                    self.anchor = Some(row);
                }
                self.cursor = Some(row);
            }
            RowAction::Open(id) => open(&self.entry_text(id, 0)),
            RowAction::OpenWith(id) => crate::actions::open_with(&self.entry_text(id, 0)),
            RowAction::OpenPath(id) => open_path(&self.entry_text(id, 0)),
            RowAction::CopyFull(id) => {
                let mut paths = self.selected_paths();
                if paths.is_empty() {
                    paths.push(self.entry_text(id, 0));
                }
                ctx.copy_text(paths.join("\r\n"));
            }
            RowAction::CopyName(id) => ctx.copy_text(self.entry_text(id, 1)),
            RowAction::CopyPath(id) => ctx.copy_text(self.entry_text(id, 2)),
            RowAction::Rename(id) => self.start_rename(id),
            RowAction::Delete(id) => self.start_delete(id),
            RowAction::Properties(id) => crate::actions::properties(&self.entry_text(id, 0)),
            RowAction::Sort(k) => {
                if self.sort == k {
                    self.ascending = !self.ascending;
                } else {
                    self.sort = k;
                    // Sizes and dates start with the largest/newest, names with A.
                    self.ascending = matches!(k, SortKey::Name | SortKey::Path | SortKey::Extension);
                }
            }
        }
    }

    fn move_cursor(&mut self, delta: i64, extend: bool) {
        if self.ids.is_empty() {
            return;
        }
        let last = self.ids.len() as i64 - 1;
        let cur = self.cursor.map(|c| c as i64).unwrap_or(-1);
        let next = (cur + delta).clamp(0, last) as usize;
        if extend {
            let from = self.anchor.unwrap_or(next);
            self.selected.clear();
            let (lo, hi) = (from.min(next), from.max(next));
            self.selected.extend(self.ids[lo..=hi].iter().copied());
        } else {
            self.selected.clear();
            self.selected.insert(self.ids[next]);
            self.anchor = Some(next);
        }
        self.cursor = Some(next);
        self.scroll_to = Some(next);
    }

    fn keyboard(&mut self, ctx: &egui::Context) {
        let typing = ctx.memory(|m| m.focused().is_some()) && !self.results_focus;
        let dialog_open = self.rename.is_some() || self.confirm_delete.is_some();
        let (down, up, pgdn, pgup, home, end, enter, shift, cmd, alt, f2, del) = ctx.input(|i| {
            (
                i.key_pressed(Key::ArrowDown),
                i.key_pressed(Key::ArrowUp),
                i.key_pressed(Key::PageDown),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::Enter),
                i.modifiers.shift,
                i.modifiers.command,
                i.modifiers.alt,
                i.key_pressed(Key::F2),
                i.key_pressed(Key::Delete),
            )
        });
        let toggles = ctx.input_mut(|i| {
            [Key::I, Key::B, Key::U, Key::M, Key::R, Key::F, Key::A, Key::C, Key::D]
                .map(|k| i.consume_key(egui::Modifiers::COMMAND, k))
        });
        if toggles[8] {
            bookmarks::add(&mut self.bookmarks, &self.query, self.filter, FILTERS[self.filter].0);
            self.message = Some(("Bookmark added".into(), Instant::now()));
        }
        if toggles[..5].iter().any(|t| *t) {
            let o = &mut self.opts;
            for (on, flag) in toggles[..5].iter().zip([&mut o.case, &mut o.whole_word, &mut o.path, &mut o.diacritics, &mut o.regex]) {
                if *on {
                    *flag = !*flag;
                }
            }
            self.save_settings();
        }
        if toggles[5] {
            self.focus_search = true;
            self.results_focus = false;
        }
        if self.results_focus && toggles[6] {
            self.selected = self.ids.iter().copied().collect();
        }
        if self.results_focus && toggles[7] {
            ctx.copy_text(self.selected_paths().join("\r\n"));
        }
        if dialog_open {
            return;
        }
        if typing && down {
            self.results_focus = true;
            ctx.memory_mut(|m| m.request_focus(egui::Id::new("results-focus")));
            self.move_cursor(if self.cursor.is_none() { 1 } else { 0 }, false);
            return;
        }
        if !self.results_focus {
            if enter && !self.ids.is_empty() {
                open(&self.entry_text(self.ids[self.cursor.unwrap_or(0)], 0));
            }
            return;
        }
        if down { self.move_cursor(1, shift); }
        if up {
            if self.cursor == Some(0) && !shift {
                self.results_focus = false;
                self.focus_search = true;
            } else {
                self.move_cursor(-1, shift);
            }
        }
        if pgdn { self.move_cursor(20, shift); }
        if pgup { self.move_cursor(-20, shift); }
        if home && !cmd { self.move_cursor(-(self.ids.len() as i64), shift); }
        if end && !cmd { self.move_cursor(self.ids.len() as i64, shift); }
        if f2 {
            if let Some(id) = self.first_selected() { self.start_rename(id); }
        }
        if del && !self.selected.is_empty() {
            if let Some(id) = self.first_selected() { self.start_delete(id); }
        }
        if enter && alt {
            if let Some(id) = self.first_selected() { crate::actions::properties(&self.entry_text(id, 0)); }
        } else if enter {
            for p in self.selected_paths().into_iter().take(16) {
                open(&p);
            }
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.pump_search();
        self.keyboard(ctx);
        self.refresh_preview(ctx);
        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }
        let pal = theme::get(ctx);
        let line = egui::Stroke::new(1.0_f32, pal.line);

        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin::symmetric(8, 3))).show(ctx, |ui| {
            self.menus(ui, ctx);
        });
        egui::TopBottomPanel::top("search")
            .frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin { left: 14, right: 14, top: 6, bottom: 10 }))
            .show(ctx, |ui| self.search_bar(ui, ctx));
        if self.status_bar {
            egui::TopBottomPanel::bottom("status")
                .frame(egui::Frame::new().fill(pal.bg).stroke(line).inner_margin(egui::Margin::symmetric(14, 5)))
                .show(ctx, |ui| self.status(ui));
        }
        if self.settings.preview {
            egui::SidePanel::right("preview")
                .resizable(true)
                .default_width(300.0)
                .width_range(230.0..=520.0)
                .frame(egui::Frame::new().fill(pal.panel).stroke(line).inner_margin(egui::Margin::same(16)))
                .show(ctx, |ui| self.preview_pane(ui));
        }
        let mut actions = Vec::new();
        let terms = self.highlight_terms();
        egui::CentralPanel::default().frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin::symmetric(8, 0))).show(ctx, |ui| {
            let idx = self.index.read().unwrap();
            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
            let view = TableView {
                index: &idx,
                ids,
                selected: &self.selected,
                sort: self.sort,
                ascending: self.ascending,
                columns: self.columns,
                scroll_to: self.scroll_to.take(),
                pal,
                row_h: if self.settings.compact { 24.0 } else { 30.0 },
                terms: &terms,
            };
            view.show(ui, &mut actions);
        });
        for a in actions {
            self.apply(ctx, a);
        }
        self.dialogs(ctx);
        if self.show_help {
            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.monospace(crate::help::SYNTAX);
                });
            });
        }
        if self.show_about {
            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.heading(APP_NAME);
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.label("Find files and folders by name, instantly.");
            });
        }
        self.screenshot_step(ctx);
        if self.progress.running.load(Ordering::Relaxed) {
            ctx.request_repaint_after(Duration::from_millis(60));
        }
    }
}

impl App {
    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frame += 1;
        ctx.request_repaint();
        // About 120 frames, but wait (up to ~15 s) for the loaded index's first results.
        let settled = {
            let idx = self.index.read().unwrap();
            idx.entries.is_empty() || (idx.ready && self.ids_epoch == idx.epoch && self.shown_serial == self.serial)
        };
        if self.frame >= 120 && (settled || self.frame >= 900) && !self.shot_sent {
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
            self.shot_sent = true;
        }
        let shot = ctx.input(|i| {
            i.raw.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                let _ = buf.save(&path);
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

input.content:
//! The main window: state, search, selection, keyboard and the frame layout.

use crate::bookmarks::{self, Bookmark};
use crate::filters::FILTERS;
use crate::index::Index;
use crate::platform::{open, open_path};
use crate::preview::{self, Body, Preview};
use crate::query::Options;
use crate::scan::Progress;
use crate::search::{self, Reply, Request, SortKey};
use crate::settings::Settings;
use crate::startup::{setup_style, start_indexing};
use crate::table::{Columns, RowAction, TableView};
use crate::theme;
use eframe::egui::{self, Key};
use std::collections::HashSet;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub const APP_NAME: &str = "Quickfind";

#[path = "ui_start.rs"]
mod start;
pub use start::StartOptions;
#[path = "ui_menus.rs"]
mod menus;
#[path = "ui_bar.rs"]
mod bar;
#[path = "ui_panels.rs"]
mod panels;

pub struct App {
    index: Arc<RwLock<Index>>,
    progress: Arc<Progress>,
    req_tx: Sender<Request>,
    rep_rx: Receiver<Reply>,
    query: String,
    opts: Options,
    filter: usize,
    sort: SortKey,
    ascending: bool,
    ids: Vec<u32>,
    ids_epoch: u64,
    error: Option<String>,
    millis: u128,
    serial: u64,
    shown_serial: u64,
    last_req: Option<Request>,
    last_sent: Instant,
    selected: HashSet<u32>,
    anchor: Option<usize>,
    cursor: Option<usize>,
    results_focus: bool,
    scroll_to: Option<usize>,
    columns: Columns,
    status_bar: bool,
    show_help: bool,
    show_about: bool,
    show_options: bool,
    opt_tab: u8,
    focus_search: bool,
    title: String,
    screenshot: Option<PathBuf>,
    frame: u32,
    shot_sent: bool,
    bookmarks: Vec<Bookmark>,
    message: Option<(String, Instant)>,
    settings: Settings,
    preview: Option<Preview>,
    preview_for: Option<u32>,
    rename: Option<(u32, String)>,
    confirm_delete: Option<Vec<String>>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>, start: StartOptions) -> Self {
        let mut app = Self::create(cc, screenshot);
        start.apply(&mut app);
        app
    }

    fn create(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        let settings = Settings::load();
        settings.apply_rules();
        setup_style(&cc.egui_ctx, settings.dark);
        egui_extras::install_image_loaders(&cc.egui_ctx);
        let index = Arc::new(RwLock::new(Index::default()));
        let progress = Arc::new(Progress::default());
        let (req_tx, req_rx) = channel();
        let (rep_tx, rep_rx) = channel();
        search::spawn(index.clone(), req_rx, rep_tx, cc.egui_ctx.clone());
        start_indexing(index.clone(), progress.clone(), cc.egui_ctx.clone(), screenshot.is_some());
        App {
            index,
            progress,
            req_tx,
            rep_rx,
            query: String::new(),
            opts: settings.opts,
            filter: 0,
            sort: SortKey::Name,
            ascending: true,
            ids: Vec::new(),
            ids_epoch: 0,
            error: None,
            millis: 0,
            serial: 0,
            shown_serial: 0,
            last_req: None,
            last_sent: Instant::now() - Duration::from_secs(10),
            selected: HashSet::new(),
            anchor: None,
            cursor: None,
            results_focus: false,
            scroll_to: None,
            columns: settings.columns,
            status_bar: settings.status_bar,
            show_help: false,
            show_about: false,
            show_options: false,
            opt_tab: 0,
            focus_search: true,
            title: String::new(),
            screenshot,
            frame: 0,
            shot_sent: false,
            bookmarks: bookmarks::load(),
            message: None,
            settings,
            preview: None,
            preview_for: None,
            rename: None,
            confirm_delete: None,
        }
    }

    /// Write the current choices to disk.
    fn save_settings(&mut self) {
        self.settings.columns = self.columns;
        self.settings.status_bar = self.status_bar;
        self.settings.opts = self.opts;
        self.settings.save();
    }

    fn search_text(&self) -> String {
        let f = FILTERS[self.filter].1;
        match (f.is_empty(), self.query.trim().is_empty()) {
            (true, _) => self.query.clone(),
            (false, true) => f.to_string(),
            (false, false) => format!("{f} <{}>", self.query),
        }
    }

    /// Plain words of the search, shown highlighted in the names.
    fn highlight_terms(&self) -> Vec<String> {
        if self.opts.regex {
            return Vec::new();
        }
        let mut out = Vec::new();
        for tok in self.query.split_whitespace() {
            if tok.starts_with('!') || tok.contains(':') || tok.contains('\\') {
                continue;
            }
            for part in tok.split(['|', '*', '?', '<', '>', '"']) {
                if !part.is_empty() {
                    out.push(part.to_ascii_lowercase());
                }
            }
        }
        out
    }

    fn pump_search(&mut self) {
        let (generation, epoch, ready) = {
            let idx = self.index.read().unwrap();
            (idx.generation, idx.epoch, idx.ready)
        };
        let req = Request {
            text: self.search_text(),
            opts: self.opts,
            sort: self.sort,
            ascending: self.ascending,
            generation,
            epoch,
            serial: 0,
        };
        let changed_query = match &self.last_req {
            None => true,
            Some(l) => l.text != req.text || l.opts != req.opts || l.sort != req.sort || l.ascending != req.ascending || l.epoch != req.epoch,
        };
        let changed_gen = self.last_req.as_ref().is_some_and(|l| l.generation != req.generation);
        let wait = if ready { Duration::from_millis(300) } else { Duration::from_millis(1000) };
        if changed_query || (changed_gen && self.last_sent.elapsed() >= wait) {
            if changed_query {
                self.selected.clear();
                self.anchor = None;
                self.cursor = None;
                self.scroll_to = Some(0);
            }
            self.serial += 1;
            let mut r = req.clone();
            r.serial = self.serial;
            let _ = self.req_tx.send(r);
            self.last_req = Some(req);
            self.last_sent = Instant::now();
        }
        while let Ok(rep) = self.rep_rx.try_recv() {
            if rep.serial >= self.shown_serial {
                self.shown_serial = rep.serial;
                self.ids = rep.ids;
                self.ids_epoch = rep.epoch;
                self.error = rep.error;
                self.millis = rep.millis;
            }
        }
    }

    /// Keep the preview pane in step with the selection.
    fn refresh_preview(&mut self, ctx: &egui::Context) {
        let want = if self.settings.preview && self.selected.len() == 1 { self.selected.iter().next().copied() } else { None };
        if want == self.preview_for {
            return;
        }
        if let Some(Preview { body: Body::Image(uri), .. }) = &self.preview {
            ctx.forget_image(uri);
        }
        self.preview = want.and_then(|id| preview::build(&self.index.read().unwrap(), id));
        self.preview_for = want;
    }

    fn entry_text(&self, id: u32, what: u8) -> String {
        let idx = self.index.read().unwrap();
        match idx.entries.get(id as usize) {
            Some(e) => match what {
                0 => idx.full_path(e),
                1 => idx.name(e).to_string(),
                _ => idx.dir_path(e).to_string(),
            },
            None => String::new(),
        }
    }

    fn selected_paths(&self) -> Vec<String> {
        let idx = self.index.read().unwrap();
        self.ids
            .iter()
            .filter(|i| self.selected.contains(i))
            .filter_map(|i| idx.entries.get(*i as usize).map(|e| idx.full_path(e)))
            .collect()
    }

    fn first_selected(&self) -> Option<u32> {
        self.ids.iter().copied().find(|i| self.selected.contains(i))
    }

    fn start_rename(&mut self, id: u32) {
        self.rename = Some((id, self.entry_text(id, 1)));
    }

    fn start_delete(&mut self, id: u32) {
        let paths = if self.selected.contains(&id) { self.selected_paths() } else { vec![self.entry_text(id, 0)] };
        self.confirm_delete = Some(paths);
    }

    fn apply(&mut self, ctx: &egui::Context, a: RowAction) {
        match a {
            RowAction::Click { row, id, ctrl, shift } => {
                self.results_focus = true;
                if shift {
                    let from = self.anchor.unwrap_or(row);
                    let (lo, hi) = (from.min(row), from.max(row));
                    if !ctrl {
                        self.selected.clear();
                    }
                    self.selected.extend(self.ids[lo..=hi].iter().copied());
                } else if ctrl {
                    if !self.selected.remove(&id) {
                        self.selected.insert(id);
                    }
                    self.anchor = Some(row);
                } else {
                    self.selected.clear();
                    self.selected.insert(id);
                    self.anchor = Some(row);
                }
                self.cursor = Some(row);
            }
            RowAction::Open(id) => open(&self.entry_text(id, 0)),
            RowAction::OpenWith(id) => crate::actions::open_with(&self.entry_text(id, 0)),
            RowAction::OpenPath(id) => open_path(&self.entry_text(id, 0)),
            RowAction::CopyFull(id) => {
                let mut paths = self.selected_paths();
                if paths.is_empty() {
                    paths.push(self.entry_text(id, 0));
                }
                ctx.copy_text(paths.join("\r\n"));
            }
            RowAction::CopyName(id) => ctx.copy_text(self.entry_text(id, 1)),
            RowAction::CopyPath(id) => ctx.copy_text(self.entry_text(id, 2)),
            RowAction::Rename(id) => self.start_rename(id),
            RowAction::Delete(id) => self.start_delete(id),
            RowAction::Properties(id) => crate::actions::properties(&self.entry_text(id, 0)),
            RowAction::Sort(k) => {
                if self.sort == k {
                    self.ascending = !self.ascending;
                } else {
                    self.sort = k;
                    // Sizes and dates start with the largest/newest, names with A.
                    self.ascending = matches!(k, SortKey::Name | SortKey::Path | SortKey::Extension);
                }
            }
        }
    }

    fn move_cursor(&mut self, delta: i64, extend: bool) {
        if self.ids.is_empty() {
            return;
        }
        let last = self.ids.len() as i64 - 1;
        let cur = self.cursor.map(|c| c as i64).unwrap_or(-1);
        let next = (cur + delta).clamp(0, last) as usize;
        if extend {
            let from = self.anchor.unwrap_or(next);
            self.selected.clear();
            let (lo, hi) = (from.min(next), from.max(next));
            self.selected.extend(self.ids[lo..=hi].iter().copied());
        } else {
            self.selected.clear();
            self.selected.insert(self.ids[next]);
            self.anchor = Some(next);
        }
        self.cursor = Some(next);
        self.scroll_to = Some(next);
    }

    fn keyboard(&mut self, ctx: &egui::Context) {
        let typing = ctx.memory(|m| m.focused().is_some()) && !self.results_focus;
        let dialog_open = self.rename.is_some() || self.confirm_delete.is_some();
        let (down, up, pgdn, pgup, home, end, enter, shift, cmd, alt, f2, del) = ctx.input(|i| {
            (
                i.key_pressed(Key::ArrowDown),
                i.key_pressed(Key::ArrowUp),
                i.key_pressed(Key::PageDown),
                i.key_pressed(Key::PageUp),
                i.key_pressed(Key::Home),
                i.key_pressed(Key::End),
                i.key_pressed(Key::Enter),
                i.modifiers.shift,
                i.modifiers.command,
                i.modifiers.alt,
                i.key_pressed(Key::F2),
                i.key_pressed(Key::Delete),
            )
        });
        let toggles = ctx.input_mut(|i| {
            [Key::I, Key::B, Key::U, Key::M, Key::R, Key::F, Key::A, Key::C, Key::D]
                .map(|k| i.consume_key(egui::Modifiers::COMMAND, k))
        });
        if toggles[8] {
            bookmarks::add(&mut self.bookmarks, &self.query, self.filter, FILTERS[self.filter].0);
            self.message = Some(("Bookmark added".into(), Instant::now()));
        }
        if toggles[..5].iter().any(|t| *t) {
            let o = &mut self.opts;
            for (on, flag) in toggles[..5].iter().zip([&mut o.case, &mut o.whole_word, &mut o.path, &mut o.diacritics, &mut o.regex]) {
                if *on {
                    *flag = !*flag;
                }
            }
            self.save_settings();
        }
        if toggles[5] {
            self.focus_search = true;
            self.results_focus = false;
        }
        if self.results_focus && toggles[6] {
            self.selected = self.ids.iter().copied().collect();
        }
        if self.results_focus && toggles[7] {
            ctx.copy_text(self.selected_paths().join("\r\n"));
        }
        if dialog_open {
            return;
        }
        if typing && down {
            self.results_focus = true;
            ctx.memory_mut(|m| m.request_focus(egui::Id::new("results-focus")));
            self.move_cursor(if self.cursor.is_none() { 1 } else { 0 }, false);
            return;
        }
        if !self.results_focus {
            if enter && !self.ids.is_empty() {
                open(&self.entry_text(self.ids[self.cursor.unwrap_or(0)], 0));
            }
            return;
        }
        if down { self.move_cursor(1, shift); }
        if up {
            if self.cursor == Some(0) && !shift {
                self.results_focus = false;
                self.focus_search = true;
            } else {
                self.move_cursor(-1, shift);
            }
        }
        if pgdn { self.move_cursor(20, shift); }
        if pgup { self.move_cursor(-20, shift); }
        if home && !cmd { self.move_cursor(-(self.ids.len() as i64), shift); }
        if end && !cmd { self.move_cursor(self.ids.len() as i64, shift); }
        if f2 {
            if let Some(id) = self.first_selected() { self.start_rename(id); }
        }
        if del && !self.selected.is_empty() {
            if let Some(id) = self.first_selected() { self.start_delete(id); }
        }
        if enter && alt {
            if let Some(id) = self.first_selected() { crate::actions::properties(&self.entry_text(id, 0)); }
        } else if enter {
            for p in self.selected_paths().into_iter().take(16) {
                open(&p);
            }
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.pump_search();
        self.keyboard(ctx);
        self.refresh_preview(ctx);
        let title = if self.query.is_empty() { APP_NAME.to_string() } else { format!("{} - {APP_NAME}", self.query) };
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }
        let pal = theme::get(ctx);
        let line = egui::Stroke::new(1.0_f32, pal.line);

        egui::TopBottomPanel::top("menu").frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin::symmetric(8, 3))).show(ctx, |ui| {
            self.menus(ui, ctx);
        });
        egui::TopBottomPanel::top("search")
            .frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin { left: 14, right: 14, top: 6, bottom: 10 }))
            .show(ctx, |ui| self.search_bar(ui, ctx));
        if self.status_bar {
            egui::TopBottomPanel::bottom("status")
                .frame(egui::Frame::new().fill(pal.bg).stroke(line).inner_margin(egui::Margin::symmetric(14, 5)))
                .show(ctx, |ui| self.status(ui));
        }
        if self.settings.preview {
            egui::SidePanel::right("preview")
                .resizable(true)
                .default_width(300.0)
                .width_range(230.0..=520.0)
                .frame(egui::Frame::new().fill(pal.panel).stroke(line).inner_margin(egui::Margin::same(16)))
                .show(ctx, |ui| self.preview_pane(ui));
        }
        let mut actions = Vec::new();
        let terms = self.highlight_terms();
        egui::CentralPanel::default().frame(egui::Frame::new().fill(pal.panel).inner_margin(egui::Margin::symmetric(8, 0))).show(ctx, |ui| {
            let idx = self.index.read().unwrap();
            let ids: &[u32] = if self.ids_epoch == idx.epoch { &self.ids } else { &[] };
            let view = TableView {
                index: &idx,
                ids,
                selected: &self.selected,
                sort: self.sort,
                ascending: self.ascending,
                columns: self.columns,
                scroll_to: self.scroll_to.take(),
                pal,
                row_h: if self.settings.compact { 24.0 } else { 30.0 },
                terms: &terms,
            };
            view.show(ui, &mut actions);
        });
        for a in actions {
            self.apply(ctx, a);
        }
        self.dialogs(ctx);
        if self.show_help {
            egui::Window::new("Search Syntax").open(&mut self.show_help).default_width(460.0).show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.monospace(crate::help::SYNTAX);
                });
            });
        }
        if self.show_about {
            egui::Window::new(format!("About {APP_NAME}")).open(&mut self.show_about).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.heading(APP_NAME);
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.label("Find files and folders by name, instantly.");
            });
        }
        self.screenshot_step(ctx);
        if self.progress.running.load(Ordering::Relaxed) {
            ctx.request_repaint_after(Duration::from_millis(60));
        }
    }
}

impl App {
    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frame += 1;
        ctx.request_repaint();
        // About 120 frames, but wait (up to ~15 s) for the loaded index's first results.
        let settled = {
            let idx = self.index.read().unwrap();
            idx.entries.is_empty() || (idx.ready && self.ids_epoch == idx.epoch && self.shown_serial == self.serial)
        };
        if self.frame >= 120 && (settled || self.frame >= 900) && !self.shot_sent {
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
            self.shot_sent = true;
        }
        let shot = ctx.input(|i| {
            i.raw.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                let _ = buf.save(&path);
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

//! Search bar with option chips, filter pills and the status bar.

use super::App;
use crate::platform::{human_size, thousands};
use crate::theme::{self, Pal};
use eframe::egui::{self, pos2, vec2, Align, Color32, Layout, Rect, RichText, Sense, Stroke};
use std::sync::atomic::Ordering;
use std::time::Duration;

/// Pill label -> index into FILTERS.
const PILLS: [(&str, usize); 8] =
    [("All", 0), ("Folders", 5), ("Documents", 3), ("Pictures", 6), ("Audio", 1), ("Video", 7), ("Archives", 2), ("Apps", 4)];

impl App {
    pub(super) fn search_bar(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        let pal = theme::get(ctx);
        let mut changed = false;
        egui::Frame::new()
            .fill(pal.raised)
            .corner_radius(12)
            .stroke(Stroke::new(1.0_f32, pal.line))
            .inner_margin(egui::Margin::symmetric(14, 8))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    magnifier(ui, pal.accent);
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let o = &mut self.opts;
                        changed |= chip(ui, &pal, ".*", "Regular expressions (Ctrl+R)", &mut o.regex);
                        changed |= chip(ui, &pal, "\u{e9}", "Match accents (Ctrl+M)", &mut o.diacritics);
                        changed |= chip(ui, &pal, "Path", "Match full path (Ctrl+U)", &mut o.path);
                        changed |= chip(ui, &pal, "Word", "Match whole words (Ctrl+B)", &mut o.whole_word);
                        changed |= chip(ui, &pal, "Aa", "Match case (Ctrl+I)", &mut o.case);
                        if !self.query.is_empty() {
                            let x = egui::Button::new(RichText::new("\u{2715}").size(12.0).color(pal.dim)).frame(false);
                            if ui.add(x).on_hover_text("Clear").clicked() {
                                self.query.clear();
                                self.focus_search = true;
                            }
                        }
                        let edit = egui::TextEdit::singleline(&mut self.query)
                            .hint_text(RichText::new("Search files and folders...").color(pal.dim))
                            .font(egui::FontId::proportional(16.0))
                            .frame(false)
                            .desired_width(f32::INFINITY)
                            .margin(egui::Margin::symmetric(8, 2))
                            .id(egui::Id::new("search-box"));
                        let resp = ui.add(edit);
                        if self.focus_search {
                            resp.request_focus();
                            self.focus_search = false;
                        }
                        if resp.gained_focus() || resp.changed() {
                            self.results_focus = false;
                        }
                    });
                });
            });
        if changed {
            self.save_settings();
        }
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 6.0;
            for (label, idx) in PILLS {
                if pill(ui, &pal, label, self.filter == idx) {
                    self.filter = idx;
                }
            }
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                let icon = if self.settings.dark { "\u{2600}" } else { "\u{263E}" };
                let b = egui::Button::new(RichText::new(icon).size(15.0).color(pal.dim)).frame(false);
                if ui.add(b).on_hover_text("Switch between dark and light").clicked() {
                    self.settings.dark = !self.settings.dark;
                    theme::apply(ctx, self.settings.dark);
                    self.save_settings();
                }
                let on = self.settings.preview;
                if chip(ui, &pal, "Preview", "Show or hide the preview pane", &mut self.settings.preview) {
                    self.save_settings();
                }
                let _ = on;
            });
        });
    }

    pub(super) fn status(&self, ui: &mut egui::Ui) {
        let pal = theme::get(ui.ctx());
        ui.horizontal(|ui| {
            let selected = self.selected.len();
            let text = if let Some(err) = &self.error {
                err.clone()
            } else if selected == 1 && self.ids.len() == 1 {
                "1 of 1 objects selected".to_string()
            } else if selected > 0 {
                let mut t = format!("{} objects selected", thousands(selected as u64));
                if selected <= 20_000 {
                    let idx = self.index.read().unwrap();
                    let total: u64 = self
                        .selected
                        .iter()
                        .filter_map(|i| idx.entries.get(*i as usize))
                        .filter(|e| !e.is_dir())
                        .map(|e| e.size)
                        .sum();
                    if total > 0 {
                        t.push_str(&format!("  \u{b7}  {}", human_size(total)));
                    }
                }
                t
            } else {
                format!("{} objects", thousands(self.ids.len() as u64))
            };
            ui.label(RichText::new(text).size(12.5).color(pal.text));
            if self.error.is_none() && self.millis > 0 {
                ui.label(RichText::new(format!("{} ms", self.millis)).size(12.0).color(pal.dim));
            }
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if self.progress.running.load(Ordering::Relaxed) {
                    let found = self.progress.found.load(Ordering::Relaxed);
                    ui.label(RichText::new(format!("Indexing  {} found", thousands(found))).size(12.0).color(pal.dim));
                    busy_bar(ui, &pal);
                } else if let Some((m, at)) = &self.message {
                    if at.elapsed() < Duration::from_secs(5) {
                        ui.label(RichText::new(m).size(12.0).color(pal.accent));
                    }
                }
            });
        });
    }
}

/// Small toggle button; accent-filled when on. Returns true when clicked.
fn chip(ui: &mut egui::Ui, pal: &Pal, label: &str, tip: &str, on: &mut bool) -> bool {
    let (fill, fg) = if *on { (pal.accent, pal.on_accent) } else { (Color32::TRANSPARENT, pal.dim) };
    let b = egui::Button::new(RichText::new(label).size(11.5).strong().color(fg))
        .fill(fill)
        .stroke(Stroke::NONE)
        .corner_radius(7)
        .min_size(vec2(0.0, 22.0));
    let clicked = ui.add(b).on_hover_text(tip).clicked();
    if clicked {
        *on = !*on;
    }
    clicked
}

/// Rounded filter button.
fn pill(ui: &mut egui::Ui, pal: &Pal, label: &str, active: bool) -> bool {
    let (fill, fg) = if active { (pal.accent, pal.on_accent) } else { (pal.raised, pal.dim) };
    let b = egui::Button::new(RichText::new(label).size(12.5).color(fg))
        .fill(fill)
        .stroke(Stroke::NONE)
        .corner_radius(14)
        .min_size(vec2(0.0, 26.0));
    ui.add(b).clicked()
}

fn magnifier(ui: &mut egui::Ui, color: Color32) {
    let (r, _) = ui.allocate_exact_size(vec2(18.0, 18.0), Sense::hover());
    let c = pos2(r.center().x - 1.5, r.center().y - 1.5);
    let p = ui.painter();
    p.circle_stroke(c, 5.5, Stroke::new(2.0_f32, color));
    p.line_segment([pos2(c.x + 4.0, c.y + 4.0), pos2(c.x + 8.0, c.y + 8.0)], Stroke::new(2.2_f32, color));
}

/// A small moving bar while the drives are being indexed.
fn busy_bar(ui: &mut egui::Ui, pal: &Pal) {
    let (r, _) = ui.allocate_exact_size(vec2(90.0, 4.0), Sense::hover());
    ui.painter().rect_filled(r, 2.0, pal.line);
    let t = ui.ctx().input(|i| i.time) as f32 * 0.9;
    let phase = 0.5 - 0.5 * (t * std::f32::consts::TAU).cos();
    let w = 30.0;
    let seg = Rect::from_min_size(pos2(r.left() + (r.width() - w) * phase, r.top()), vec2(w, 4.0));
    ui.painter().rect_filled(seg, 2.0, pal.accent);
}

