//! Search bar with option chips, filter pills and the status bar.

use super::App;
use crate::platform::{human_size, thousands};
use crate::theme::{self, Pal};
use eframe::egui::{self, pos2, vec2, Align, Color32, Layout, Rect, RichText, Sense, Stroke};
use std::sync::atomic::Ordering;
use std::time::Duration;

/// Pill label -> index into FILTERS.
const PILLS: [(&str, usize); 8] =
    [("All", 0), ("Folders", 5), ("Documents", 3), ("Pictures", 6), ("Audio", 1), ("Video", 7), ("Archives", 2), ("Apps", 4)];

impl App {
    pub(super) fn search_bar(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        let pal = theme::get(ctx);
        let mut changed = false;
        egui::Frame::new()
            .fill(pal.raised)
            .corner_radius(12)
            .stroke(Stroke::new(1.0_f32, pal.line))
            .inner_margin(egui::Margin::symmetric(14, 8))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    magnifier(ui, pal.accent);
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let o = &mut self.opts;
                        changed |= chip(ui, &pal, ".*", "Regular expressions (Ctrl+R)", &mut o.regex);
                        changed |= chip(ui, &pal, "\u{e9}", "Match accents (Ctrl+M)", &mut o.diacritics);
                        changed |= chip(ui, &pal, "Path", "Match full path (Ctrl+U)", &mut o.path);
                        changed |= chip(ui, &pal, "Word", "Match whole words (Ctrl+B)", &mut o.whole_word);
                        changed |= chip(ui, &pal, "Aa", "Match case (Ctrl+I)", &mut o.case);
                        if !self.query.is_empty() {
                            let x = egui::Button::new(RichText::new("\u{2715}").size(12.0).color(pal.dim)).frame(false);
                            if ui.add(x).on_hover_text("Clear").clicked() {
                                self.query.clear();
                                self.focus_search = true;
                            }
                        }
                        let edit = egui::TextEdit::singleline(&mut self.query)
                            .hint_text(RichText::new("Search files and folders...").color(pal.dim))
                            .font(egui::FontId::proportional(16.0))
                            .frame(false)
                            .desired_width(f32::INFINITY)
                            .margin(egui::Margin::symmetric(8, 2))
                            .id(egui::Id::new("search-box"));
                        let resp = ui.add(edit);
                        if self.focus_search {
                            resp.request_focus();
                            self.focus_search = false;
                        }
                        if resp.gained_focus() || resp.changed() {
                            self.results_focus = false;
                        }
                    });
                });
            });
        if changed {
            self.save_settings();
        }
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 6.0;
            for (label, idx) in PILLS {
                if pill(ui, &pal, label, self.filter == idx) {
                    self.filter = idx;
                }
            }
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                let icon = if self.settings.dark { "\u{2600}" } else { "\u{263E}" };
                let b = egui::Button::new(RichText::new(icon).size(15.0).color(pal.dim)).frame(false);
                if ui.add(b).on_hover_text("Switch between dark and light").clicked() {
                    self.settings.dark = !self.settings.dark;
                    theme::apply(ctx, self.settings.dark);
                    self.save_settings();
                }
                let on = self.settings.preview;
                if chip(ui, &pal, "Preview", "Show or hide the preview pane", &mut self.settings.preview) {
                    self.save_settings();
                }
                let _ = on;
            });
        });
    }

    pub(super) fn status(&self, ui: &mut egui::Ui) {
        let pal = theme::get(ui.ctx());
        ui.horizontal(|ui| {
            let selected = self.selected.len();
            let text = if let Some(err) = &self.error {
                err.clone()
            } else if selected == 1 && self.ids.len() == 1 {
                "1 of 1 objects selected".to_string()
            } else if selected > 0 {
                let mut t = format!("{} objects selected", thousands(selected as u64));
                if selected <= 20_000 {
                    let idx = self.index.read().unwrap();
                    let total: u64 = self
                        .selected
                        .iter()
                        .filter_map(|i| idx.entries.get(*i as usize))
                        .filter(|e| !e.is_dir())
                        .map(|e| e.size)
                        .sum();
                    if total > 0 {
                        t.push_str(&format!("  \u{b7}  {}", human_size(total)));
                    }
                }
                t
            } else {
                format!("{} objects", thousands(self.ids.len() as u64))
            };
            ui.label(RichText::new(text).size(12.5).color(pal.text));
            if self.error.is_none() && self.millis > 0 {
                ui.label(RichText::new(format!("{} ms", self.millis)).size(12.0).color(pal.dim));
            }
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if self.progress.running.load(Ordering::Relaxed) {
                    let found = self.progress.found.load(Ordering::Relaxed);
                    ui.label(RichText::new(format!("Indexing  {} found", thousands(found))).size(12.0).color(pal.dim));
                    busy_bar(ui, &pal);
                } else if let Some((m, at)) = &self.message {
                    if at.elapsed() < Duration::from_secs(5) {
                        ui.label(RichText::new(m).size(12.0).color(pal.accent));
                    }
                }
            });
        });
    }
}

/// Small toggle button; accent-filled when on. Returns true when clicked.
fn chip(ui: &mut egui::Ui, pal: &Pal, label: &str, tip: &str, on: &mut bool) -> bool {
    let (fill, fg) = if *on { (pal.accent, pal.on_accent) } else { (Color32::TRANSPARENT, pal.dim) };
    let b = egui::Button::new(RichText::new(label).size(11.5).strong().color(fg))
        .fill(fill)
        .stroke(Stroke::NONE)
        .corner_radius(7)
        .min_size(vec2(0.0, 22.0));
    let clicked = ui.add(b).on_hover_text(tip).clicked();
    if clicked {
        *on = !*on;
    }
    clicked
}

/// Rounded filter button.
fn pill(ui: &mut egui::Ui, pal: &Pal, label: &str, active: bool) -> bool {
    let (fill, fg) = if active { (pal.accent, pal.on_accent) } else { (pal.raised, pal.dim) };
    let b = egui::Button::new(RichText::new(label).size(12.5).color(fg))
        .fill(fill)
        .stroke(Stroke::NONE)
        .corner_radius(14)
        .min_size(vec2(0.0, 26.0));
    ui.add(b).clicked()
}

fn magnifier(ui: &mut egui::Ui, color: Color32) {
    let (r, _) = ui.allocate_exact_size(vec2(18.0, 18.0), Sense::hover());
    let c = pos2(r.center().x - 1.5, r.center().y - 1.5);
    let p = ui.painter();
    p.circle_stroke(c, 5.5, Stroke::new(2.0_f32, color));
    p.line_segment([pos2(c.x + 4.0, c.y + 4.0), pos2(c.x + 8.0, c.y + 8.0)], Stroke::new(2.2_f32, color));
}

/// A small moving bar while the drives are being indexed.
fn busy_bar(ui: &mut egui::Ui, pal: &Pal) {
    let (r, _) = ui.allocate_exact_size(vec2(90.0, 4.0), Sense::hover());
    ui.painter().rect_filled(r, 2.0, pal.line);
    let t = ui.ctx().input(|i| i.time) as f32 * 0.9;
    let phase = 0.5 - 0.5 * (t * std::f32::consts::TAU).cos();
    let w = 30.0;
    let seg = Rect::from_min_size(pos2(r.left() + (r.width() - w) * phase, r.top()), vec2(w, 4.0));
    ui.painter().rect_filled(seg, 2.0, pal.accent);
}

//! Preview pane and the Options, Rename and Delete windows.

use super::App;
use crate::platform::{open, open_path};
use crate::preview::Body;
use crate::scan;
use crate::startup::rebuild;
use crate::theme;
use eframe::egui::{self, vec2, Align2, Color32, RichText};
use std::time::Instant;

impl App {
    pub(super) fn preview_pane(&mut self, ui: &mut egui::Ui) {
        let pal = theme::get(ui.ctx());
        let Some(p) = &self.preview else {
            ui.vertical_centered(|ui| {
                ui.add_space(ui.available_height() * 0.35);
                ui.label(RichText::new("\u{1F50D}").size(30.0).color(pal.dim));
                ui.add_space(6.0);
                ui.label(RichText::new("Select a file to preview").color(pal.dim));
            });
            return;
        };
        egui::ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
            ui.label(RichText::new(&p.name).size(16.0).strong().color(pal.text));
            ui.label(RichText::new(&p.kind_label).size(12.0).color(pal.accent));
            ui.add_space(10.0);
            match &p.body {
                Body::Image(uri) => {
                    let w = ui.available_width();
                    ui.add(egui::Image::new(uri.as_str()).max_size(vec2(w, 260.0)).corner_radius(8));
                }
                Body::Text(t) => {
                    egui::Frame::new().fill(pal.raised).corner_radius(8).inner_margin(egui::Margin::same(10)).show(ui, |ui| {
                        ui.set_width(ui.available_width());
                        ui.add(egui::Label::new(RichText::new(t).monospace().size(11.5).color(pal.text)).wrap());
                    });
                }
                Body::Note(n) => {
                    ui.label(RichText::new(n).color(pal.dim));
                }
            }
            ui.add_space(12.0);
            egui::Grid::new("preview-info").num_columns(2).spacing([14.0, 6.0]).show(ui, |ui| {
                for (k, v) in &p.rows {
                    ui.label(RichText::new(*k).size(12.0).color(pal.dim));
                    ui.add(egui::Label::new(RichText::new(v).size(12.0).color(pal.text)).wrap());
                    ui.end_row();
                }
            });
            ui.add_space(14.0);
            ui.horizontal(|ui| {
                if ui.button("Open").clicked() {
                    open(&p.path);
                }
                if ui.button("Show in folder").clicked() {
                    open_path(&p.path);
                }
            });
        });
    }

    pub(super) fn dialogs(&mut self, ctx: &egui::Context) {
        self.options_window(ctx);
        self.rename_window(ctx);
        self.delete_window(ctx);
    }

    fn options_window(&mut self, ctx: &egui::Context) {
        if !self.show_options {
            return;
        }
        let pal = theme::get(ctx);
        let mut open = true;
        let mut changed = false;
        let mut rules_changed = false;
        let mut rebuild_now = false;
        egui::Window::new("Options").open(&mut open).collapsible(false).resizable(false).default_width(440.0).show(ctx, |ui| {
            ui.horizontal(|ui| {
                for (i, name) in ["General", "Indexing", "Columns"].iter().enumerate() {
                    ui.selectable_value(&mut self.opt_tab, i as u8, *name);
                }
            });
            ui.separator();
            match self.opt_tab {
                0 => {
                    ui.label(RichText::new("Appearance").strong());
                    ui.horizontal(|ui| {
                        changed |= ui.radio_value(&mut self.settings.dark, true, "Dark").changed();
                        changed |= ui.radio_value(&mut self.settings.dark, false, "Light").changed();
                    });
                    ui.horizontal(|ui| {
                        changed |= ui.radio_value(&mut self.settings.compact, false, "Comfortable rows").changed();
                        changed |= ui.radio_value(&mut self.settings.compact, true, "Compact rows").changed();
                    });
                    changed |= ui.checkbox(&mut self.settings.preview, "Show preview pane").changed();
                    changed |= ui.checkbox(&mut self.status_bar, "Show status bar").changed();
                    ui.add_space(8.0);
                    ui.label(RichText::new("Search defaults").strong());
                    let o = &mut self.opts;
                    changed |= ui.checkbox(&mut o.case, "Match case").changed();
                    changed |= ui.checkbox(&mut o.whole_word, "Match whole words").changed();
                    changed |= ui.checkbox(&mut o.path, "Match path").changed();
                    changed |= ui.checkbox(&mut o.diacritics, "Match accents").changed();
                    changed |= ui.checkbox(&mut o.regex, "Enable regex").changed();
                }
                1 => {
                    ui.label(RichText::new("Drives to index").strong());
                    for d in scan::fixed_drives() {
                        let mut on = !self.settings.drives_off.iter().any(|x| x.eq_ignore_ascii_case(&d));
                        if ui.checkbox(&mut on, &d).changed() {
                            self.settings.drives_off.retain(|x| !x.eq_ignore_ascii_case(&d));
                            if !on {
                                self.settings.drives_off.push(d.clone());
                            }
                            rules_changed = true;
                        }
                    }
                    ui.add_space(8.0);
                    ui.label(RichText::new("Excluded folders").strong());
                    ui.label(RichText::new("One per line: a folder name such as node_modules, or a full path.").size(12.0).color(pal.dim));
                    rules_changed |= ui
                        .add(egui::TextEdit::multiline(&mut self.settings.exclude).desired_rows(5).desired_width(f32::INFINITY))
                        .changed();
                    rules_changed |= ui.checkbox(&mut self.settings.hide_hidden, "Leave out hidden files and folders").changed();
                    rules_changed |= ui.checkbox(&mut self.settings.hide_system, "Leave out system files and folders").changed();
                    ui.add_space(8.0);
                    if ui.button("Apply and rebuild index").clicked() {
                        rebuild_now = true;
                    }
                    ui.label(RichText::new("Changes here take effect when the index is rebuilt.").size(12.0).color(pal.dim));
                }
                _ => {
                    let c = &mut self.columns;
                    ui.label(RichText::new("Show columns").strong());
                    changed |= ui.checkbox(&mut c.path, "Path").changed();
                    changed |= ui.checkbox(&mut c.size, "Size").changed();
                    changed |= ui.checkbox(&mut c.extension, "Extension").changed();
                    changed |= ui.checkbox(&mut c.modified, "Date Modified").changed();
                    changed |= ui.checkbox(&mut c.created, "Date Created").changed();
                    changed |= ui.checkbox(&mut c.attributes, "Attributes").changed();
                }
            }
        });
        self.show_options = open;
        if changed || rules_changed {
            theme::apply(ctx, self.settings.dark);
            self.settings.apply_rules();
            self.save_settings();
        }
        if rebuild_now {
            self.settings.apply_rules();
            self.save_settings();
            rebuild(self.index.clone(), self.progress.clone(), ctx.clone());
            self.message = Some(("Rebuilding the index...".into(), Instant::now()));
        }
    }

    fn rename_window(&mut self, ctx: &egui::Context) {
        let Some((id, mut text)) = self.rename.take() else { return };
        let (mut ok, mut cancel) = (false, ctx.input(|i| i.key_pressed(egui::Key::Escape)));
        egui::Window::new("Rename").collapsible(false).resizable(false).anchor(Align2::CENTER_CENTER, [0.0, 0.0]).show(ctx, |ui| {
            let r = ui.add(egui::TextEdit::singleline(&mut text).desired_width(340.0));
            if r.lost_focus() && ctx.input(|i| i.key_pressed(egui::Key::Enter)) {
                ok = true;
            } else if !r.has_focus() && !r.lost_focus() {
                r.request_focus();
            }
            ui.add_space(6.0);
            ui.horizontal(|ui| {
                ok |= ui.button("Rename").clicked();
                cancel |= ui.button("Cancel").clicked();
            });
        });
        if ok {
            let msg = match crate::actions::rename(&self.entry_text(id, 0), &text) {
                Ok(()) => "Renamed".to_string(),
                Err(e) => e,
            };
            self.message = Some((msg, Instant::now()));
        } else if !cancel {
            self.rename = Some((id, text));
        }
    }

    fn delete_window(&mut self, ctx: &egui::Context) {
        let Some(paths) = self.confirm_delete.take() else { return };
        let (mut yes, mut cancel) = (false, ctx.input(|i| i.key_pressed(egui::Key::Escape)));
        egui::Window::new("Delete").collapsible(false).resizable(false).anchor(Align2::CENTER_CENTER, [0.0, 0.0]).show(ctx, |ui| {
            ui.label(format!("Move {} item(s) to the Recycle Bin?", paths.len()));
            ui.add_space(4.0);
            for p in paths.iter().take(5) {
                ui.label(RichText::new(p).size(12.0).color(theme::get(ctx).dim));
            }
            if paths.len() > 5 {
                ui.label(format!("... and {} more", paths.len() - 5));
            }
            ui.add_space(8.0);
            ui.horizontal(|ui| {
                if ui.add(egui::Button::new(RichText::new("Delete").color(Color32::WHITE)).fill(Color32::from_rgb(200, 60, 70))).clicked() {
                    yes = true;
                }
                cancel |= ui.button("Cancel").clicked();
            });
        });
        if yes {
            let msg = match crate::actions::recycle(&paths) {
                Ok(()) => format!("Moved {} item(s) to the Recycle Bin", paths.len()),
                Err(e) => e,
            };
            self.message = Some((msg, Instant::now()));
            self.selected.clear();
        } else if !cancel {
            self.confirm_delete = Some(paths);
        }
    }
}

//! Menus and export of the main window.

use super::{App, APP_NAME};
use crate::bookmarks;
use crate::filters::FILTERS;
use crate::platform::thousands;
use crate::startup::rebuild;
use crate::theme;
use eframe::egui;
use std::time::Instant;

impl App {
    pub(super) fn menus(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        egui::menu::bar(ui, |ui| {
            ui.menu_button("File", |ui| {
                if ui.button("Export...").clicked() {
                    ui.close_menu();
                    self.export();
                }
                ui.separator();
                if ui.button("Exit").clicked() {
                    ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                }
            });
            ui.menu_button("Edit", |ui| {
                if ui.add(egui::Button::new("Copy Full Path").shortcut_text("Ctrl+C")).clicked() {
                    ctx.copy_text(self.selected_paths().join("\r\n"));
                    ui.close_menu();
                }
                if ui.add(egui::Button::new("Select All").shortcut_text("Ctrl+A")).clicked() {
                    self.selected = self.ids.iter().copied().collect();
                    ui.close_menu();
                }
                ui.separator();
                let first = self.first_selected();
                if ui.add_enabled(first.is_some(), egui::Button::new("Rename...").shortcut_text("F2")).clicked() {
                    if let Some(id) = first { self.start_rename(id); }
                    ui.close_menu();
                }
                if ui.add_enabled(first.is_some(), egui::Button::new("Delete").shortcut_text("Del")).clicked() {
                    if let Some(id) = first { self.start_delete(id); }
                    ui.close_menu();
                }
                if ui.add_enabled(first.is_some(), egui::Button::new("Properties").shortcut_text("Alt+Enter")).clicked() {
                    if let Some(id) = first { crate::actions::properties(&self.entry_text(id, 0)); }
                    ui.close_menu();
                }
            });
            ui.menu_button("View", |ui| {
                let mut ch = false;
                ch |= ui.checkbox(&mut self.columns.path, "Path").changed();
                ch |= ui.checkbox(&mut self.columns.size, "Size").changed();
                ch |= ui.checkbox(&mut self.columns.extension, "Extension").changed();
                ch |= ui.checkbox(&mut self.columns.modified, "Date Modified").changed();
                ch |= ui.checkbox(&mut self.columns.created, "Date Created").changed();
                ch |= ui.checkbox(&mut self.columns.attributes, "Attributes").changed();
                ui.separator();
                ch |= ui.checkbox(&mut self.settings.preview, "Preview Pane").changed();
                ch |= ui.checkbox(&mut self.status_bar, "Status Bar").changed();
                if ui.checkbox(&mut self.settings.dark, "Dark Theme").changed() {
                    theme::apply(ctx, self.settings.dark);
                    ch = true;
                }
                if ch {
                    self.save_settings();
                }
            });
            ui.menu_button("Search", |ui| {
                let mut ch = false;
                ch |= toggle(ui, &mut self.opts.case, "Match Case", "Ctrl+I");
                ch |= toggle(ui, &mut self.opts.whole_word, "Match Whole Words", "Ctrl+B");
                ch |= toggle(ui, &mut self.opts.path, "Match Path", "Ctrl+U");
                ch |= toggle(ui, &mut self.opts.diacritics, "Match Diacritics", "Ctrl+M");
                ui.separator();
                ch |= toggle(ui, &mut self.opts.regex, "Enable Regex", "Ctrl+R");
                ui.separator();
                for (i, (name, _)) in FILTERS.iter().enumerate() {
                    if ui.radio(self.filter == i, *name).clicked() {
                        self.filter = i;
                        ui.close_menu();
                    }
                }
                if ch {
                    self.save_settings();
                }
            });
            let fname = FILTERS[self.filter].0;
            if let Some(b) = bookmarks::menu(ui, &mut self.bookmarks, &self.query, self.filter, fname) {
                self.query = b.query;
                self.filter = b.filter;
                self.focus_search = true;
            }
            ui.menu_button("Tools", |ui| {
                if ui.button("Options...").clicked() {
                    self.show_options = true;
                    ui.close_menu();
                }
                if ui.button("Rebuild Index").clicked() {
                    ui.close_menu();
                    rebuild(self.index.clone(), self.progress.clone(), ctx.clone());
                }
            });
            ui.menu_button("Help", |ui| {
                if ui.button("Search Syntax").clicked() {
                    self.show_help = true;
                    ui.close_menu();
                }
                if ui.button(format!("About {APP_NAME}")).clicked() {
                    self.show_about = true;
                    ui.close_menu();
                }
            });
        });
    }

    pub(super) fn export(&mut self) {
        let Some(path) = rfd::FileDialog::new()
            .set_file_name("results.efu")
            .add_filter("File List", &["efu", "csv"])
            .save_file()
        else {
            return;
        };
        let idx = self.index.read().unwrap();
        let mut out = String::from("Filename,Size,Date Modified,Date Created,Attributes\r\n");
        for &i in &self.ids {
            let Some(e) = idx.entries.get(i as usize) else { continue };
            let size = if e.is_dir() { String::new() } else { e.size.to_string() };
            out.push_str(&format!("\"{}\",{},{},{},{}\r\n", idx.full_path(e).replace('"', "\"\""), size, e.mtime, e.ctime, e.attrs));
        }
        let msg = match std::fs::write(&path, out) {
            Ok(_) => format!("Exported {} results", thousands(self.ids.len() as u64)),
            Err(e) => format!("Export failed: {e}"),
        };
        self.message = Some((msg, Instant::now()));
    }
}

/// A checkable menu entry. Returns true when it was flipped.
fn toggle(ui: &mut egui::Ui, v: &mut bool, label: &str, shortcut: &str) -> bool {
    let text = if *v { format!("\u{2714}  {label}") } else { format!("     {label}") };
    if ui.add(egui::Button::new(text).shortcut_text(shortcut)).clicked() {
        *v = !*v;
        ui.close_menu();
        return true;
    }
    false
}

