//! Real Windows file icons, fetched once per file type and kept as textures.

use eframe::egui::{self, ColorImage, TextureHandle, TextureOptions};
use std::collections::HashMap;

#[derive(Default)]
pub struct IconCache {
    map: HashMap<String, Option<TextureHandle>>,
}

impl IconCache {
    /// The icon for a file extension (lower-case) or "<dir>" for folders; None when unavailable.
    pub fn get(&mut self, ctx: &egui::Context, key: &str) -> Option<TextureHandle> {
        if let Some(t) = self.map.get(key) {
            return t.clone();
        }
        let tex = load(key).map(|img| ctx.load_texture(format!("icon-{key}"), img, TextureOptions::LINEAR));
        self.map.insert(key.to_string(), tex.clone());
        tex
    }
}

#[cfg(windows)]
fn load(key: &str) -> Option<ColorImage> {
    use windows_sys::Win32::Graphics::Gdi::{
        DeleteObject, GetDC, GetDIBits, GetObjectW, ReleaseDC, BITMAP, BITMAPINFO, BITMAPINFOHEADER, BI_RGB, DIB_RGB_COLORS,
    };
    use windows_sys::Win32::Storage::FileSystem::{FILE_ATTRIBUTE_DIRECTORY, FILE_ATTRIBUTE_NORMAL};
    use windows_sys::Win32::UI::Shell::{SHGetFileInfoW, SHFILEINFOW, SHGFI_ICON, SHGFI_SMALLICON, SHGFI_USEFILEATTRIBUTES};
    use windows_sys::Win32::UI::WindowsAndMessaging::{DestroyIcon, GetIconInfo, ICONINFO};

    let (name, attr) = if key == "<dir>" {
        ("folder".to_string(), FILE_ATTRIBUTE_DIRECTORY)
    } else {
        (format!("file.{key}"), FILE_ATTRIBUTE_NORMAL)
    };
    let wide: Vec<u16> = name.encode_utf16().chain([0]).collect();
    unsafe {
        let mut info: SHFILEINFOW = std::mem::zeroed();
        let r = SHGetFileInfoW(
            wide.as_ptr(),
            attr,
            &mut info,
            std::mem::size_of::<SHFILEINFOW>() as u32,
            SHGFI_ICON | SHGFI_SMALLICON | SHGFI_USEFILEATTRIBUTES,
        );
        if r == 0 || info.hIcon.is_null() {
            return None;
        }
        let mut ii: ICONINFO = std::mem::zeroed();
        if GetIconInfo(info.hIcon, &mut ii) == 0 {
            DestroyIcon(info.hIcon);
            return None;
        }
        let mut bm: BITMAP = std::mem::zeroed();
        GetObjectW(ii.hbmColor, std::mem::size_of::<BITMAP>() as i32, &mut bm as *mut _ as *mut _);
        let (w, h) = (bm.bmWidth.max(0) as usize, bm.bmHeight.max(0) as usize);
        let mut out = None;
        if w > 0 && h > 0 {
            let mut bmi: BITMAPINFO = std::mem::zeroed();
            bmi.bmiHeader.biSize = std::mem::size_of::<BITMAPINFOHEADER>() as u32;
            bmi.bmiHeader.biWidth = w as i32;
            bmi.bmiHeader.biHeight = -(h as i32); // top-down
            bmi.bmiHeader.biPlanes = 1;
            bmi.bmiHeader.biBitCount = 32;
            bmi.bmiHeader.biCompression = BI_RGB;
            let mut buf = vec![0u8; w * h * 4];
            let dc = GetDC(std::ptr::null_mut());
            let got = GetDIBits(dc, ii.hbmColor, 0, h as u32, buf.as_mut_ptr() as *mut _, &mut bmi, DIB_RGB_COLORS);
            ReleaseDC(std::ptr::null_mut(), dc);
            if got != 0 {
                let opaque_missing = buf.chunks(4).all(|p| p[3] == 0);
                for p in buf.chunks_mut(4) {
                    p.swap(0, 2); // BGRA -> RGBA
                    if opaque_missing {
                        p[3] = if p[0] == 0 && p[1] == 0 && p[2] == 0 { 0 } else { 255 };
                    }
                }
                out = Some(ColorImage::from_rgba_unmultiplied([w, h], &buf));
            }
        }
        DeleteObject(ii.hbmColor);
        DeleteObject(ii.hbmMask);
        DestroyIcon(info.hIcon);
        out
    }
}

#[cfg(not(windows))]
fn load(_key: &str) -> Option<ColorImage> {
    None
}

//! Notification-area (tray) icon and the Ctrl+Alt+Space hotkey, on one hidden message window.

use std::sync::atomic::{AtomicBool, AtomicIsize, Ordering};
use std::sync::OnceLock;

#[derive(Clone, Copy)]
pub enum Event {
    Show,
    Exit,
}

static CALLBACK: OnceLock<Box<dyn Fn(Event) + Send + Sync>> = OnceLock::new();
static HWND_SAVED: AtomicIsize = AtomicIsize::new(0);
static EXIT: AtomicBool = AtomicBool::new(false);

/// True once (after "Exit" was chosen in the tray menu).
pub fn take_exit() -> bool {
    EXIT.swap(false, Ordering::SeqCst)
}

#[cfg(windows)]
pub fn start(on_event: impl Fn(Event) + Send + Sync + 'static) {
    let _ = CALLBACK.set(Box::new(on_event));
    std::thread::spawn(|| unsafe { run() });
}

#[cfg(not(windows))]
pub fn start(_on_event: impl Fn(Event) + Send + Sync + 'static) {}

/// Take the icon out of the tray (call when the program exits).
pub fn remove() {
    #[cfg(windows)]
    unsafe {
        use windows_sys::Win32::UI::Shell::{Shell_NotifyIconW, NIM_DELETE, NOTIFYICONDATAW};
        let h = HWND_SAVED.load(Ordering::SeqCst);
        if h != 0 {
            let mut nid: NOTIFYICONDATAW = std::mem::zeroed();
            nid.cbSize = std::mem::size_of::<NOTIFYICONDATAW>() as u32;
            nid.hWnd = h as _;
            nid.uID = 1;
            Shell_NotifyIconW(NIM_DELETE, &nid);
        }
    }
}

#[cfg(windows)]
const WM_TRAY: u32 = 0x8000 + 1; // WM_APP + 1

#[cfg(windows)]
unsafe extern "system" fn wndproc(
    hwnd: windows_sys::Win32::Foundation::HWND,
    msg: u32,
    wp: windows_sys::Win32::Foundation::WPARAM,
    lp: windows_sys::Win32::Foundation::LPARAM,
) -> windows_sys::Win32::Foundation::LRESULT {
    use windows_sys::Win32::Foundation::POINT;
    use windows_sys::Win32::UI::WindowsAndMessaging::*;
    let fire = |e: Event| {
        if let Some(cb) = CALLBACK.get() {
            cb(e);
        }
    };
    match msg {
        WM_HOTKEY => fire(Event::Show),
        WM_TRAY => match (lp & 0xFFFF) as u32 {
            WM_LBUTTONUP => fire(Event::Show),
            WM_RBUTTONUP => {
                let menu = CreatePopupMenu();
                let show: Vec<u16> = "Show Quickfind".encode_utf16().chain([0]).collect();
                let exit: Vec<u16> = "Exit".encode_utf16().chain([0]).collect();
                AppendMenuW(menu, MF_STRING, 1, show.as_ptr());
                AppendMenuW(menu, MF_STRING, 2, exit.as_ptr());
                let mut pt: POINT = std::mem::zeroed();
                GetCursorPos(&mut pt);
                SetForegroundWindow(hwnd);
                let cmd = TrackPopupMenu(menu, TPM_RETURNCMD | TPM_RIGHTBUTTON, pt.x, pt.y, 0, hwnd, std::ptr::null());
                DestroyMenu(menu);
                match cmd {
                    1 => fire(Event::Show),
                    2 => {
                        EXIT.store(true, Ordering::SeqCst);
                        fire(Event::Exit);
                    }
                    _ => {}
                }
            }
            _ => {}
        },
        _ => return DefWindowProcW(hwnd, msg, wp, lp),
    }
    0
}

#[cfg(windows)]
unsafe fn run() {
    use windows_sys::Win32::System::LibraryLoader::GetModuleHandleW;
    use windows_sys::Win32::UI::Input::KeyboardAndMouse::{RegisterHotKey, MOD_ALT, MOD_CONTROL, MOD_NOREPEAT, VK_SPACE};
    use windows_sys::Win32::UI::Shell::{Shell_NotifyIconW, NIF_ICON, NIF_MESSAGE, NIF_TIP, NIM_ADD, NOTIFYICONDATAW};
    use windows_sys::Win32::UI::WindowsAndMessaging::*;

    let hinst = GetModuleHandleW(std::ptr::null());
    let class: Vec<u16> = "QuickfindTray".encode_utf16().chain([0]).collect();
    let mut wc: WNDCLASSW = std::mem::zeroed();
    wc.lpfnWndProc = Some(wndproc);
    wc.hInstance = hinst;
    wc.lpszClassName = class.as_ptr();
    RegisterClassW(&wc);
    let hwnd = CreateWindowExW(0, class.as_ptr(), class.as_ptr(), 0, 0, 0, 0, 0, HWND_MESSAGE, std::ptr::null_mut(), hinst, std::ptr::null());
    if hwnd.is_null() {
        return;
    }
    HWND_SAVED.store(hwnd as isize, Ordering::SeqCst);
    RegisterHotKey(hwnd, 1, MOD_CONTROL | MOD_ALT | MOD_NOREPEAT, VK_SPACE as u32);

    let mut nid: NOTIFYICONDATAW = std::mem::zeroed();
    nid.cbSize = std::mem::size_of::<NOTIFYICONDATAW>() as u32;
    nid.hWnd = hwnd;
    nid.uID = 1;
    nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_TRAY;
    nid.hIcon = LoadIconW(std::ptr::null_mut(), IDI_APPLICATION);
    for (i, c) in "Quickfind  (Ctrl+Alt+Space)".encode_utf16().enumerate().take(127) {
        nid.szTip[i] = c;
    }
    Shell_NotifyIconW(NIM_ADD, &nid);

    let mut msg: MSG = std::mem::zeroed();
    while GetMessageW(&mut msg, std::ptr::null_mut(), 0, 0) > 0 {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }
}

