    public string BadgeCategory
    {
        get
        {
            if (IsDirectory) return "folders";
            return Kind switch
            {
                FileKind.Picture => "pictures",
                FileKind.Document => "documents",
                FileKind.Audio => "audio",
                FileKind.Video => "video",
                FileKind.Archive => "archives",
                FileKind.Exe => "apps",
                _ => "other"
            };
        }
    }

