    {
        get
        {
            if (IsDirectory) return "";
            if (string.IsNullOrWhiteSpace(Extension)) return "FILE";
            var e = Extension.TrimStart('.').ToUpperInvariant();
            return e.Length <= 4 ? e : e[..4];
        }
    }

