    /// <summary>Exact file names always skipped (lowercase).</summary>
    static readonly string[] FileNames =
    [
        "thumbs.db",
        "desktop.ini",
        ".ds_store",
    ];

    public static bool ShouldSkipName(ReadOnlySpan<char> name, bool isDir)
    {
        if (!Enabled || name.IsEmpty) return false;

        // Office lock / temp: ~$Report.docx, ~WRL0001.tmp
        if (name.Length >= 2 && name[0] == '~' && (name[1] == '$' || name[1] == '~'))
            return true;

        // Transient NSIS / installer dirs often named ~NSU1.tmp, ~PC, etc. — keep short ~* only when temp-like
        if (!isDir && name.StartsWith("~$", StringComparison.Ordinal))
            return true;

        var folded = FoldName(name);
        if (!isDir)
        {
            foreach (var f in FileNames)
                if (folded.Equals(f, StringComparison.Ordinal)) return true;
        }
        else
        {
            foreach (var d in DirNames)
                if (folded.Equals(d, StringComparison.Ordinal)) return true;
        }
        return false;
    }

    public static bool ShouldSkipPath(string fullPath)
    {
        if (!Enabled || string.IsNullOrEmpty(fullPath)) return false;
        var fold = fullPath.ToLowerInvariant().Replace('/', '\\');
        if (!fold.EndsWith('\\')) fold += "\\";

        // Ensure drive-root $Recycle.Bin matches
        foreach (var frag in PathFragments)
        {
            if (fold.Contains(frag, StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    public static bool ShouldSkip(string parentOrFullPath, string name, bool isDir)
    {
        if (!Enabled) return false;
        if (ShouldSkipName(name.AsSpan(), isDir)) return true;
        var full = string.IsNullOrEmpty(parentOrFullPath)
            ? name
            : TextNorm.Join(parentOrFullPath, name);
        return ShouldSkipPath(full) || (isDir && ShouldSkipPath(full + "\\"));
    }

    public static bool ShouldSkipEntry(FileIndex idx, in Entry e)
    {
        if (!Enabled || e.Deleted) return false;
        var name = idx.Name(e);
        if (ShouldSkipName(name.AsSpan(), e.IsDir)) return true;
        var full = idx.FullPath(e);
        return ShouldSkipPath(full) || (e.IsDir && ShouldSkipPath(full + "\\"));
    }

    /// <summary>Mark junk entries deleted in an existing index (search hides them; next save shrinks).</summary>
    public static int Prune(FileIndex idx)
    {
        if (!Enabled) return 0;
        var n = 0;
        for (var i = 0; i < idx.Entries.Count; i++)
        {
            var e = idx.Entries[i];
            if (e.Deleted) continue;
            if (!ShouldSkipEntry(idx, e)) continue;
            e.Deleted = true;
            idx.Entries[i] = e;
            n++;
        }
        if (n > 0) idx.Generation++;
        return n;
    }

    static string FoldName(ReadOnlySpan<char> name)
    {
        // Fast ASCII lower for exclusion compares
        Span<char> buf = name.Length <= 256 ? stackalloc char[name.Length] : new char[name.Length];
        for (var i = 0; i < name.Length; i++)
        {
            var c = name[i];
            buf[i] = c is >= 'A' and <= 'Z' ? (char)(c + 32) : c;
        }
        return new string(buf);
    }
}
