/// Load the saved index/pub fn setup_style(ctx: &egui::Context, dark: bool, accent: &str) {
    use egui::{FontData, FontFamily};
    let mut fonts = egui::FontDefinitions::default();
    let add = |fonts: &mut egui::FontDefinitions, name: &str, bytes: &\x27static [u8]| {
        fonts.font_data.insert(name.into(), Arc::new(FontData::from_static(bytes)));
    };
    add(&mut fonts, "is-regular", include_bytes!("../assets/fonts/InstrumentSans-Regular.ttf"));
    add(&mut fonts, "is-medium", include_bytes!("../assets/fonts/InstrumentSans-Medium.ttf"));
    add(&mut fonts, "is-semibold", include_bytes!("../assets/fonts/InstrumentSans-SemiBold.ttf"));
    add(&mut fonts, "is-bold", include_bytes!("../assets/fonts/InstrumentSans-Bold.ttf"));
    add(&mut fonts, "jbmono", include_bytes!("../assets/fonts/JetBrainsMono-Regular.ttf"));
    // System fonts fill in glyphs the bundled fonts lack, and supply the icon font.
    let windir = PathBuf::from(std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into())).join("Fonts");
    let mut fallback: Vec<String> = Vec::new();
    for (name, file) in [("segoeui", "segoeui.ttf"), ("seguisym", "seguisym.ttf")] {
        if let Ok(bytes) = std::fs::read(windir.join(file)) {
            fonts.font_data.insert(name.into(), Arc::new(FontData::from_owned(bytes)));
            fallback.push(name.into());
        }
    }
    let has_icons = match std::fs::read(windir.join("segmdl2.ttf")) {
        Ok(bytes) => {
            fonts.font_data.insert("mdl2".into(), Arc::new(FontData::from_owned(bytes)));
            true
        }
        Err(_) => false,
    };
    let family = |first: &str| {
        let mut v = vec![first.to_string()];
        v.extend(fallback.iter().cloned());
        v
