const JUNK_DIRS: [&str; 12] = [
    "$recycle.bin", "system volume information", "recovery", "node_modules", ".git", ".svn", ".hg", ".cache",
    "__pycache__", ".nuget", "inetcache", "temporary internet files",
];
const JUNK_FILES: [&str; 3] = ["thumbs.db", "desktop.ini", ".ds_store"];
const JUNK_PATHS: [&str; 20] = [
    "\\windows\\winsxs\\", "\\windows\\installer\\", "\\windows\\servicing\\", "\\windows\\softwaredistribution\\",
    "\\windows\\assembly\\", "\\appdata\\local\\temp\\", "\\appdata\\local\\microsoft\\windows\\inetcache\\",
    "\\appdata\\local\\microsoft\\windows\\webcache\\", "\\appdata\\local\\microsoft\\windows\\notifications\\",
    "\\appdata\\local\\packages\\", "\\appdata\\local\\pip\\cache\\", "\\appdata\\local\\npm-cache\\",
    "\\appdata\\local\\yarn\\", "\\appdata\\local\\pnpm-store\\", "\\appdata\\local\\docker\\",
    "\\appdata\\local\\crashdumps\\", "\\appdata\\roaming\\code\\cache\\", "\\appdata\\roaming\\code\\cacheddata\\",
    "\\appdata\\roaming\\cursor\\cache\\", "\\appdata\\roaming\\cursor\\cacheddata\\",
];

/// Junk filter (same lists as OmniFind): lock files, caches, VCS folders, Recycle Bin ...
fn is_junk(dir: &str, name: &str, is_dir: bool) -> bool {
    if name.starts_with("~$") || name.starts_with("~~") {
        return true;
    }
    let lname = name.to_ascii_lowercase();
    if is_dir {
        if JUNK_DIRS.contains(&lname.as_str()) {
            return true;
        }
        let full = format!("{}\\{}\\", dir.to_ascii_lowercase(), lname);
        return JUNK_PATHS.iter().any(|p| full.contains(p));
    }
    JUNK_FILES.contains(&lname.as_str())
}
EOF
