    }
    let page = Rect::from_min_max(rect.min + Vec2::new(2.5, 0.5), rect.max - Vec2::new(2.5, 0.5));
    let (fill, edge) = if pal.dark { (Color32::from_rgb(52, 56, 70), Color32::from_rgb(86, 92, 112)) } else { (Color32::WHITE, Color32::from_gray(170)) };
