    };
    if let Some(c) = band {
        let b = Rect::from_min_max(page.left_bottom() + Vec2::new(1.5, -5.5), page.right_bottom() - Vec2::new(1.5, 1.5));
        p.rect_filled(b, 1.5, c);
    }
