            if widgets::action(ui, &pal, "Show in folder", Some(w)).clicked() {
                open_path(&path);
            }
            ui.add_space(8.0);
            let label = if self.copied_path { "Copied" } else { "Copy path" };
            if widgets::action(ui, &pal, label, Some(w)).clicked() {
                ui.ctx().copy_text(path.clone());
